// A diagram laid out: its marks in the order they are drawn, its size, and the faces its text was measured in.
// Ported from Parcel NExT's Divooka.Visualization.Dhole/Rendering/Scene.cs.

import type { LineStyle } from "../syntax/scan";
import { RectF, translation, rotationDegrees, type Vec2, type VectorPath } from "./geometry";
import type { Tone } from "./tones";
import { FontWeights, layoutText, type FontWeight, type ParagraphAlignment, type TextLayout, type TextMeasurer } from "../plot/text";
import type { Theme } from "../plot/theme";
import type { Sink, Paint } from "../plot/sink";
import { DrawingLayer, type DrawingContext } from "../plot/figure";

/** A shape: filled, outlined, or both. */
export interface ShapeMark {
  readonly type: "shape";
  /** Its outline, in the diagram's pixels. */
  readonly path: VectorPath;
  /** What it is filled with, or null. */
  readonly fill: Tone | null;
  /** What it is outlined with, or null. */
  readonly stroke: Tone | null;
  /** The outline's width. */
  readonly width: number;
  /** How the outline is drawn. */
  readonly line: LineStyle;
}

/** A block of text, already broken into lines at layout. */
export interface TextMark {
  readonly type: "text";
  readonly text: string;
  /** The block's left edge. */
  readonly x: number;
  /** The block's top edge. */
  readonly y: number;
  /** How wide the block was measured. */
  readonly width: number;
  /** How tall the block was measured. */
  readonly height: number;
  /** The width the lines are set in - the widest line, so each lines up within the block - or infinity for text on one line. */
  readonly measure: number;
  /** The font size, in pixels. */
  readonly size: number;
  readonly weight: FontWeight;
  readonly colour: Tone;
  readonly align: ParagraphAlignment;
  readonly italic: boolean;
  /** Degrees the block is turned through, clockwise about its centre: -90 reads up the page. */
  readonly rotation: number;
}

export type Mark = ShapeMark | TextMark;

/** A shape mark. */
export function shapeMark(path: VectorPath, fill: Tone | null, stroke: Tone | null, width = 1, line: LineStyle = "solid"): ShapeMark {
  return { type: "shape", path, fill, stroke, width, line };
}

/** The rectangle a text block covers, as it was measured - turned with it when it is turned a quarter. */
export function textBounds(text: TextMark): RectF {
  return Math.abs(Math.abs(text.rotation) - 90) < 1
    ? RectF.fromXYWH(text.x + text.width / 2 - text.height / 2, text.y + text.height / 2 - text.width / 2, text.height, text.width)
    : RectF.fromXYWH(text.x, text.y, text.width, text.height);
}

/** A laid-out diagram: its marks in the order they are drawn, its size, and the faces its text was measured in. */
export class Scene {
  /** The faces the text was measured in, and is drawn in whatever the figure's theme says, so it fits where it was laid out. */
  readonly fontFamilies: readonly string[];
  readonly marks: Mark[] = [];
  width = 0;
  height = 0;

  constructor(fontFamilies: readonly string[]) {
    this.fontFamilies = fontFamilies;
  }

  add(mark: Mark): void {
    this.marks.push(mark);
  }
  get texts(): TextMark[] {
    return this.marks.filter((m): m is TextMark => m.type === "text");
  }
  get shapes(): ShapeMark[] {
    return this.marks.filter((m): m is ShapeMark => m.type === "shape");
  }

  /** Every mark moved by (dx, dy). */
  offset(dx: number, dy: number): void {
    const move = translation(dx, dy);
    for (let i = 0; i < this.marks.length; i++) {
      const mark = this.marks[i];
      this.marks[i] = mark.type === "shape" ? { ...mark, path: mark.path.transformed(move) } : { ...mark, x: mark.x + dx, y: mark.y + dy };
    }
  }

  /** The rectangle every mark lies in. */
  bounds(): RectF {
    let left = Number.MAX_VALUE;
    let top = Number.MAX_VALUE;
    let right = -Number.MAX_VALUE;
    let bottom = -Number.MAX_VALUE;
    for (const mark of this.marks) {
      const box = mark.type === "shape" ? mark.path.tightBounds().inflate(mark.stroke !== null ? mark.width / 2 : 0) : textBounds(mark);
      if (box.width <= 0 && box.height <= 0) continue;
      left = Math.min(left, box.left);
      top = Math.min(top, box.top);
      right = Math.max(right, box.right);
      bottom = Math.max(bottom, box.bottom);
    }
    return left > right ? new RectF(0, 0, 0, 0) : new RectF(left, top, right, bottom);
  }

  /** Moves every mark so the scene starts at `margin` from its top left, and sizes it to end the same distance from its bottom right; how far everything moved, for a layout that keeps positions of its own beside the marks. */
  frame(margin: number): Vec2 {
    const b = this.bounds();
    const moved = { x: margin - b.left, y: margin - b.top };
    this.offset(moved.x, moved.y);
    this.width = Math.ceil(b.width + 2 * margin);
    this.height = Math.ceil(b.height + 2 * margin);
    return moved;
  }
}

/** The width and height a block of text takes. */
export interface SizeF {
  readonly width: number;
  readonly height: number;
}

/**
 * Measures and lays out every word of a diagram in one set of faces, so what is measured at layout is exactly what is drawn.
 */
export class TextSetter {
  readonly families: readonly string[];
  readonly measurer: TextMeasurer;
  private readonly cache = new Map<string, TextLayout>();

  constructor(families: readonly string[], measurer: TextMeasurer) {
    this.families = families;
    this.measurer = measurer;
  }

  /** The block laid out, its lines broken to fit `maxWidth`. */
  layout(text: string, size: number, weight: FontWeight, maxWidth = Number.POSITIVE_INFINITY, italic = false, align: ParagraphAlignment = "left"): TextLayout {
    text ??= "";
    const key = `${size}|${weight}|${maxWidth}|${italic}|${align}|${text}`;
    const cached = this.cache.get(key);
    if (cached) return cached;
    const laid = layoutText(this.measurer, text, { families: this.families, size, weight, italic }, maxWidth, align);
    if (this.cache.size > 4096) this.cache.clear();
    this.cache.set(key, laid);
    return laid;
  }

  /** The width and height a block takes, its lines broken to fit `maxWidth`. */
  measure(text: string, size: number, weight: FontWeight, maxWidth = Number.POSITIVE_INFINITY, italic = false): SizeF {
    if (!text) return { width: 0, height: this.layout(" ", size, weight).height };
    const laid = this.layout(text, size, weight, maxWidth, italic);
    return { width: laid.width, height: laid.height };
  }

  /** A text mark for `text`, its lines broken to fit `maxWidth` and aligned within the widest of them, with its top left at (x, y). */
  mark(text: string, x: number, y: number, size: number, weight: FontWeight, colour: Tone, maxWidth = Number.POSITIVE_INFINITY, align: ParagraphAlignment = "left", italic = false): TextMark {
    const measured = this.measure(text, size, weight, maxWidth, italic);
    // Set again in exactly the widest line's width, the lines break where they broke and each lines up within the block.
    const measure = Number.isFinite(maxWidth) || align !== "left" ? measured.width : Number.POSITIVE_INFINITY;
    return { type: "text", text, x, y, width: measured.width, height: measured.height, measure, size, weight, colour, align, italic, rotation: 0 };
  }

  /** A text mark whose block is centred on (cx, cy). */
  centred(text: string, cx: number, cy: number, size: number, weight: FontWeight, colour: Tone, maxWidth = Number.POSITIVE_INFINITY, italic = false): TextMark {
    const measured = this.measure(text, size, weight, maxWidth, italic);
    return this.mark(text, cx - measured.width / 2, cy - measured.height / 2, size, weight, colour, maxWidth, "center", italic);
  }
}

/** A setter for a theme's faces, measuring with `measurer`. */
export function setterFor(theme: Theme, measurer: TextMeasurer): TextSetter {
  return new TextSetter(theme.fontFamilies, measurer);
}

export { FontWeights };

function strokePaint(colour: ReturnType<Tone["in"]>, width: number, line: LineStyle): Paint {
  const dashUnit = Math.max(1, width * 0.8);
  return {
    colour,
    style: "stroke",
    strokeWidth: line === "thick" ? width * 2.2 : width,
    cap: "butt",
    join: "round",
    dash: line === "dashed" ? [5 * dashUnit, 4 * dashUnit] : undefined,
  };
}

/** A laid-out diagram as a layer of the plotting framework: it reaches every output a chart reaches, and takes its colours from the figure's theme as it is drawn. */
export class DiagramLayer extends DrawingLayer {
  readonly scene: Scene;
  readonly kindName: string;
  private readonly measurer: TextMeasurer;

  constructor(scene: Scene, kindName: string, measurer: TextMeasurer) {
    super();
    this.scene = scene;
    this.kindName = kindName;
    this.measurer = measurer;
  }

  get width(): number {
    return this.scene.width;
  }
  get height(): number {
    return this.scene.height;
  }
  override get kind(): string {
    return this.kindName;
  }

  protected draw(context: DrawingContext): void {
    const sink: Sink = context.sink;
    const theme = context.theme;
    const setter = new TextSetter(this.scene.fontFamilies, this.measurer);
    for (const mark of this.scene.marks) {
      if (mark.type === "shape") {
        if (mark.fill) sink.drawPath(mark.path, { colour: mark.fill.in(theme), style: "fill" });
        if (mark.stroke && mark.width > 0) sink.drawPath(mark.path, strokePaint(mark.stroke.in(theme), mark.width, mark.line));
        continue;
      }
      const laid = setter.layout(mark.text, mark.size, mark.weight, Number.isFinite(mark.measure) ? mark.measure + 0.5 : Number.POSITIVE_INFINITY, mark.italic, mark.align);
      if (mark.rotation === 0) {
        sink.drawText(laid, mark.x, mark.y, mark.colour.in(theme));
        continue;
      }
      const saved = sink.save();
      try {
        sink.concat(rotationDegrees(mark.rotation, mark.x + mark.width / 2, mark.y + mark.height / 2));
        sink.drawText(laid, mark.x, mark.y, mark.colour.in(theme));
      } finally {
        sink.restoreToCount(saved);
      }
    }
  }
}
