// The pieces every line of Dhole is cut into: names in quotation marks, attributes in brackets, a label after a colon, arrows between names, lists between commas, and the values a setting takes.
// Ported from Parcel NExT's Divooka.Visualization.Dhole/Syntax/Scan.cs.

import { isWhiteSpace, type Span } from "./source";
import type { ProblemList } from "./problems";

/** How a line between two things is drawn. */
export type LineStyle = "solid" | "dashed" | "thick";

/** What an end of a line carries: nothing, a filled arrowhead, a hollow triangle (inheritance), a filled diamond (composition) or a hollow one (aggregation). */
export type Head = "none" | "arrow" | "triangle" | "diamond" | "hollowDiamond";

/** One way of writing an arrow, and what it draws. `spaced`: the arrow is only an arrow with a space on each side - true for the arrows that could be part of a name, such as -- or o-. */
export interface ArrowForm {
  readonly token: string;
  readonly line: LineStyle;
  readonly tail: Head;
  readonly tip: Head;
  readonly spaced: boolean;
}

function form(token: string, line: LineStyle, tail: Head, tip: Head, spaced = false): ArrowForm {
  return { token, line, tail, tip, spaced };
}

/** An arrow found in a line. */
export interface Arrow {
  readonly token: Span;
  readonly form: ArrowForm;
  readonly tailCard?: string | null;
  readonly tipCard?: string | null;
}

/** The arrows one kind of diagram has. */
export class ArrowSet {
  readonly forms: readonly ArrowForm[];
  /** Whether a line with a cardinality at each end - 1-* - is an arrow here. */
  readonly cardinalities: boolean;

  constructor(forms: Iterable<ArrowForm>, cardinalities = false) {
    // Longest first, so --> is never read as -- followed by >. Stable, as .NET's OrderByDescending is.
    this.forms = [...forms].map((f, i) => ({ f, i })).sort((a, b) => b.f.token.length - a.f.token.length || a.i - b.i).map((e) => e.f);
    this.cardinalities = cardinalities;
  }

  /** The arrows, as a person would read them in a hint. */
  get names(): string[] {
    const tokens: string[] = [];
    for (const f of this.forms) if (!tokens.includes(f.token)) tokens.push(f.token);
    return this.cardinalities ? [...tokens, "1-*", "0..1-1"] : tokens;
  }

  /** The plain arrows every diagram of boxes and lines has. */
  static readonly plain = new ArrowSet(plainForms());

  /** A class diagram's: the plain arrows, UML's triangles and diamonds, and multiplicities. */
  static readonly classes = new ArrowSet(
    [
      ...plainForms(),
      form("<|-", "solid", "triangle", "none", true), form("<|--", "solid", "triangle", "none", true),
      form("-|>", "solid", "none", "triangle", true), form("--|>", "solid", "none", "triangle", true),
      form("<|..", "dashed", "triangle", "none", true), form("..|>", "dashed", "none", "triangle", true),
      form("*-", "solid", "diamond", "none", true), form("*--", "solid", "diamond", "none", true),
      form("-*", "solid", "none", "diamond", true), form("--*", "solid", "none", "diamond", true),
      form("o-", "solid", "hollowDiamond", "none", true), form("o--", "solid", "hollowDiamond", "none", true),
      form("-o", "solid", "none", "hollowDiamond", true), form("--o", "solid", "none", "hollowDiamond", true),
    ],
    true,
  );

  /** An entity diagram's: a line with a cardinality at each end, and the plain ones. */
  static readonly entities = new ArrowSet(plainForms(), true);
}

function plainForms(): ArrowForm[] {
  return [
    form("->", "solid", "none", "arrow"),
    form("->>", "solid", "none", "arrow"),
    form("-->", "dashed", "none", "arrow"),
    form("-->>", "dashed", "none", "arrow"),
    form("..>", "dashed", "none", "arrow"),
    form("=>", "thick", "none", "arrow"),
    form("==>", "thick", "none", "arrow"),
    form("<-", "solid", "arrow", "none"),
    form("<--", "dashed", "arrow", "none"),
    form("<..", "dashed", "arrow", "none"),
    form("<->", "solid", "arrow", "arrow"),
    form("<-->", "dashed", "arrow", "arrow"),
    form("<=>", "thick", "arrow", "arrow"),
    form("--", "solid", "none", "none", true),
    form("---", "solid", "none", "none", true),
    form("..", "dashed", "none", "none", true),
    form("==", "thick", "none", "none", true),
  ];
}

/** A thing named on a line, with the attributes in brackets after it. */
export interface Ref {
  /** Everything written for it. */
  readonly whole: Span;
  /** Where its name is. */
  readonly nameSpan: Span;
  /** The name, unquoted. */
  readonly name: string;
  /** Each word in its brackets. */
  readonly attributes: readonly Span[];
}

// ---------------------------------------------------------------- quotes and brackets

function isOpenQuote(c: string): boolean {
  return c === '"' || c === "\u201C";
}
function isCloseQuote(c: string, open: string): boolean {
  return open === '"' ? c === '"' : c === "\u201D" || c === '"';
}

/** Walks a stretch, calling `visit` with each index that is outside quotation marks and outside brackets and - when asked - parentheses. False when `visit` stopped the walk. */
function walk(s: Span, skipParentheses: boolean, visit: (i: number) => boolean): boolean {
  let quote = "";
  let brackets = 0;
  let parentheses = 0;
  for (let i = 0; i < s.length; i++) {
    const c = s.at(i);
    if (quote !== "") {
      if (c === "\\" && i + 1 < s.length) {
        i++;
        continue;
      }
      if (isCloseQuote(c, quote)) quote = "";
      continue;
    }
    if (isOpenQuote(c)) {
      quote = c;
      continue;
    }
    if (c === "[") {
      brackets++;
      continue;
    }
    if (c === "]" && brackets > 0) {
      brackets--;
      continue;
    }
    if (skipParentheses) {
      if (c === "(") {
        parentheses++;
        continue;
      }
      if (c === ")" && parentheses > 0) {
        parentheses--;
        continue;
      }
    }
    if (brackets > 0 || parentheses > 0) continue;
    if (!visit(i)) return false;
  }
  return true;
}

/** Where the first `c` outside quotation marks and brackets is, or -1. */
export function indexOf(s: Span, c: string, skipParentheses = false): number {
  let found = -1;
  walk(s, skipParentheses, (i) => {
    if (s.at(i) !== c) return true;
    found = i;
    return false;
  });
  return found;
}

/**
 * A line cut at its colon outside quotation marks and brackets: what comes before, and what comes after (null when there is no colon).
 *
 * The colon that cuts is the first one followed by a space or ending the line, so a time of day or an address keeps its own colons - `09:00: Gates open` is the time 09:00 - and only a line with no such colon is cut at its first colon of any kind.
 */
export function splitColon(s: Span, skipParentheses = false): { head: Span; tail: Span | null } {
  let colon = -1;
  let first = -1;
  walk(s, skipParentheses, (i) => {
    const c = s.at(i);
    if (c !== ":" && c !== "\uFF1A") return true;
    if (first < 0) first = i;
    if (c === "\uFF1A" || i + 1 === s.length || isWhiteSpace(s.at(i + 1))) {
      colon = i;
      return false;
    }
    return true;
  });
  if (colon < 0) colon = first;
  return colon < 0 ? { head: s.trim(), tail: null } : { head: s.slice(0, colon).trim(), tail: s.from(colon + 1).trim() };
}

/** A stretch cut at every `separator` outside quotation marks, brackets and parentheses. */
export function list(s: Span, separator = ","): Span[] {
  const pieces: Span[] = [];
  let start = 0;
  walk(s, true, (i) => {
    const c = s.at(i);
    if (c === separator || (separator === "," && c === "\uFF0C") || (separator === ";" && c === "\uFF1B")) {
      pieces.push(s.slice(start, i - start).trim());
      start = i + 1;
    }
    return true;
  });
  pieces.push(s.from(start).trim());
  return pieces;
}

/** A name as written: unquoted when it is in quotation marks, with an unclosed quotation mark reported. */
export function name(span: Span, problems: ProblemList): string {
  const s = span.trim();
  if (s.length === 0) return "";
  if (!isOpenQuote(s.at(0))) return s.text;
  const open = s.at(0);
  let text = "";
  for (let i = 1; i < s.length; i++) {
    const c = s.at(i);
    if (c === "\\" && i + 1 < s.length && (s.at(i + 1) === '"' || s.at(i + 1) === "\\")) {
      text += s.at(++i);
      continue;
    }
    if (isCloseQuote(c, open)) {
      // Anything after the closing quotation mark is kept: "Fish" and chips reads as a person wrote it.
      if (i + 1 < s.length) text += s.from(i + 1).text;
      return text.trim();
    }
    text += c;
  }
  problems.error(s.slice(0, 1), "UnclosedQuote");
  return text.trim();
}

const mermaidShapedName = /^[\p{L}\p{N}_]+(?:\{\{(?<hexagon>.+)\}\}|\{(?<diamond>.+)\}|\(\((?<circle>.+)\)\)|\(\[(?<pill>.+)\]\))$/u;

/** A thing named on a line: its name, and the attributes in brackets at its end. */
export function reference(span: Span, problems: ProblemList): Ref {
  const s = span.trim();
  const attributes: Span[] = [];
  let nameSpan = s;
  if (s.length > 0 && s.at(s.length - 1) === "]") {
    const open = lastTopLevelOpenBracket(s);
    if (open >= 0) {
      for (const word of list(s.slice(open + 1, s.length - open - 2))) if (!word.isEmpty) attributes.push(word);
      nameSpan = s.slice(0, open).trim();
    }
  }
  // Mermaid's stadium, F([Go]), holds a bracket that is no list of attributes: it is the name's, and said below.
  else if (indexOf(s, "]") < 0 && !mermaidShapedName.test(s.text)) {
    const at = openBracketOutsideQuotes(s);
    if (at >= 0) {
      problems.error(s.slice(at, 1), "UnclosedBracket");
      for (const word of list(s.from(at + 1))) if (!word.isEmpty) attributes.push(word);
      nameSpan = s.slice(0, at).trim();
    }
  }
  warnOfMermaidShape(nameSpan, problems);
  return { whole: s, nameSpan, name: name(nameSpan, problems), attributes };
}

/**
 * A name written as Mermaid names a shaped node, an id and its words in the shape's brackets - C{Let me think} - is drawn under the whole of that name, and said, with the Dhole way to write it.
 *
 * Dhole names a thing by its words and its shape by a word in brackets, so it cannot read the id as Mermaid does: a later line naming C names another thing. Only the brackets that leave the id and the words in the name are said - Mermaid's square ones are read as attributes, and their words are said there - and parentheses only doubled, since a name such as f(x) is a name. A name in quotation marks is the writer's own.
 */
function warnOfMermaidShape(nameSpan: Span, problems: ProblemList): void {
  if (nameSpan.isEmpty || isOpenQuote(nameSpan.at(0))) return;
  const match = mermaidShapedName.exec(nameSpan.text);
  if (!match || !match.groups) return;
  const g = match.groups;
  const said: [string, string] =
    g.hexagon !== undefined ? [g.hexagon, "hexagon"] : g.diamond !== undefined ? [g.diamond, "diamond"] : g.circle !== undefined ? [g.circle, "circle"] : [g.pill ?? "", "pill"];
  problems.warning(nameSpan, "MermaidShape", nameSpan.text, said[0].trim(), said[1]);
}

/** The attributes in brackets at the end of a stretch, and the stretch before them. */
export function trailingAttributes(s: Span, problems: ProblemList): { remainder: Span; attributes: Span[] } {
  const found = reference(s, problems);
  return { remainder: found.nameSpan, attributes: [...found.attributes] };
}

function lastTopLevelOpenBracket(s: Span): number {
  // The bracket that opens the list closing at the end: walk back over nested brackets, outside quotation marks.
  let depth = 0;
  let inQuote = false;
  for (let i = s.length - 1; i >= 0; i--) {
    const c = s.at(i);
    if (c === '"') inQuote = !inQuote;
    if (inQuote) continue;
    if (c === "]") depth++;
    else if (c === "[" && --depth === 0) return i;
  }
  return -1;
}

function openBracketOutsideQuotes(s: Span): number {
  let inQuote = false;
  for (let i = 0; i < s.length; i++) {
    if (s.at(i) === '"') inQuote = !inQuote;
    if (!inQuote && s.at(i) === "[") return i;
  }
  return -1;
}

// ---------------------------------------------------------------- arrows

const cardinalityArrow = /^(?<tail>0\.\.1|1\.\.\*|0\.\.\*|0\.\.n|1\.\.n|1|\*|n|many)(?<line>-{1,3})(?<tip>0\.\.1|1\.\.\*|0\.\.\*|0\.\.n|1\.\.n|1|\*|n|many)$/i;
const crowsFootArrow = /^(?<tail>\|o|\|\||\}o|\}\|)(?<line>--|\.\.)(?<tip>o\||\|\||o\{|\|\{)$/;

/** A crow's foot drawn in characters as the cardinality it draws: a bar is one, a ring is zero, a foot is many. */
function foot(drawn: string): string {
  switch (drawn) {
    case "||":
      return "1";
    case "|o":
    case "o|":
      return "0..1";
    case "}|":
    case "|{":
      return "1..*";
    default:
      return "*";
  }
}

/** A cardinality as one of four: exactly one, zero or one, one or more, any number. */
function card(written: string): string {
  switch (written.toLowerCase()) {
    case "1":
      return "1";
    case "0..1":
      return "0..1";
    case "1..*":
    case "1..n":
      return "1..*";
    default:
      return "*";
  }
}

/** The head of a line cut at its arrows: the things between them, and the arrows themselves - one more thing than arrows when the line is well formed. */
export function arrows(head: Span, set: ArrowSet): { pieces: Span[]; arrows: Arrow[] } {
  const pieces: Span[] = [];
  const found: Arrow[] = [];
  let pieceStart = 0;
  let skipTo = -1;
  walk(head, true, (i) => {
    if (i < skipTo) return true;
    const m = matchArrow(head, i, set);
    if (m) {
      pieces.push(head.slice(pieceStart, i - pieceStart).trim());
      found.push({ token: head.slice(i, m.length), form: m.form, tailCard: m.tailCard, tipCard: m.tipCard });
      pieceStart = i + m.length;
      skipTo = i + m.length;
    }
    return true;
  });
  pieces.push(head.from(pieceStart).trim());
  return { pieces, arrows: found };
}

function matchArrow(s: Span, i: number, set: ArrowSet): { form: ArrowForm; length: number; tailCard: string | null; tipCard: string | null } | null {
  const spaceBefore = i === 0 || isWhiteSpace(s.at(i - 1));
  if (set.cardinalities && spaceBefore) {
    let end = i;
    while (end < s.length && !isWhiteSpace(s.at(end))) end++;
    const word = s.slice(i, end - i).text;
    const c = cardinalityArrow.exec(word);
    if (c && c.groups) return { form: form(c[0], "solid", "none", "none", true), length: end - i, tailCard: card(c.groups.tail), tipCard: card(c.groups.tip) };
    // Mermaid's crow's feet drawn in characters - ||--o{ - read as the cardinalities they draw, dotted for a relationship that is not identifying.
    const d = crowsFootArrow.exec(word);
    if (d && d.groups) return { form: form(d[0], d.groups.line === ".." ? "dashed" : "solid", "none", "none", true), length: end - i, tailCard: foot(d.groups.tail), tipCard: foot(d.groups.tip) };
  }
  for (const f of set.forms) {
    if (i + f.token.length > s.length || s.line.text.substr(s.start + i, f.token.length) !== f.token) continue;
    if (f.spaced) {
      const spaceAfter = i + f.token.length === s.length || isWhiteSpace(s.at(i + f.token.length));
      if (!spaceBefore || !spaceAfter) continue;
    }
    return { form: f, length: f.token.length, tailCard: null, tipCard: null };
  }
  return null;
}

const arrowLike = /^(?:<\||[<*ox])?[-=.~]+(?:\|>|[>*ox])?$/;
const cardinalityLike = /^(?:\d+|n|m|\*|many)(?:\.\.(?:\d+|n|m|\*|many))?-{1,3}(?:\d+|n|m|\*|many)(?:\.\.(?:\d+|n|m|\*|many))?$/i;

/** The first word of a stretch written as a line with a count at each end that is not one of the four counts - 2-*, 1..5-1 - or null. */
export function badCardinality(s: Span): Span | null {
  let start = -1;
  for (let i = 0; i <= s.length; i++) {
    const space = i === s.length || isWhiteSpace(s.at(i));
    if (!space && start < 0) start = i;
    else if (space && start >= 0) {
      const word = s.slice(start, i - start);
      if (cardinalityLike.test(word.text) && !cardinalityArrow.test(word.text)) return word;
      start = -1;
    }
  }
  return null;
}

/**
 * The first word of a stretch that is drawn like an arrow but is none of `set`'s - -.->, --x, ~~~ - or null.
 *
 * A word of dashes, equals signs, dots and tildes, with at most an arrowhead, a bar, a star, an o or an x at either end, and two strokes of line, a head or a drawn end; a single dash between words - Step - one - is a dash, and anything with another letter in it is a name.
 */
export function unknownArrow(s: Span, set: ArrowSet): Span | null {
  let found: Span | null = null;
  let start = -1;
  let last = -2;
  const check = (from: number, to: number): void => {
    if (found !== null || from < 0 || to - from < 2) return;
    const word = s.slice(from, to - from);
    const text = word.text;
    if (!arrowLike.test(text)) return;
    // Two strokes of line, or a head, or an end drawn as a cross, a ring or a star: Mermaid's -x and --o are arrows meant, a lone dash is not.
    const firstC = text[0];
    const lastC = text[text.length - 1];
    const drawnEnd = firstC === "x" || firstC === "o" || firstC === "*" || lastC === "x" || lastC === "o" || lastC === "*";
    const strokes = [...text].filter((c) => c === "-" || c === "=" || c === "." || c === "~").length;
    if (strokes < 2 && !text.includes(">") && !text.includes("<") && !drawnEnd) return;
    if (set.forms.some((f) => f.token === text) || (set.cardinalities && cardinalityArrow.test(text))) return;
    found = word;
  };
  walk(s, true, (i) => {
    // A stretch in quotation marks or brackets was skipped: the word before it ended there.
    if (i !== last + 1) {
      check(start, last + 1);
      start = -1;
    }
    if (isWhiteSpace(s.at(i))) {
      check(start, i);
      start = -1;
    } else if (start < 0) start = i;
    last = i;
    return true;
  });
  check(start, last + 1);
  return found;
}

/** A label written between bars after an arrow, as Mermaid writes one - A -->|yes| B - where the piece after the arrow starts: the bars and what is between them, or null. */
export function labelBetweenBars(pieces: readonly Span[]): Span | null {
  for (let i = 1; i < pieces.length; i++) {
    const piece = pieces[i];
    if (piece.length > 1 && piece.at(0) === "|") {
      const close = piece.text.indexOf("|", 1);
      if (close > 0) return piece.slice(0, close + 1);
    }
  }
  return null;
}

// ---------------------------------------------------------------- values

/** A word as settings and kinds are compared: lower case, letters and digits only. */
export function key(text: string): string {
  let out = "";
  for (const c of text) if (/[\p{L}\p{N}]/u.test(c)) out += c.toLowerCase();
  return out;
}

/** Whether a character is a decimal digit, as .NET's char.IsDigit answers. */
export function isDigit(c: string): boolean {
  return /\p{Nd}/u.test(c);
}

/** Whether a character is a letter or a digit, as .NET's char.IsLetterOrDigit answers. */
export function isLetterOrDigit(c: string): boolean {
  return /[\p{L}\p{Nd}]/u.test(c);
}

const floatPattern = /^[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?$/;

/** A number written in the invariant way - a dot for decimals - with an optional thousands separator of underscores, and a percent sign read as hundredths when `percentAsFraction`. NaN when it is not one. */
export function tryNumber(text: string, percentAsFraction = false): number {
  let t = text.trim().replaceAll("_", "").replaceAll("\u2212", "-");
  const percent = t.endsWith("%");
  if (percent) t = t.slice(0, -1).trimEnd();
  t = t.trim();
  if (!floatPattern.test(t)) return NaN;
  let value = Number(t);
  if (!Number.isFinite(value)) return NaN;
  if (percent && percentAsFraction) value /= 100;
  return value;
}

/** A date written as year-month-day, with an optional time, as milliseconds since 1970 in UTC; NaN when it is not one. */
export function tryDate(text: string): number {
  const t = text.trim();
  // yyyy-MM-dd, yyyy-M-d, with " HH:mm", " H:mm", "THH:mm", " HH:mm:ss", "THH:mm:ss"; yyyy/MM/dd, yyyy/M/d; yyyy-MM; yyyy.
  let m = /^(\d{4})-(\d{1,2})-(\d{1,2})(?:([ T])(\d{1,2}):(\d{2})(?::(\d{2}))?)?$/.exec(t);
  if (m) {
    const [, y, mo, d, sep, h, mi, se] = m;
    const twoDigitDate = mo.length === 2 && d.length === 2;
    if (sep !== undefined) {
      // "yyyy-M-d H:mm" is the only time format that takes a one-digit month, day or hour; every other wants two of each, and seconds only with two-digit fields.
      const twoDigits = twoDigitDate && h.length === 2;
      if (se !== undefined && !twoDigits) return NaN;
      if (sep === "T" && !twoDigits) return NaN;
      if (sep === " " && !twoDigits && se === undefined && h.length > 2) return NaN;
    }
    return utc(+y, +mo, +d, h === undefined ? 0 : +h, mi === undefined ? 0 : +mi, se === undefined ? 0 : +se);
  }
  m = /^(\d{4})\/(\d{1,2})\/(\d{1,2})$/.exec(t);
  if (m) return utc(+m[1], +m[2], +m[3], 0, 0, 0);
  m = /^(\d{4})-(\d{2})$/.exec(t);
  if (m) return utc(+m[1], +m[2], 1, 0, 0, 0);
  m = /^(\d{4})$/.exec(t);
  if (m) return utc(+m[1], 1, 1, 0, 0, 0);
  return NaN;
}

function utc(year: number, month: number, day: number, hour: number, minute: number, second: number): number {
  if (year < 1 || month < 1 || month > 12 || day < 1 || hour > 23 || minute > 59 || second > 59) return NaN;
  const days = new Date(Date.UTC(year, month, 0)).getUTCDate();
  if (day > days) return NaN;
  const date = new Date(0);
  date.setUTCFullYear(year, month - 1, day);
  date.setUTCHours(hour, minute, second, 0);
  return date.getTime();
}

/** One day in milliseconds. */
export const DayMs = 86_400_000;

/** A length of time as days, weeks, hours or minutes - 3d, 2w, 1d 4h - in milliseconds; NaN when it is not one. */
export function tryDuration(text: string): number {
  if (!/^\s*(?:\d+(?:\.\d+)?\s*(?:d|day|days|w|wk|week|weeks|h|hr|hour|hours|min|mins|minute|minutes)\s*)+$/i.test(text)) return NaN;
  let total = 0;
  for (const m of text.matchAll(/(\d+(?:\.\d+)?)\s*(d|days|day|weeks|week|wk|w|hours|hour|hr|h|minutes|minute|mins|min)(?![a-z])/gi)) {
    const n = Number(m[1]);
    switch (m[2].toLowerCase()[0]) {
      case "w":
        total += 7 * n * DayMs;
        break;
      case "h":
        total += n * 3_600_000;
        break;
      case "m":
        total += n * 60_000;
        break;
      default:
        total += n * DayMs;
    }
  }
  return total;
}

/** On or off: on, yes, true or off, no, false; null for anything else. */
export function switchValue(text: string): boolean | null {
  switch (key(text)) {
    case "on":
    case "yes":
    case "true":
    case "show":
    case "y":
    case "1":
      return true;
    case "off":
    case "no":
    case "false":
    case "hide":
    case "none":
    case "n":
    case "0":
      return false;
    default:
      return null;
  }
}

/** A range written as two numbers with two dots, a dash or "to" between them: 0..100; null when it is not one. */
export function tryRange(text: string): { low: number; high: number } | null {
  const t = text.trim();
  for (const separator of ["..", " to ", "\u2013", "\u2014", "~"]) {
    const at = t.toLowerCase().indexOf(separator);
    if (at > 0) {
      let low = tryNumber(t.slice(0, at));
      let high = tryNumber(t.slice(at + separator.length));
      if (!Number.isNaN(low) && !Number.isNaN(high)) {
        if (low > high) [low, high] = [high, low];
        return low < high ? { low, high } : null;
      }
    }
  }
  return null;
}

const sizePattern = /^\s*(?<w>\d+(?:\.\d+)?)\s*(?:x|×|\*|,|by)\s*(?<h>\d+(?:\.\d+)?)\s*(?:px)?\s*$/i;

/** A size in pixels: 800 x 600; null when it is not one, or is under 50 or over 20000 either way. */
export function trySize(text: string): { width: number; height: number } | null {
  const m = sizePattern.exec(text);
  if (!m || !m.groups) return null;
  const width = Number(m.groups.w);
  const height = Number(m.groups.h);
  return width >= 50 && height >= 50 && width <= 20000 && height <= 20000 ? { width, height } : null;
}

// ---------------------------------------------------------------- suggestions

/** How many single-character changes turn one word into another, two letters swapped counting as one - "titel" is one slip from "title", as it is to the person who typed it. */
export function distance(a: string, b: string): number {
  a = a.toLowerCase();
  b = b.toLowerCase();
  let before = new Array<number>(b.length + 1).fill(0);
  let previous = new Array<number>(b.length + 1).fill(0);
  let current = new Array<number>(b.length + 1).fill(0);
  for (let j = 0; j <= b.length; j++) previous[j] = j;
  for (let i = 1; i <= a.length; i++) {
    current[0] = i;
    for (let j = 1; j <= b.length; j++) {
      current[j] = Math.min(Math.min(current[j - 1] + 1, previous[j] + 1), previous[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
      if (i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) current[j] = Math.min(current[j], before[j - 2] + 1);
    }
    [before, previous, current] = [previous, current, before];
  }
  return previous[b.length];
}

/** The choice nearest to `word`, when it is close enough to be a slip: within two changes, and fewer than a third of the word's letters. */
export function nearest(word: string, choices: Iterable<string>): string | null {
  const k = key(word);
  if (k.length < 3) return null;
  let best: string | null = null;
  let bestDistance = Number.MAX_SAFE_INTEGER;
  for (const choice of choices) {
    const d = distance(k, key(choice));
    if (d < bestDistance) {
      best = choice;
      bestDistance = d;
    }
  }
  return best !== null && bestDistance <= Math.min(2, Math.max(1, Math.floor(k.length / 3))) ? best : null;
}
