// Colours as a diagram asks for them, turned into colours only when it is drawn, in the figure's theme - so a figure given
// another theme recolours its diagrams: nothing in a laid-out diagram is a literal colour.
// Ported from Parcel NExT's Divooka.Visualization.Dhole/Rendering/Tones.cs.

import type { Colour, Theme } from "../plot/theme";

/** The neutral colours of a theme a diagram draws with. */
export type Ink = "background" | "ink" | "secondary" | "muted" | "grid" | "axis";

/** A colour asked for by name, found in whatever palette the theme has: the palette colour nearest that hue. Accent is the palette's first colour - the theme's own. */
export type NamedHue = "accent" | "blue" | "orange" | "green" | "yellow" | "pink" | "purple" | "red" | "teal" | "grey";

/**
 * A colour as a diagram asks for it - a neutral ink, the palette's n-th colour, or a named hue - washed toward the background
 * and made translucent as it says.
 */
export class Tone {
  private constructor(
    private readonly kind: 0 | 1 | 2,
    private readonly inkValue: Ink,
    private readonly index: number,
    private readonly named: NamedHue,
    /** How much of the colour is used against the background: 1 the colour itself, 0 the background. */
    readonly strength: number,
    /** How opaque it is drawn. */
    readonly opacity: number,
    /** How much of the theme's ink is mixed in, so a pale hue still reads as text on a wash of itself. */
    readonly deepen = 0,
  ) {}

  static of(ink: Ink, opacity = 1): Tone {
    return new Tone(0, ink, 0, "accent", 1, opacity);
  }
  static palette(index: number, strength = 1, opacity = 1): Tone {
    return new Tone(1, "ink", index, "accent", strength, opacity);
  }
  static hue(hue: NamedHue, strength = 1, opacity = 1): Tone {
    return new Tone(2, "ink", 0, hue, strength, opacity);
  }

  /** The same colour washed to `strength`. */
  washed(strength: number): Tone {
    return new Tone(this.kind, this.inkValue, this.index, this.named, strength, this.opacity, this.deepen);
  }
  /** The same colour at `opacity`. */
  faded(opacity: number): Tone {
    return new Tone(this.kind, this.inkValue, this.index, this.named, this.strength, opacity, this.deepen);
  }
  /** The same colour with `amount` of the theme's ink in it. */
  deepened(amount: number): Tone {
    return new Tone(this.kind, this.inkValue, this.index, this.named, this.strength, this.opacity, amount);
  }
  /** Whether this is a hue rather than a neutral ink. */
  get isHue(): boolean {
    return this.kind !== 0;
  }

  /** Whether two tones ask for the same colour. */
  equals(other: Tone | null | undefined): boolean {
    return (
      !!other &&
      this.kind === other.kind &&
      this.inkValue === other.inkValue &&
      this.index === other.index &&
      this.named === other.named &&
      this.strength === other.strength &&
      this.opacity === other.opacity &&
      this.deepen === other.deepen
    );
  }

  /** The colour in a theme. */
  in(theme: Theme): Colour {
    let colour: Colour;
    if (this.kind === 1) colour = theme.palette.at(this.index);
    else if (this.kind === 2) colour = nearest(theme, this.named);
    else
      switch (this.inkValue) {
        case "background":
          colour = theme.background;
          break;
        case "secondary":
          colour = theme.secondaryInk;
          break;
        case "muted":
          colour = theme.mutedInk;
          break;
        case "grid":
          colour = theme.grid;
          break;
        case "axis":
          colour = theme.axisLine;
          break;
        default:
          colour = theme.ink;
      }
    if (this.strength < 1) colour = mix(theme.background, colour, this.strength);
    if (this.deepen > 0) colour = mix(colour, theme.ink, this.deepen);
    if (this.opacity < 1) colour = { ...colour, a: Math.round(colour.a * Math.min(Math.max(this.opacity, 0), 1)) };
    return colour;
  }
}

/** .NET's Math.Round: halves to the even neighbour. */
export function roundHalfEven(v: number): number {
  const r = Math.round(v);
  return Math.abs(v % 1) === 0.5 && r % 2 !== 0 ? r - 1 : r;
}

/** Two colours mixed: 0 is the first, 1 the second. */
export function mix(from: Colour, to: Colour, amount: number): Colour {
  const t = Math.min(Math.max(amount, 0), 1);
  const channel = (a: number, b: number) => roundHalfEven(a + (b - a) * t);
  return { r: channel(from.r, to.r), g: channel(from.g, to.g), b: channel(from.b, to.b), a: channel(from.a, to.a) };
}

/** Whether a colour is dark: what a theme's background says about which way to wash. */
export function isDark(colour: Colour): boolean {
  return 0.2126 * colour.r + 0.7152 * colour.g + 0.0722 * colour.b < 128;
}

const found = new WeakMap<Theme, Map<NamedHue, Colour>>();

/** The palette colour of a theme nearest a named hue; grey is the theme's muted ink. */
export function nearest(theme: Theme, hue: NamedHue): Colour {
  if (hue === "accent") return theme.palette.at(0);
  if (hue === "grey") return theme.mutedInk;
  let known = found.get(theme);
  if (!known) {
    known = new Map();
    found.set(theme, known);
  }
  const cached = known.get(hue);
  if (cached) return cached;
  let best = fallback(theme, hue);
  let bestDistance = Number.MAX_VALUE;
  const target = degrees(hue);
  for (const colour of theme.palette.colors) {
    const [h, s, l] = hsl(colour);
    if (s < 0.18 || l < 0.08 || l > 0.94) continue;
    let d = Math.abs(h - target);
    d = Math.min(d, 360 - d);
    if (d < bestDistance) {
      best = colour;
      bestDistance = d;
    }
  }
  // A palette with nothing within reach of the hue - a grey one - keeps the colour in the hue's place in Divooka's order.
  if (bestDistance > 50) best = fallback(theme, hue);
  known.set(hue, best);
  return best;
}

function degrees(hue: NamedHue): number {
  switch (hue) {
    case "blue":
      return 215;
    case "orange":
      return 22;
    case "green":
      return 145;
    case "yellow":
      return 43;
    case "pink":
      return 330;
    case "purple":
      return 262;
    case "red":
      return 358;
    case "teal":
      return 178;
    default:
      return 215;
  }
}

function fallback(theme: Theme, hue: NamedHue): Colour {
  const order: Partial<Record<NamedHue, number>> = { blue: 0, orange: 1, green: 2, yellow: 3, pink: 4, teal: 5, purple: 6, red: 7 };
  return theme.palette.at(order[hue] ?? 0);
}

function hsl(colour: Colour): [number, number, number] {
  const r = colour.r / 255;
  const g = colour.g / 255;
  const b = colour.b / 255;
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const l = (max + min) / 2;
  const d = max - min;
  if (d < 1e-9) return [0, 0, l];
  const s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
  const h = max === r ? (g - b) / d + (g < b ? 6 : 0) : max === g ? (b - r) / d + 2 : (r - g) / d + 4;
  return [h * 60, s, l];
}
