// Everything Dhole says to a person, in English and in Chinese, and the problems it says it about.
// Ported from Parcel NExT's Divooka.Visualization.Dhole/Syntax/Problems.cs and DholeWords.cs.
//
// The words of the language itself - flowchart, direction, note, after - are English in every interface, as a programming language's keywords are; what Dhole says ABOUT a text is in the reader's language.

import type { Span } from "./source";

/** A word Dhole says in two languages, for a problem that names it: a kind of diagram, a setting. */
export class Said {
  readonly english: string;
  readonly chinese: string;
  constructor(english: string, chinese: string) {
    this.english = english;
    this.chinese = chinese;
  }
  in(language: string): string {
    return isChinese(language) ? this.chinese : this.english;
  }
  toString(): string {
    return this.english;
  }
}

/** The language name for English. */
export const English = "English";
/** The language name for Chinese. */
export const Chinese = "Chinese";

/** Whether `language` names Chinese - "Chinese", a culture name such as zh-CN, or a code such as zh. */
export function isChinese(language: string | null | undefined): boolean {
  if (!language) return false;
  const lower = language.toLowerCase();
  return lower.startsWith("zh") || lower.startsWith("chinese") || language.includes("中");
}

/** How much a problem in Dhole text matters. */
export type DholeSeverity = "error" | "warning";

