function where(language: string): string {
  return isChinese(language) ? "第 {0} 行第 {1} 列：" : "Line {0}, column {1}: ";
}
function warningWord(language: string): string {
  return isChinese(language) ? "（警告）" : "(warning) ";
}
function message(code: ProblemCode, language: string): string {
  const entry = Table[code];
  return entry ? (isChinese(language) ? entry[2] : entry[0]) : code;
}
function hint(code: ProblemCode, language: string): string {
  const entry = Table[code];
  return entry ? (isChinese(language) ? entry[3] : entry[1]) : "";
}

/** What a problem's words are filled in with: a word, a number, a word in two languages, or a list of either. */
export type ProblemArgument = string | number | Said | readonly string[] | readonly Said[];

/** A number written as .NET writes "0.###": at most three decimals, none when it is whole. */
export function formatNumber(value: number): string {
  if (!Number.isFinite(value)) return String(value);
  const rounded = Math.round(value * 1000) / 1000;
  return (Object.is(rounded, -0) ? 0 : rounded).toString();
}

/** A template with its arguments, a Said argument in the template's language. */
export function formatWords(template: string, args: readonly ProblemArgument[], language: string): string {
  if (args.length === 0) return template;
  const resolved = args.map((argument) => {
    if (argument instanceof Said) return argument.in(language);
    if (Array.isArray(argument)) {
      const joiner = isChinese(language) ? "、" : ", ";
      return (argument as readonly (string | Said)[]).map((a) => (a instanceof Said ? a.in(language) : a)).join(joiner);
    }
    if (typeof argument === "number") return formatNumber(argument);
    return String(argument);
  });
  return template.replace(/\{(\d+)\}/g, (whole, index: string) => {
    const i = Number(index);
    return i < resolved.length ? resolved[i] : whole;
  });
}

/**
 * One problem in Dhole text: where it is, what is wrong, and what to write instead.
 *
 * A problem never stops the rest of the text from being read: the line it is on is skipped or read as far as it makes sense, and every other line is drawn. Its words are English by default and Chinese on request.
 */
export class DholeProblem {
  /** Whether it is an error or a warning. */
  readonly severity: DholeSeverity;
  /** The line it is on, counted from 1. */
  readonly line: number;
  /** The column it starts at, counted from 1. */
  readonly column: number;
  /** How many characters it covers. */
  readonly length: number;
  /** Which problem it is. */
  readonly code: ProblemCode;
  private readonly args: readonly ProblemArgument[];

  constructor(severity: DholeSeverity, line: number, column: number, length: number, code: ProblemCode, args: readonly ProblemArgument[]) {
    this.severity = severity;
    this.line = line;
    this.column = column;
    this.length = Math.max(1, length);
    this.code = code;
    this.args = args;
  }

  /** What is wrong, in a sentence. */
  get message(): string {
    return this.messageIn(English);
  }
  /** What to write instead, in a sentence; empty when there is nothing more to say. */
  get hint(): string {
    return this.hintIn(English);
  }
  /** What is wrong, in `language` - English or Chinese. */
  messageIn(language: string): string {
    return formatWords(message(this.code, language), this.args, language);
  }
  /** What to write instead, in `language`. */
  hintIn(language: string): string {
    return formatWords(hint(this.code, language), this.args, language);
  }

  /** The problem as one line: where, what and what to do, in `language`. */
  describe(language: string = English): string {
    const h = this.hintIn(language);
    const at = where(language).replace("{0}", String(this.line)).replace("{1}", String(this.column));
    const kind = this.severity === "warning" ? warningWord(language) : "";
    // Chinese runs its sentences together; English puts a space between them.
    const gap = isChinese(language) ? "" : " ";
    return h.length === 0 ? `${at}${kind}${this.messageIn(language)}` : `${at}${kind}${this.messageIn(language)}${gap}${h}`;
  }

  /** The problem as one line in English: "Line 3, column 7: ..." followed by the hint. */
  toString(): string {
    return this.describe(English);
  }
}

/** The problems found while reading one text, in the order of the lines they are on. */
export class ProblemList {
  private readonly problems: DholeProblem[] = [];
  private readonly seen = new Set<string>();

  /** Every problem, by line and then by column; problems on one spot keep the order they were found in. */
  get all(): DholeProblem[] {
    return this.problems
      .map((p, i) => ({ p, i }))
      .sort((a, b) => a.p.line - b.p.line || a.p.column - b.p.column || a.i - b.i)
      .map((e) => e.p);
  }
  get hasErrors(): boolean {
    return this.problems.some((p) => p.severity === "error");
  }
  get count(): number {
    return this.problems.length;
  }

  error(where: Span, code: ProblemCode, ...args: ProblemArgument[]): void {
    this.add("error", where.line.number, where.column, where.length, code, args);
  }
  warning(where: Span, code: ProblemCode, ...args: ProblemArgument[]): void {
    this.add("warning", where.line.number, where.column, where.length, code, args);
  }
  errorAt(line: number, column: number, length: number, code: ProblemCode, ...args: ProblemArgument[]): void {
    this.add("error", line, column, length, code, args);
  }
  warningAt(line: number, column: number, length: number, code: ProblemCode, ...args: ProblemArgument[]): void {
    this.add("warning", line, column, length, code, args);
  }

  private add(severity: DholeSeverity, line: number, column: number, length: number, code: ProblemCode, args: ProblemArgument[]): void {
    // One complaint per place: a line read twice - once to find its kind, once to draw it - says its problem once.
    const key = `${line}:${column}:${code}`;
    if (this.seen.has(key)) return;
    this.seen.add(key);
    this.problems.push(new DholeProblem(severity, line, column, length, code, args));
  }
}
