// Where a figure is drawn: a sink that takes shapes, lines and laid-out text with the canvas' calls - save and restore, a
// transform, a clip - and writes them out as SVG, the format a page draws a picture in at any size and keeps its words as words.

import { cssFamilies, type TextLayout } from "./text";
import { hexOf, type Colour } from "./theme";
import { fmt, identity, isIdentity, multiply, rotationDegrees, scaling, translation, type Matrix, RectF, VectorPath } from "../rendering/geometry";

/** How a shape is painted: filled, or stroked with a width, a dash, caps and joins. */
export interface Paint {
  readonly colour: Colour;
  readonly style: "fill" | "stroke";
  readonly strokeWidth?: number;
  readonly dash?: readonly number[];
  readonly cap?: "butt" | "round" | "square";
  readonly join?: "miter" | "round" | "bevel";
}

export const Paints = {
  fill(colour: Colour): Paint {
    return { colour, style: "fill" };
  },
  stroke(colour: Colour, width: number, cap: Paint["cap"] = "butt", join: Paint["join"] = "miter", dash?: readonly number[]): Paint {
    return { colour, style: "stroke", strokeWidth: width, cap, join, dash };
  },
  hairline(colour: Colour, width = 1): Paint {
    return { colour, style: "stroke", strokeWidth: width, cap: "butt", join: "miter" };
  },
};

/** What a figure is drawn onto. */
export interface Sink {
  save(): number;
  restoreToCount(count: number): void;
  translate(dx: number, dy: number): void;
  scale(sx: number, sy: number): void;
  concat(matrix: Matrix): void;
  clipRect(rect: RectF): void;
  drawPath(path: VectorPath, paint: Paint): void;
  drawRect(rect: RectF, paint: Paint): void;
  drawLine(x1: number, y1: number, x2: number, y2: number, paint: Paint): void;
  /** Laid-out text with its block's top left at (x, y). */
  drawText(layout: TextLayout, x: number, y: number, colour: Colour): void;
}

function escapeXml(text: string): string {
  return text.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;");
}

function colourAttributes(prefix: "fill" | "stroke", colour: Colour): string {
  const opacity = colour.a / 255;
  return `${prefix}="${hexOf(colour)}"${opacity < 1 ? ` ${prefix}-opacity="${fmt(opacity)}"` : ""}`;
}

function matrixAttribute(m: Matrix): string {
  if (m.a === 1 && m.b === 0 && m.c === 0 && m.d === 1) return `translate(${fmt(m.e)} ${fmt(m.f)})`;
  return `matrix(${fmt(m.a)} ${fmt(m.b)} ${fmt(m.c)} ${fmt(m.d)} ${fmt(m.e)} ${fmt(m.f)})`;
}

/** A sink that writes SVG. Transforms and clips open groups, and restoring closes them, so the document nests as the drawing did. */
export class SvgSink implements Sink {
  private readonly body: string[] = [];
  private readonly defs: string[] = [];
  private readonly frames: number[] = [];
  private openGroups = 0;
  private clips = 0;
  private readonly idPrefix: string;

  constructor(idPrefix = "dh") {
    this.idPrefix = idPrefix;
  }

  save(): number {
    this.frames.push(this.openGroups);
    return this.frames.length - 1;
  }

  restoreToCount(count: number): void {
    while (this.frames.length > count) {
      const groups = this.frames.pop() as number;
      while (this.openGroups > groups) {
        this.body.push("</g>");
        this.openGroups--;
      }
    }
  }

  translate(dx: number, dy: number): void {
    if (dx !== 0 || dy !== 0) this.concat(translation(dx, dy));
  }
  scale(sx: number, sy: number): void {
    if (sx !== 1 || sy !== 1) this.concat(scaling(sx, sy));
  }
  concat(matrix: Matrix): void {
    if (isIdentity(matrix)) return;
    this.body.push(`<g transform="${matrixAttribute(matrix)}">`);
    this.openGroups++;
  }

  clipRect(rect: RectF): void {
    const id = `${this.idPrefix}-clip${this.clips++}`;
    this.defs.push(`<clipPath id="${id}"><rect x="${fmt(rect.left)}" y="${fmt(rect.top)}" width="${fmt(rect.width)}" height="${fmt(rect.height)}"/></clipPath>`);
    this.body.push(`<g clip-path="url(#${id})">`);
    this.openGroups++;
  }

  private paintAttributes(paint: Paint): string {
    if (paint.style === "fill") return colourAttributes("fill", paint.colour);
    let out = `fill="none" ${colourAttributes("stroke", paint.colour)} stroke-width="${fmt(paint.strokeWidth ?? 1)}"`;
    if (paint.cap && paint.cap !== "butt") out += ` stroke-linecap="${paint.cap}"`;
    if (paint.join && paint.join !== "miter") out += ` stroke-linejoin="${paint.join}"`;
    if (paint.dash && paint.dash.length > 0) out += ` stroke-dasharray="${paint.dash.map(fmt).join(" ")}"`;
    return out;
  }

  drawPath(path: VectorPath, paint: Paint): void {
    if (path.isEmpty || paint.colour.a === 0) return;
    this.body.push(`<path d="${path.toSvg()}" ${this.paintAttributes(paint)}/>`);
  }

  drawRect(rect: RectF, paint: Paint): void {
    if (paint.colour.a === 0) return;
    this.body.push(`<rect x="${fmt(rect.left)}" y="${fmt(rect.top)}" width="${fmt(rect.width)}" height="${fmt(rect.height)}" ${this.paintAttributes(paint)}/>`);
  }

  drawLine(x1: number, y1: number, x2: number, y2: number, paint: Paint): void {
    if (paint.colour.a === 0) return;
    this.body.push(`<line x1="${fmt(x1)}" y1="${fmt(y1)}" x2="${fmt(x2)}" y2="${fmt(y2)}" ${this.paintAttributes({ ...paint, style: "stroke" })}/>`);
  }

  drawText(layout: TextLayout, x: number, y: number, colour: Colour): void {
    if (colour.a === 0) return;
    const f = layout.font;
    const style = `font-family="${escapeXml(cssFamilies(f.families))}" font-size="${fmt(f.size)}"${f.weight !== 400 ? ` font-weight="${f.weight}"` : ""}${f.italic ? ' font-style="italic"' : ""} ${colourAttributes("fill", colour)}`;
    for (const line of layout.lines) {
      if (line.text.length === 0) continue;
      this.body.push(`<text x="${fmt(x + line.left)}" y="${fmt(y + line.baseline)}" ${style} xml:space="preserve">${escapeXml(line.text)}</text>`);
    }
  }

  /** The SVG document of everything drawn, `width` by `height` pixels, with a title for a reader who cannot see it. */
  toSvg(width: number, height: number, title?: string | null, description?: string | null): string {
    this.restoreToCount(0);
    while (this.openGroups > 0) {
      this.body.push("</g>");
      this.openGroups--;
    }
    const head = `<svg xmlns="http://www.w3.org/2000/svg" width="${fmt(width)}" height="${fmt(height)}" viewBox="0 0 ${fmt(width)} ${fmt(height)}" role="img">`;
    const words = (title ? `<title>${escapeXml(title)}</title>` : "") + (description ? `<desc>${escapeXml(description)}</desc>` : "");
    const defs = this.defs.length > 0 ? `<defs>${this.defs.join("")}</defs>` : "";
    return `${head}${words}${defs}${this.body.join("")}</svg>`;
  }
}

/** A rotation about a point, as a sink's concat takes it. */
export { rotationDegrees, identity, multiply };
