// A graph diagram described - boxes, lines and groups - and laid out and drawn: each group laid out on its own as a layered graph and then placed in its parent as one box, the lines routed through the layout's waypoints, everything turned into marks.
// Ported from Parcel NExT's Divooka.Visualization.Dhole/Layout/GraphDiagram.cs.

import { RectF, VectorPath, add, mul, normalize, sub, vec, type Vec2 } from "../rendering/geometry";
import { Scene, TextSetter, shapeMark, type Mark, type SizeF, type TextMark } from "../rendering/scene";
import * as Shapes from "../rendering/shapes";
import type { NodeShape } from "../rendering/shapes";
import { Tone } from "../rendering/tones";
import type { Head, LineStyle } from "../syntax/scan";
import { FontWeights, type TextMeasurer } from "../plot/text";
import type { Theme } from "../plot/theme";
import { LayeredEdge, LayeredNode, run as runLayered } from "./layered";
import type { Direction } from "./direction";

/** What a box in a graph diagram holds besides its label: a class's members, an entity's attributes. */
export class Compartments {
  /** A line above the name: «interface». */
  stereotype: string | null = null;
  /** Sections of lines under the name, each drawn under a rule: attributes, then operations. */
  readonly sections: CompartmentLine[][] = [];
  /** Whether each line is a row of columns - an entity's key, name and type - rather than a sentence. */
  tabular = false;

  constructor(init?: { tabular?: boolean }) {
    if (init?.tabular) this.tabular = true;
  }
}

/**
 * One line in a compartment.
 * cells: the line's text; a tabular compartment lines its cells up in columns.
 * italic: whether it is set in italic - an abstract member.
 * underline: whether it is a static member.
 */
export interface CompartmentLine {
  readonly cells: readonly string[];
  readonly italic: boolean;
  readonly underline: boolean;
}

export function compartmentLine(cells: readonly string[], italic = false, underline = false): CompartmentLine {
  return { cells, italic, underline };
}

/** A box in a graph diagram. */
export class GraphNode {
  readonly id: string;
  /** What the box is found by: its name with case and spacing set aside. */
  readonly key: string;
  label = "";
  shape: NodeShape = "box";
  /** The hue the box is drawn in; the theme's accent when not said. */
  hue: Tone = Tone.hue("accent");
  /** Whether the box is drawn quiet: a muted outline and a grey wash. */
  muted = false;
  /** The group it was first named in, or -1. */
  group = -1;
  compartments: Compartments | null = null;
  /** Where it was first written, for the order things are placed in. */
  order = 0;

  size: SizeF = { width: 0, height: 0 };
  box: RectF = new RectF(0, 0, 0, 0);

  constructor(id: string, key = "") {
    this.id = id;
    this.key = key;
  }
}

/** A line between two boxes. */
export class GraphEdge {
  from: number;
  to: number;
  /** Whether `from` is a group - a composite state - rather than a box. */
  fromGroup = false;
  /** Whether `to` is a group. */
  toGroup = false;
  label: string | null = null;
  line: LineStyle = "solid";
  tail: Head = "none";
  tip: Head = "arrow";
  /** The cardinality written at the first end, for an entity's crow's foot or a class's multiplicity. */
  tailCard: string | null = null;
  tipCard: string | null = null;
  /** Whether the cardinalities are drawn as crow's feet (an entity diagram) rather than written (a class diagram). */
  crowsFeet = false;
  /** A hue for the line, or null for the theme's secondary ink. */
  hue: Tone | null = null;

  constructor(init: Partial<GraphEdge> & { from: number; to: number }) {
    this.from = init.from;
    this.to = init.to;
    Object.assign(this, init);
  }
}

/** A group of boxes drawn in a frame of its own: a subgraph, a composite state, a package. */
export class GraphGroup {
  readonly id: string;
  label = "";
  parent = -1;
  hue: Tone | null = null;
  /** Whether the frame is a state's own rounded box, its name in a header, rather than a dashed region. */
  isState = false;
  box: RectF = new RectF(0, 0, 0, 0);

  constructor(id: string) {
    this.id = id;
  }
}

/** A graph diagram described: boxes, lines and groups, and which way it flows. */
export class GraphModel {
  direction: Direction = "down";
  readonly nodes: GraphNode[] = [];
  readonly edges: GraphEdge[] = [];
  readonly groups: GraphGroup[] = [];
  private readonly byId = new Map<string, number>();

  indexOf(id: string): number {
    return this.byId.get(id) ?? -1;
  }

  /**
   * Turns the boxes named `redirect`'s keys into the groups its values name: their lines go to the group instead, and the boxes go.
   *
   * A composite state is written as a state with lines under it, and a line may name it before those lines are read: it was a box until then.
   */
  redirect(redirect: ReadonlyMap<number, number>): void {
    if (redirect.size === 0) return;
    for (const edge of this.edges) {
      if (!edge.fromGroup && redirect.has(edge.from)) {
        edge.from = redirect.get(edge.from)!;
        edge.fromGroup = true;
      }
      if (!edge.toGroup && redirect.has(edge.to)) {
        edge.to = redirect.get(edge.to)!;
        edge.toGroup = true;
      }
    }
    const renumber = new Map<number, number>();
    const kept: GraphNode[] = [];
    for (let i = 0; i < this.nodes.length; i++)
      if (!redirect.has(i)) {
        renumber.set(i, kept.length);
        kept.push(this.nodes[i]);
      }
    for (const edge of this.edges) {
      if (!edge.fromGroup) edge.from = renumber.get(edge.from)!;
      if (!edge.toGroup) edge.to = renumber.get(edge.to)!;
    }
    this.nodes.length = 0;
    this.nodes.push(...kept);
    this.byId.clear();
    for (let i = 0; i < this.nodes.length; i++) this.byId.set(this.nodes[i].key, i);
  }

  /** The box called `id`, made the first time it is named, in `group`; whether it was made then. */
  node(id: string, group: number): { node: GraphNode; created: boolean } {
    const index = this.byId.get(id);
    if (index !== undefined) return { node: this.nodes[index], created: false };
    const node = new GraphNode(id, id);
    node.label = id;
    node.group = group;
    node.order = this.nodes.length;
    this.byId.set(id, this.nodes.length);
    this.nodes.push(node);
    return { node, created: true };
  }
}

/** The sizes text is set in, scaled with the theme's own. */
export interface TypeSizes {
  readonly label: number;
  readonly small: number;
  readonly heading: number;
}

export function typeFor(theme: Theme): TypeSizes {
  const k = Math.fround(theme.fontSize / 11.0);
  return { label: 14 * k, small: 12.5 * k, heading: 14 * k };
}

const PadX = 14;
const PadY = 9;
const MaxLabel = 210;
const GroupPad = 16;
const HeadSize = 9;

/** One item of a level: a box, or a child group laid out as one box. */
interface Item {
  readonly isGroup: boolean;
  readonly index: number;
}

const itemKey = (item: Item): string => `${item.isGroup ? "g" : "n"}${item.index}`;
const sameItem = (a: Item, b: Item): boolean => a.isGroup === b.isGroup && a.index === b.index;

/** One group's layout: where each of its items went, relative to its own top left, and the lines between its items. */
class LevelLayout {
  group = -1;
  readonly items: Item[] = [];
  readonly boxes: LayeredNode[] = [];
  readonly lines: { edge: number; line: LayeredEdge }[] = [];
  /** The stretch inside this group of each line that crosses its frame: from the box it joins to a stub on the frame's far side. */
  readonly stubs = new Map<number, LayeredEdge>();
  size: SizeF = { width: 0, height: 0 };
  contentOffset: Vec2 = vec(0, 0);
  origin: Vec2 = vec(0, 0);
}

/**
 * A graph diagram laid out and drawn: each group laid out on its own as a layered graph and then placed in its parent as one box, the lines routed through the layout's waypoints, everything turned into marks.
 */
export const GraphDiagram = { build };

export function build(model: GraphModel, theme: Theme, measurer: TextMeasurer): Scene {
  const text = new TextSetter(theme.fontFamilies, measurer);
  const type = typeFor(theme);
  const scene = new Scene(theme.fontFamilies);

  for (const node of model.nodes) node.size = measure(node, text, type);

  // Lay every group out from the innermost outward, then place each in its parent.
  const levels = new Map<number, LevelLayout>();
  const top = layoutLevel(model, -1, levels, text, type);
  position(model, top, levels, vec(0, 0));

  drawGroups(model, scene, text, type);
  drawEdges(model, levels, scene, text, type);
  drawNodes(model, scene, text, type);
  // The boxes keep the places the marks were moved to, so what is laid out and what is drawn agree.
  const moved = scene.frame(12);
  for (const node of model.nodes) node.box = RectF.fromXYWH(node.box.left + moved.x, node.box.top + moved.y, node.box.width, node.box.height);
  for (const group of model.groups) group.box = RectF.fromXYWH(group.box.left + moved.x, group.box.top + moved.y, group.box.width, group.box.height);
  return scene;
}

// ---------------------------------------------------------------- measuring

function measure(node: GraphNode, text: TextSetter, type: TypeSizes): SizeF {
  if (node.shape === "startDot" || node.shape === "endDot" || node.shape === "bar") return Shapes.fit(node.shape, { width: 0, height: 0 }, 0, 0);
  if (node.compartments !== null) return measureCompartments(node, node.compartments, text, type);
  const label = text.measure(node.label, type.label, FontWeights.Normal, node.shape === "diamond" ? MaxLabel * Math.fround(0.7) : MaxLabel);
  const size = Shapes.fit(node.shape, label, PadX, PadY);
  return { width: Math.max(size.width, node.shape === "circle" ? 0 : 56), height: Math.max(size.height, 34) };
}

function measureCompartments(node: GraphNode, c: Compartments, text: TextSetter, type: TypeSizes): SizeF {
  let width = text.measure(node.label, type.heading, FontWeights.SemiBold).width;
  let height = text.measure(node.label, type.heading, FontWeights.SemiBold).height + 2 * 7;
  if (c.stereotype !== null) {
    const s = text.measure(`«${c.stereotype}»`, type.small, FontWeights.Normal);
    width = Math.max(width, s.width);
    height += s.height;
  }
  for (const section of c.sections) {
    height += 8;
    for (const line of section) {
      const columns = columnWidths(c, text, type);
      const lineWidth = c.tabular ? columns.reduce((a, b) => a + b, 0) + 14 * (columns.length - 1) : text.measure(line.cells[0], type.small, FontWeights.Normal, Number.POSITIVE_INFINITY, line.italic).width;
      width = Math.max(width, lineWidth);
      height += text.measure("Ag", type.small, FontWeights.Normal).height + 3;
    }
    if (section.length === 0) height += 6;
  }
  return { width: Math.max(width + 2 * PadX, 96), height: height + 6 };
}

function columnWidths(c: Compartments, text: TextSetter, type: TypeSizes): number[] {
  const all = c.sections.flat();
  const count = all.length === 0 ? 1 : Math.max(...all.map((l) => l.cells.length));
  const widths = new Array<number>(count).fill(0);
  for (const line of all)
    for (let i = 0; i < line.cells.length; i++) widths[i] = Math.max(widths[i], text.measure(line.cells[i], type.small, i === 1 ? FontWeights.Normal : FontWeights.Normal).width);
  return widths;
}

// ---------------------------------------------------------------- layout

function layoutLevel(model: GraphModel, group: number, levels: Map<number, LevelLayout>, text: TextSetter, type: TypeSizes): LevelLayout {
  const level = new LevelLayout();
  level.group = group;
  // Child groups first, so each is one box of known size here.
  for (let g = 0; g < model.groups.length; g++)
    if (model.groups[g].parent === group) {
      const inner = layoutLevel(model, g, levels, text, type);
      levels.set(g, inner);
      level.items.push({ isGroup: true, index: g });
      level.boxes.push(new LayeredNode(inner.size.width, inner.size.height));
    }
  for (let n = 0; n < model.nodes.length; n++)
    if (model.nodes[n].group === group) {
      level.items.push({ isGroup: false, index: n });
      level.boxes.push(new LayeredNode(model.nodes[n].size.width, model.nodes[n].size.height));
    }
  // Groups are placed where their first-written node would be, so the text's order reads down the page.
  const order = level.items.map((_, i) => i).sort((a, b) => firstOrder(model, level.items[a]) - firstOrder(model, level.items[b]) || a - b);
  const items = order.map((i) => level.items[i]);
  const boxes = order.map((i) => level.boxes[i]);
  level.items.length = 0;
  level.items.push(...items);
  level.boxes.length = 0;
  level.boxes.push(...boxes);

  const itemIndex = new Map<string, number>();
  for (let i = 0; i < level.items.length; i++) itemIndex.set(itemKey(level.items[i]), i);

  const lines: LayeredEdge[] = [];
  for (let e = 0; e < model.edges.length; e++) {
    const edge = model.edges[e];
    const a = edge.fromGroup ? groupItemAt(model, edge.from, group) : itemAt(model, edge.from, group);
    const b = edge.toGroup ? groupItemAt(model, edge.to, group) : itemAt(model, edge.to, group);
    if (group >= 0 && (a === null) !== (b === null)) {
      // A line crossing this group's frame is laid out here as far as the frame: from its box to a stub at the frame's top when it comes in, at the bottom when it goes out, so it takes a lane past the boxes in its way rather than through them.
      const stub = level.boxes.length;
      level.boxes.push(new LayeredNode(2, 2, { pin: a !== null ? 2 : 1 }));
      const inside = a !== null ? new LayeredEdge(itemIndex.get(itemKey(a))!, stub) : new LayeredEdge(stub, itemIndex.get(itemKey(b!))!);
      lines.push(inside);
      level.stubs.set(e, inside);
      continue;
    }
    if (a === null || b === null) continue;
    // A line between two things inside one child group is that group's; a line between a box and a group it is in is drawn where both are.
    if (sameItem(a, b) && edge.from !== edge.to) continue;
    if (sameItem(a, b) && a.isGroup) continue;
    const label = !edge.label ? null : chip(text.measure(edge.label, type.small, FontWeights.Normal, 160));
    const line = new LayeredEdge(itemIndex.get(itemKey(a))!, itemIndex.get(itemKey(b))!, label);
    lines.push(line);
    level.lines.push({ edge: e, line });
  }
  for (const loop of lines.filter((l) => l.isLoop)) level.boxes[loop.from].loopRoom = Math.max(level.boxes[loop.from].loopRoom, 30 + (loop.label?.width ?? 0));

  const bounds = runLayered(level.boxes, lines, model.direction, 30, 46);
  const labelled = group >= 0 && !!model.groups[group].label;
  const title = labelled ? text.measure(model.groups[group].label, type.small, FontWeights.SemiBold).height + 8 : 0;
  const pad = group >= 0 ? GroupPad : 0;
  const titleWidth = labelled ? text.measure(model.groups[group].label, type.small, FontWeights.SemiBold).width + 2 * pad : 0;
  const contentWidth = Math.max(bounds.width + 2 * pad, titleWidth);
  level.contentOffset = vec(pad - bounds.left + (contentWidth - (bounds.width + 2 * pad)) / 2, pad + title - bounds.top);
  level.size = { width: contentWidth, height: bounds.height + 2 * pad + title };
  if (group < 0) levels.set(-1, level);
  return level;
}

function chip(text: SizeF): SizeF {
  return { width: text.width + 8, height: text.height + 4 };
}

const IntMax = 2147483647;

function firstOrder(model: GraphModel, item: Item): number {
  if (!item.isGroup) return model.nodes[item.index].order;
  let first = IntMax;
  for (let n = 0; n < model.nodes.length; n++) if (within(model, model.nodes[n].group, item.index)) first = Math.min(first, model.nodes[n].order);
  return first === IntMax ? IntMax - 1 : first;
}

function within(model: GraphModel, group: number, ancestor: number): boolean {
  for (let g = group; g >= 0; g = model.groups[g].parent) if (g === ancestor) return true;
  return false;
}

/** The item of the level for `group` that holds a node: the node itself, or the child group it is somewhere inside; null when it is outside the level. */
function itemAt(model: GraphModel, node: number, group: number): Item | null {
  const container = model.nodes[node].group;
  if (container === group) return { isGroup: false, index: node };
  let child = container;
  while (child >= 0 && model.groups[child].parent !== group) child = model.groups[child].parent;
  return child >= 0 ? { isGroup: true, index: child } : null;
}

/** The item of the level for `group` that is or holds group `inner`; null when it is the level itself or outside it. */
function groupItemAt(model: GraphModel, inner: number, group: number): Item | null {
  if (inner === group) return null;
  let child = inner;
  while (child >= 0 && model.groups[child].parent !== group) child = model.groups[child].parent;
  return child >= 0 ? { isGroup: true, index: child } : null;
}

function position(model: GraphModel, level: LevelLayout, levels: Map<number, LevelLayout>, origin: Vec2): void {
  level.origin = add(origin, level.contentOffset);
  for (let i = 0; i < level.items.length; i++) {
    const { isGroup, index } = level.items[i];
    const box = level.boxes[i].box;
    const placed = RectF.fromXYWH(box.left + level.origin.x, box.top + level.origin.y, box.width, box.height);
    if (isGroup) {
      model.groups[index].box = placed;
      position(model, levels.get(index)!, levels, vec(placed.left, placed.top));
    } else model.nodes[index].box = placed;
  }
}

// ---------------------------------------------------------------- drawing

function drawGroups(model: GraphModel, scene: Scene, text: TextSetter, type: TypeSizes): void {
  // Outer groups first, so an inner frame sits on its parent's.
  const byDepth = model.groups.map((_, g) => g).sort((a, b) => depth(model, a) - depth(model, b) || a - b);
  for (const g of byDepth) {
    const group = model.groups[g];
    const box = group.box;
    if (group.isState) {
      const hue = group.hue ?? Tone.hue("accent");
      const frame = new VectorPath();
      frame.addRoundRect(box, 12, 12);
      scene.add(shapeMark(frame, hue.washed(0.06), hue.washed(0.75), 1.25));
    } else {
      const hue = group.hue;
      const frame = new VectorPath();
      frame.addRoundRect(box, 8, 8);
      scene.add(shapeMark(frame, hue?.washed(0.07) ?? Tone.of("ink").washed(0.035), hue?.washed(0.55) ?? Tone.of("axis"), 1, "dashed"));
    }
    if (group.label) scene.add(text.mark(group.label, box.left + GroupPad * 0.75, box.top + 7, type.small, FontWeights.SemiBold, Tone.of("secondary")));
  }
}

function depth(model: GraphModel, group: number): number {
  let d = 0;
  for (let g = model.groups[group].parent; g >= 0; g = model.groups[g].parent) d++;
  return d;
}

function drawEdges(model: GraphModel, levels: Map<number, LevelLayout>, scene: Scene, text: TextSetter, type: TypeSizes): void {
  const vertical = model.direction === "down" || model.direction === "up";
  const labels: Mark[] = [];
  for (const level of levels.values()) {
    for (const { edge: e, line } of level.lines) {
      const edge = model.edges[e];
      if (line.points.length < 2) continue;
      const fromItem = level.items[line.from];
      const toItem = level.items[line.to];
      // A line whose end is inside a group runs on through each group it enters, along the lane that group's own layout gave it, to the very box it names.
      const leaving = lanes(model, levels, e, fromItem, edge.fromGroup ? edge.from : -1);
      const entering = lanes(model, levels, e, toItem, edge.toGroup ? edge.to : -1);
      leaving.reverse();
      const points: Vec2[] = [...leaving.flat(), ...line.points.map((p) => add(p, level.origin)), ...entering.flat()];
      if (!line.isLoop) {
        // A port on a diamond or a circle sits on its outline, not on the box round it.
        if (!edge.fromGroup) points[0] = Shapes.onOutline(model.nodes[edge.from].shape, model.nodes[edge.from].box, points[0], vertical);
        if (!edge.toGroup) points[points.length - 1] = Shapes.onOutline(model.nodes[edge.to].shape, model.nodes[edge.to].box, points[points.length - 1], vertical);
      }

      const ink = edge.hue ?? Tone.of("secondary");
      const width = 1.5;
      // The line stops where its heads begin.
      const tipDirection = endDirection(points, true, vertical, line.isLoop);
      const tailDirection = endDirection(points, false, vertical, line.isLoop);
      const tip = points[points.length - 1];
      const tail = points[0];
      // A crow's foot is drawn over the line's own end, so the line runs all the way to the box.
      const tipBack = edge.crowsFeet ? 0 : Shapes.headLength(edge.tip, HeadSize);
      const tailBack = edge.crowsFeet ? 0 : Shapes.headLength(edge.tail, HeadSize);
      const drawn = [...points];
      if (tipBack > 0 && drawn.length >= 2) drawn[drawn.length - 1] = sub(tip, mul(tipDirection, tipBack));
      if (tailBack > 0 && drawn.length >= 2) drawn[0] = sub(tail, mul(tailDirection, tailBack));
      const path = line.isLoop ? loopPath(drawn) : Shapes.bump(drawn, vertical);
      scene.add(shapeMark(path, null, ink, width, edge.line));
      addHead(scene, edge.tip, tip, tipDirection, ink);
      addHead(scene, edge.tail, tail, tailDirection, ink);
      if (edge.crowsFeet) {
        addCrow(scene, edge.tipCard, tip, tipDirection, ink);
        addCrow(scene, edge.tailCard, tail, tailDirection, ink);
      } else {
        addCard(labels, text, type, edge.tipCard, tip, tipDirection);
        addCard(labels, text, type, edge.tailCard, tail, tailDirection);
      }
      if (edge.label) {
        const size = text.measure(edge.label, type.small, FontWeights.Normal, 160);
        const c = add(line.labelCenter, level.origin);
        const chipPath = new VectorPath();
        chipPath.addRoundRect(RectF.fromXYWH(c.x - size.width / 2 - 4, c.y - size.height / 2 - 2, size.width + 8, size.height + 4), 4, 4);
        labels.push(shapeMark(chipPath, Tone.of("background", 0.92), null, 0));
        labels.push(text.centred(edge.label, c.x, c.y, type.small, FontWeights.Normal, Tone.of("secondary"), 160));
      }
    }
  }
  // Labels after every line, so no line is drawn over one.
  for (const label of labels) scene.add(label);
}

/**
 * The lanes a line takes inside the groups it crosses on one side, outermost first: each the stretch of that group's own layout from its stub on the frame to the box - or the inner group - the line reaches.
 * @param item The line's end as the level that draws it sees it: a box, or the group holding it.
 * @param endGroup The group the line itself ends at, or -1 when it ends at a box.
 */
function lanes(_model: GraphModel, levels: Map<number, LevelLayout>, edge: number, item: Item, endGroup: number): Vec2[][] {
  const found: Vec2[][] = [];
  let group = item.isGroup && item.index !== endGroup ? item.index : -1;
  for (;;) {
    if (group < 0) break;
    const inner = levels.get(group);
    if (!inner) break;
    const stub = inner.stubs.get(edge);
    if (!stub || stub.points.length === 0) break;
    found.push(stub.points.map((p) => add(p, inner.origin)));
    // The lane ends at the stub's own box inside this group: a box, or a group to go on into.
    const at = stub.from < inner.items.length && inner.stubs.get(edge) === stub && stub.to >= inner.items.length ? stub.from : stub.to;
    const { isGroup, index } = at < inner.items.length ? inner.items[at] : { isGroup: false, index: -1 };
    group = isGroup && index !== endGroup ? index : -1;
  }
  return found;
}

/** The direction a line runs as it reaches its end (tip) or, backward, its start (tail). */
function endDirection(points: readonly Vec2[], tip: boolean, vertical: boolean, loop: boolean): Vec2 {
  const end = tip ? points[points.length - 1] : points[0];
  const before = tip ? points[points.length - 2] : points[1];
  if (loop) return normalize(sub(end, before));
  const d = sub(end, before);
  if (vertical) return vec(0, Math.abs(d.y) < 0.01 ? 1 : Math.sign(d.y));
  return vec(Math.abs(d.x) < 0.01 ? 1 : Math.sign(d.x), 0);
}

function loopPath(points: readonly Vec2[]): VectorPath {
  const path = new VectorPath();
  if (points.length < 3) return Shapes.polyline(points);
  const a = points[0];
  const m = points[1];
  const b = points[points.length - 1];
  path.moveTo(a);
  path.cubicTo(add(add(a, mul(sub(m, a), 1.6)), mul(sub(a, b), 0.15)), add(add(b, mul(sub(m, b), 1.6)), mul(sub(b, a), 0.15)), b);
  return path;
}

function addHead(scene: Scene, head: Head, at: Vec2, direction: Vec2, ink: Tone): void {
  const drawn = Shapes.end(head, at, direction, HeadSize);
  if (drawn) scene.add(shapeMark(drawn.path, drawn.filled ? ink : Tone.of("background"), ink, drawn.filled ? 1 : 1.4));
}

/** An entity's cardinality at a line's end: a bar for one, a circle for zero, a crow's foot for many. */
function addCrow(scene: Scene, card: string | null, at: Vec2, direction: Vec2, ink: Tone): void {
  if (card === null) return;
  const u = normalize(direction);
  const n = vec(-u.y, u.x);
  const many = card === "*" || card === "1..*";
  const zero = card === "0..1" || card === "*";
  const marks = new VectorPath();
  if (many) {
    const heel = sub(at, mul(u, 12));
    marks.moveTo(heel).lineTo(add(at, mul(n, 7)));
    marks.moveTo(heel).lineTo(at);
    marks.moveTo(heel).lineTo(sub(at, mul(n, 7)));
  }
  // The bar of one, inside the foot, or near the end alone.
  const barAt = many ? 15 : 7;
  if (!zero) {
    marks.moveTo(add(sub(at, mul(u, barAt)), mul(n, 7))).lineTo(sub(sub(at, mul(u, barAt)), mul(n, 7)));
    if (!many) marks.moveTo(add(sub(at, mul(u, barAt + 4)), mul(n, 7))).lineTo(sub(sub(at, mul(u, barAt + 4)), mul(n, 7)));
  }
  scene.add(shapeMark(marks, null, ink, 1.4));
  if (zero) {
    const centre = sub(at, mul(u, many ? 19 : 12));
    const circle = new VectorPath();
    circle.addCircle(centre.x, centre.y, 4.2);
    scene.add(shapeMark(circle, Tone.of("background"), ink, 1.4));
    if (!many) {
      const bar = new VectorPath();
      bar.moveTo(add(sub(at, mul(u, 5)), mul(n, 7))).lineTo(sub(sub(at, mul(u, 5)), mul(n, 7)));
      scene.add(shapeMark(bar, null, ink, 1.4));
    }
  }
}

/** A class's multiplicity written beside a line's end. */
function addCard(labels: Mark[], text: TextSetter, type: TypeSizes, card: string | null, at: Vec2, direction: Vec2): void {
  if (card === null) return;
  const u = normalize(direction);
  const n = vec(-u.y, u.x);
  const c = add(sub(at, mul(u, 16)), mul(n, 11));
  labels.push(text.centred(card, c.x, c.y, type.small * Math.fround(0.92), FontWeights.Normal, Tone.of("secondary")));
}

function drawNodes(model: GraphModel, scene: Scene, text: TextSetter, type: TypeSizes): void {
  for (const node of model.nodes) {
    const box = node.box;
    const hue = node.hue;
    let fill = node.muted ? Tone.of("ink").washed(0.05) : hue.washed(0.14);
    let stroke = node.muted ? Tone.of("muted") : hue.washed(0.9);
    switch (node.shape) {
      case "startDot":
        scene.add(shapeMark(Shapes.outline(node.shape, box), Tone.of("ink"), null, 0));
        continue;
      case "endDot":
        scene.add(shapeMark(Shapes.outline(node.shape, box), Tone.of("background"), Tone.of("ink"), 1.5));
        scene.add(shapeMark(Shapes.outline("circle", box.inflate(-4.5)), Tone.of("ink"), null, 0));
        continue;
      case "bar":
        scene.add(shapeMark(Shapes.outline(node.shape, barBox(box, model.direction)), Tone.of("ink"), null, 0));
        continue;
    }
    if (node.compartments !== null) {
      drawCompartments(node, node.compartments, scene, text, type);
      continue;
    }
    if (node.shape === "note") {
      fill = Tone.hue("yellow").washed(0.2);
      stroke = Tone.hue("yellow").washed(0.75);
    }
    scene.add(shapeMark(Shapes.outline(node.shape, box), fill, stroke, 1.5));
    const maxWidth = node.shape === "diamond" ? MaxLabel * Math.fround(0.7) : MaxLabel;
    const cx = box.midX;
    let cy = box.midY;
    if (node.shape === "cylinder") cy += 4;
    if (node.shape === "document") cy -= 3;
    scene.add(text.centred(node.label, cx, cy, type.label, FontWeights.Normal, Tone.of("ink"), maxWidth));
  }
}

/** A fork or a join is drawn across the flow, whichever way the box was measured. */
function barBox(box: RectF, direction: Direction): RectF {
  return direction === "down" || direction === "up" ? box : RectF.fromXYWH(box.midX - box.height / 2, box.midY - box.width / 2, box.height, box.width);
}

function drawCompartments(node: GraphNode, c: Compartments, scene: Scene, text: TextSetter, type: TypeSizes): void {
  const box = node.box;
  const hue = node.hue;
  const headerHeight = text.measure(node.label, type.heading, FontWeights.SemiBold).height + 14 + (c.stereotype !== null ? text.measure("«x»", type.small, FontWeights.Normal).height : 0);
  const outlinePath = new VectorPath();
  outlinePath.addRoundRect(box, 4, 4);
  scene.add(shapeMark(outlinePath, Tone.of("background"), null, 0));
  const header = new VectorPath();
  header.addRoundRect(RectF.fromXYWH(box.left, box.top, box.width, headerHeight), 4, 4);
  scene.add(shapeMark(header, hue.washed(0.16), null, 0));
  scene.add(shapeMark(outlinePath, null, hue.washed(0.9), 1.5));
  let y = box.top + 7;
  if (c.stereotype !== null) {
    const stereo: TextMark = text.centred(`«${c.stereotype}»`, box.midX, 0, type.small, FontWeights.Normal, Tone.of("secondary"));
    scene.add({ ...stereo, y });
    y += stereo.height;
  }
  const name = text.centred(node.label, box.midX, 0, type.heading, FontWeights.SemiBold, Tone.of("ink"));
  scene.add({ ...name, y });
  y = box.top + headerHeight;
  const lineHeight = text.measure("Ag", type.small, FontWeights.Normal).height + 3;
  const columns = c.tabular ? columnWidths(c, text, type) : [];
  for (const section of c.sections) {
    const rule = new VectorPath();
    rule.moveTo(box.left, y).lineTo(box.right, y);
    scene.add(shapeMark(rule, null, hue.washed(0.45), 1));
    y += 5;
    for (const line of section) {
      if (c.tabular) {
        let x = box.left + PadX;
        for (let i = 0; i < line.cells.length; i++) {
          const ink = i === 0 ? Tone.of("ink") : Tone.of("secondary");
          scene.add(text.mark(line.cells[i], x, y, type.small, i === 0 && line.underline ? FontWeights.SemiBold : FontWeights.Normal, ink));
          x += columns[i] + 14;
        }
      } else {
        const mark = text.mark(line.cells[0], box.left + PadX, y, type.small, FontWeights.Normal, Tone.of("ink"), Number.POSITIVE_INFINITY, "left", line.italic);
        scene.add(mark);
        if (line.underline) {
          const underline = new VectorPath();
          underline.moveTo(mark.x, mark.y + mark.height - 2).lineTo(mark.x + mark.width, mark.y + mark.height - 2);
          scene.add(shapeMark(underline, null, Tone.of("ink"), 0.8));
        }
      }
      y += lineHeight;
    }
    if (section.length === 0) y += 6;
    y += 3;
  }
}
