// Measures and draws a chart's legend: a list of swatches and names, or a colour bar for a colour channel bound to numbers.
// Ported from Parcel NExT's Divooka.Graphics.Plotting/Rendering/LegendPainter.cs. The colour bar is measured and drawn as far as it
// can be without a colour map, which no Dhole chart has.

import type { LegendItem } from "./axis";
import { ChartPaints, type ColorAssignment } from "./contracts";
import { scaleTickFormat, ticks as d3Ticks } from "./d3";
import type { PlanLegend, TextPainter } from "./figure";
import { numberFormatter } from "./formatting";
import type { Sink } from "./sink";
import type { Theme } from "./theme";
import { RectF, VectorPath } from "../rendering/geometry";

const Swatch = 12;
const LineSwatch = 18;
const SwatchGap = 6;
const EntryGap = 16;
const RowGap = 4;
const BarThickness = 12;

/** Where a legend entry went, for a caller that wants to point at it. */
export interface LegendEntryBox {
  readonly label: string;
  readonly box: RectF;
}

export class LegendPainter implements PlanLegend {
  private readonly theme: Theme;
  private readonly text: TextPainter;
  private readonly items: readonly LegendItem[];
  private readonly bar: ColorAssignment | null;
  private readonly title: string | null;

  constructor(theme: Theme, text: TextPainter, items: readonly LegendItem[], colorBar: ColorAssignment | null, title: string | null) {
    this.theme = theme;
    this.text = text;
    this.items = items;
    this.bar = colorBar;
    this.title = title ?? colorBar?.title ?? null;
  }

  /** Whether there is anything to draw. */
  get isEmpty(): boolean {
    return this.items.length === 0 && this.bar === null;
  }

  private get titleBlock(): number {
    return !this.title ? 0 : this.text.lineHeight("legendTitle") + RowGap;
  }
  private get rowHeight(): number {
    return Math.max(this.text.lineHeight("legend"), Swatch);
  }

  /**
   * How many entries a column of `height` holds. Divooka works this out in single precision, and again from the drawn box's height
   * when it draws: a box whose float edges lose an ulp can then hold one row fewer than it was measured for, and the last entry goes
   * to a column of its own past the legend's edge. That turns on the last bit of a text's measured height, which no measurer here
   * reproduces, so this keeps every entry where it was measured: a column a hair short of its last row - the drawn box's height
   * recomputed from its edges, a thousandth of a pixel under the height it was measured as - still holds it.
   */
  private perColumn(height: number): number {
    return Math.max(1, Math.trunc((height - this.titleBlock + RowGap + 1e-3) / (this.rowHeight + RowGap)));
  }

  /** The height of `rows` rows under the title. */
  private columnHeight(rows: number): number {
    return this.titleBlock + rows * this.rowHeight + (rows - 1) * RowGap;
  }

  private swatchWidth(item: LegendItem): number {
    return item.swatch === "line" || item.swatch === "lineAndPoint" ? LineSwatch : Swatch;
  }
  private entryWidth(item: LegendItem): number {
    return this.swatchWidth(item) + SwatchGap + this.text.measure(item.label, "legend").width;
  }

  /** The size of a legend stacked in a column no taller than `maxHeight`, wrapping into more columns when it must. */
  measureColumn(maxHeight: number): { width: number; height: number } {
    if (this.isEmpty) return { width: 0, height: 0 };
    if (this.bar !== null) return this.measureBar(maxHeight);
    const titleWidth = !this.title ? 0 : this.text.measure(this.title, "legendTitle").width;
    const perColumn = this.perColumn(maxHeight);
    const columns = Math.ceil(this.items.length / perColumn);
    let width = 0;
    for (let c = 0; c < columns; c++) {
      const columnWidth = Math.max(...this.items.slice(c * perColumn, (c + 1) * perColumn).map((i) => this.entryWidth(i)));
      width += columnWidth + (c > 0 ? EntryGap : 0);
    }
    const rows = Math.min(this.items.length, perColumn);
    return { width: Math.max(width, titleWidth), height: this.columnHeight(rows) };
  }

  /** The size of a legend flowed in rows no wider than `maxWidth`. */
  measureRow(maxWidth: number): { width: number; height: number } {
    if (this.isEmpty) return { width: 0, height: 0 };
    if (this.bar !== null) {
      const labels = this.text.lineHeight("tick");
      return { width: maxWidth, height: this.titleBlock + BarThickness + 4 + labels };
    }
    const rows = this.flowRows(maxWidth).length;
    return { width: maxWidth, height: this.columnHeight(rows) };
  }

  private flowRows(maxWidth: number): LegendItem[][] {
    const rows: LegendItem[][] = [[]];
    let x = 0;
    for (const item of this.items) {
      const w = this.entryWidth(item);
      if (rows[rows.length - 1].length > 0 && x + EntryGap + w > maxWidth) {
        rows.push([]);
        x = 0;
      }
      x += (rows[rows.length - 1].length > 0 ? EntryGap : 0) + w;
      rows[rows.length - 1].push(item);
    }
    return rows;
  }

  private measureBar(maxHeight: number): { width: number; height: number } {
    const [ticks, format] = this.barTicks();
    const labelWidth = ticks.length === 0 ? 0 : Math.max(...ticks.map((t) => this.text.measure(format(t), "tick").width));
    const titleWidth = !this.title ? 0 : this.text.measure(this.title, "legendTitle").width;
    const height = Math.min(maxHeight, 220);
    return { width: Math.max(BarThickness + 4 + labelWidth, titleWidth), height };
  }

  private barTicks(): [number[], (value: number) => string] {
    const bar = this.bar!;
    const ticks = d3Ticks(bar.low, bar.high, 5);
    const format = bar.spec.format !== null ? numberFormatter(bar.spec.format) : scaleTickFormat(bar.low, bar.high, 5, null);
    return [ticks, format];
  }

  /** Draws the legend as a column with its top left at the rectangle's, and says where each entry went. */
  drawColumn(sink: Sink, box: RectF): LegendEntryBox[] {
    const boxes: LegendEntryBox[] = [];
    let y = box.top;
    if (this.title) {
      this.text.draw(sink, this.title, box.left, y, "legendTitle", this.theme.secondaryInk, "topLeft");
      y += this.titleBlock;
    }
    if (this.bar !== null) throw new Error("A colour bar is not drawn on this page.");
    const perColumn = this.perColumn(box.height);
    let x = box.left;
    for (let start = 0; start < this.items.length; start += perColumn) {
      const column = this.items.slice(start, start + perColumn);
      const columnWidth = Math.max(...column.map((i) => this.entryWidth(i)));
      let rowY = y;
      for (const item of column) {
        boxes.push(this.drawEntry(sink, item, x, rowY));
        rowY += this.rowHeight + RowGap;
      }
      x += columnWidth + EntryGap;
    }
    return boxes;
  }

  /** Draws the legend flowed in rows, each row starting at the rectangle's left. */
  drawRows(sink: Sink, box: RectF): LegendEntryBox[] {
    const boxes: LegendEntryBox[] = [];
    let y = box.top;
    if (this.title) {
      this.text.draw(sink, this.title, box.left, y, "legendTitle", this.theme.secondaryInk, "topLeft");
      y += this.titleBlock;
    }
    if (this.bar !== null) throw new Error("A colour bar is not drawn on this page.");
    for (const row of this.flowRows(box.width)) {
      let x = box.left;
      for (const item of row) {
        boxes.push(this.drawEntry(sink, item, x, y));
        x += this.entryWidth(item) + EntryGap;
      }
      y += this.rowHeight + RowGap;
    }
    return boxes;
  }

  private drawEntry(sink: Sink, item: LegendItem, x: number, y: number): LegendEntryBox {
    const mid = y + this.rowHeight / 2;
    const swatchWidth = this.swatchWidth(item);
    switch (item.swatch) {
      case "line":
        sink.drawLine(x, mid, x + swatchWidth, mid, ChartPaints.stroke(item.color, this.theme.lineWidth));
        break;
      case "lineAndPoint":
        sink.drawLine(x, mid, x + swatchWidth, mid, ChartPaints.stroke(item.color, this.theme.lineWidth));
        sink.drawPath(new VectorPath().addCircle(x + swatchWidth / 2, mid, this.theme.pointSize / 2), ChartPaints.fill(item.color));
        break;
      case "point":
        sink.drawPath(new VectorPath().addCircle(x + Swatch / 2, mid, this.theme.pointSize / 2), ChartPaints.fill(item.color));
        break;
      default:
        sink.drawPath(new VectorPath().addRoundRect(RectF.fromXYWH(x, mid - Swatch / 2, Swatch, Swatch), 2.5, 2.5), ChartPaints.fill(item.color));
        break;
    }
    const labelX = x + swatchWidth + SwatchGap;
    this.text.draw(sink, item.label, labelX, mid, "legend", this.theme.secondaryInk, "left");
    const labelWidth = this.text.measure(item.label, "legend").width;
    return { label: item.label, box: new RectF(x, y, labelX + labelWidth, y + this.rowHeight) };
  }
}
