// Dhole on a page: drawing a text into an element, drawing every Dhole code block of a page, and <dhole-diagram>, an element
// that draws the text it holds.
//
// The picture is SVG, its words kept as text in the faces they were measured in, so it scales, prints, and reads to a screen
// reader: its <title> is the diagram's title and its <desc> says what it draws in a sentence.

import { read, toSvg, type DholeOptions, type DholeResult } from "./dhole";
import { findTheme, withFont, type Theme } from "./plot/theme";
import { cssFont } from "./plot/text";
import { English } from "./syntax/problems";

/** How a page draws a text. */
export interface RenderOptions extends DholeOptions {
  /** The theme a diagram has when its text names none, by name - light, dark, presentation, minimal, classic, print, golden, quiet gold, silver gold, high contrast - or as a theme. */
  readonly theme?: string | Theme;
  /** A font to set every word in first, the theme's own families kept after it as fallbacks. */
  readonly font?: string;
  /** The language problems are said in: English (the default) or Chinese. */
  readonly language?: string;
  /** Whether the problems are listed under the picture; on by default. */
  readonly problems?: boolean;
}

function options(of: RenderOptions): DholeOptions {
  const theme = typeof of.theme === "string" ? findTheme(of.theme) ?? undefined : of.theme;
  const font = of.font;
  const adjust = of.adjustTheme;
  return {
    measurer: of.measurer,
    defaultTheme: theme,
    adjustTheme: font || adjust ? (t: Theme) => (adjust ? adjust(font ? withFont(t, font) : t) : withFont(t, font!)) : undefined,
  };
}

function escapeHtml(text: string): string {
  return text.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;");
}

/** The problems of a result as an HTML list, or an empty string when there are none. */
export function problemsHtml(result: DholeResult, language: string = English): string {
  if (result.problems.length === 0) return "";
  const items = result.problems.map((p) => `<li class="dhole-problem dhole-${p.severity}" data-line="${p.line}" data-column="${p.column}">${escapeHtml(p.describe(language))}</li>`).join("");
  return `<ul class="dhole-problems">${items}</ul>`;
}

/**
 * Draws Dhole text into `target`, replacing what it held: the picture, and under it the problems when there are any (unless
 * `problems: false`). Returns what was read, so a page can say more.
 */
export function render(text: string, target: Element, renderOptions: RenderOptions = {}): DholeResult {
  const result = read(text, options(renderOptions));
  const picture = result.figure ? toSvg(result.figure, { measurer: result.measurer, description: result.summary }) : "";
  const problems = renderOptions.problems === false ? "" : problemsHtml(result, renderOptions.language);
  target.innerHTML = `<div class="dhole-picture">${picture}</div>${problems}`;
  return result;
}

/** Waits for the faces a text will be measured in, so a web font is measured as it is drawn rather than as its fallback. */
export async function fontsReady(renderOptions: RenderOptions = {}): Promise<void> {
  if (typeof document === "undefined" || !document.fonts) return;
  const families = renderOptions.font ? [renderOptions.font] : [];
  try {
    for (const weight of [400, 600]) for (const family of families) await document.fonts.load(cssFont({ families: [family], size: 12, weight }));
    await document.fonts.ready;
  } catch {
    // A face that cannot be loaded is measured as its fallback, which is what is drawn too.
  }
}

const elementStyles = `
:host { display: block; }
.dhole-picture svg { display: block; max-width: 100%; height: auto; }
.dhole-problems { margin: 8px 0 0; padding: 0; list-style: none; font: 13px/1.45 system-ui, sans-serif; }
.dhole-problem { padding: 4px 8px; border-left: 3px solid #e34948; background: rgba(227, 73, 72, 0.08); margin-top: 4px; }
.dhole-problem.dhole-warning { border-left-color: #eda100; background: rgba(237, 161, 0, 0.1); }
`;

/**
 * `<dhole-diagram>`: draws the Dhole text it holds, in its own shadow root so a page's styles neither reach the picture nor are
 * reached by it, and draws it again when the text changes. Attributes: `theme`, `font`, `language` (problems' language) and
 * `problems="hide"`.
 */
export function defineElement(name = "dhole-diagram"): void {
  if (typeof customElements === "undefined" || customElements.get(name)) return;
  class DholeDiagram extends HTMLElement {
    static get observedAttributes(): string[] {
      return ["theme", "font", "language", "problems"];
    }
    private observer: MutationObserver | null = null;
    private scheduled = false;
    /** What the last drawing read, for a page that wants to say more. */
    result: DholeResult | null = null;

    connectedCallback(): void {
      if (!this.shadowRoot) this.attachShadow({ mode: "open" });
      this.observer = new MutationObserver(() => this.schedule());
      this.observer.observe(this, { childList: true, characterData: true, subtree: true });
      this.schedule();
    }
    disconnectedCallback(): void {
      this.observer?.disconnect();
      this.observer = null;
    }
    attributeChangedCallback(): void {
      if (this.isConnected) this.schedule();
    }
    private get renderOptions(): RenderOptions {
      return {
        theme: this.getAttribute("theme") ?? undefined,
        font: this.getAttribute("font") ?? undefined,
        language: this.getAttribute("language") ?? undefined,
        problems: this.getAttribute("problems") !== "hide",
      };
    }
    private schedule(): void {
      if (this.scheduled) return;
      this.scheduled = true;
      const go = () =>
        fontsReady(this.renderOptions).then(() => {
          this.scheduled = false;
          this.draw();
        });
      queueMicrotask(go);
    }
    private draw(): void {
      const root = this.shadowRoot!;
      const host = document.createElement("div");
      this.result = render(this.textContent ?? "", host, this.renderOptions);
      root.innerHTML = `<style>${elementStyles}</style>`;
      root.append(...Array.from(host.childNodes));
      this.dispatchEvent(new CustomEvent("dhole-rendered", { detail: this.result, bubbles: true }));
    }
  }
  customElements.define(name, DholeDiagram);
}

/**
 * Turns every Dhole code block of a page - `<pre><code class="language-dhole">`, as Markdown writes a ```dhole fence, or anything
 * matching `selector` - into a `<dhole-diagram>` holding its text. Returns how many it turned.
 */
export function renderAll(selector = "pre > code.language-dhole, pre.dhole, div.dhole", renderOptions: RenderOptions = {}): number {
  if (typeof document === "undefined") return 0;
  defineElement();
  let count = 0;
  document.querySelectorAll(selector).forEach((found) => {
    const block = found.tagName === "CODE" && found.parentElement?.tagName === "PRE" ? found.parentElement : found;
    const diagram = document.createElement("dhole-diagram");
    for (const [attribute, value] of Object.entries({ theme: renderOptions.theme, font: renderOptions.font, language: renderOptions.language }))
      if (typeof value === "string") diagram.setAttribute(attribute, value);
    if (renderOptions.problems === false) diagram.setAttribute("problems", "hide");
    diagram.textContent = found.textContent ?? "";
    block.replaceWith(diagram);
    count++;
  });
  return count;
}
