// The layered layout of a directed graph - Sugiyama's method, as dagre and Graphviz's dot lay out flowcharts.
// Ported from Parcel NExT's Divooka.Visualization.Dhole/Layout/Layered.cs.
//
// The C# keeps its coordinates in single precision (float, Vector2) and its sums in double; the placement below rounds each stored float with Math.fround where the C# does, so a tie broken by comparing two places breaks the same way here.

import { RectF, vec, type Vec2 } from "../rendering/geometry";
import type { SizeF } from "../rendering/scene";
import type { Direction } from "./direction";

export type { Direction } from "./direction";

const f = Math.fround;

/** A box to place. */
export class LayeredNode {
  readonly width: number;
  readonly height: number;
  /** Extra room beside the box, on the side across the flow, for a line that loops back to it. */
  loopRoom = 0;
  /** Whether the box is held to the first rank, or to the last: a stub where a line crosses a group's frame. */
  pin = 0;
  /** Where the box's centre went. */
  center: Vec2 = vec(0, 0);

  constructor(width: number, height: number, init?: { pin?: number }) {
    this.width = width;
    this.height = height;
    if (init?.pin !== undefined) this.pin = init.pin;
  }

  /** The box once placed. */
  get box(): RectF {
    return RectF.fromXYWH(this.center.x - this.width / 2, this.center.y - this.height / 2, this.width, this.height);
  }
}

/** A line to route between two boxes. */
export class LayeredEdge {
  readonly from: number;
  readonly to: number;
  /** The size of the label the line carries, given a place of its own between the ranks. */
  readonly label: SizeF | null;
  /** How strongly the line pulls its ends into line. */
  readonly weight: number;
  /** The line's points, from its first box to its second, ending on each box's edge: where it leaves, where it bends, where it arrives. */
  readonly points: Vec2[] = [];
  /** The centre of the line's label. */
  labelCenter: Vec2 = vec(0, 0);
  /** Whether the line goes against the flow: it closes a loop. */
  againstFlow = false;

  constructor(from: number, to: number, label: SizeF | null = null, weight = 1) {
    this.from = from;
    this.to = to;
    this.label = label;
    this.weight = weight;
  }

  /** Whether the line leaves and arrives at the same box. */
  get isLoop(): boolean {
    return this.from === this.to;
  }
}

class Vertex {
  width = 0;
  height = 0;
  rank = 0;
  order = 0;
  x = 0;
  real = -1;
  isLabel = false;
  readonly down: { to: number; weight: number }[] = [];
  readonly up: { from: number; weight: number }[] = [];
}

/** The smallest rectangle holding both, as Divooka's RectF.Union: an empty operand is ignored rather than absorbed. */
export function unionRect(a: RectF, b: RectF): RectF {
  if (a.isEmpty) return b;
  if (b.isEmpty) return a;
  return a.union(b);
}

/** The smallest rectangle holding a rectangle and a point, as Divooka's RectF.Union(Vector2). */
export function pointUnion(bounds: RectF, p: Vec2): RectF {
  if (bounds.isEmpty) return new RectF(p.x, p.y, p.x, p.y);
  return new RectF(Math.min(bounds.left, p.x), Math.min(bounds.top, p.y), Math.max(bounds.right, p.x), Math.max(bounds.bottom, p.y));
}

/**
 * The layered layout of a directed graph - Sugiyama's method, as dagre and Graphviz's dot lay out flowcharts - in four steps: break cycles, give each box a rank along the flow, order each rank to cross as few lines as possible, and place the boxes across the flow so lines run as straight as they can.
 *
 * Every step is deterministic: ties are broken by the order the boxes and lines were written in, so the same text always gives the same picture.
 *
 * Ranking is longest-path, with each source pulled down to sit just above what it leads to. A line spanning several ranks passes through a waypoint in each; a labelled line has its label as one of those waypoints, at the middle rank, so labels are placed like boxes and never sit on one - when any line has a label, every line spans two half-ranks, as dagre does, so the spacing stays even.
 *
 * Ordering sweeps the ranks down and up twenty-four times, sorting each by the barycentre of its neighbours, then swaps neighbours while that removes crossings, keeping the best order seen.
 *
 * Placement is the least-squares balance of every box against the boxes it is joined to, solved by sweeps that move each box toward the weighted mean of its neighbours and then project each rank back onto its separation constraints exactly - pool-adjacent-violators on the gaps. Waypoints of one line pull hardest on each other, so long lines run straight.
 */
export const Layered = {
  run,
  project,
};

/**
 * Places `nodes` and routes `edges`.
 * @param nodes The boxes, whose centres are set.
 * @param edges The lines, whose points are set.
 * @param direction Which way the flow runs.
 * @param nodeGap The least space between two boxes of one rank.
 * @param rankGap The space between ranks.
 * @returns The bounds of everything placed.
 */
export function run(nodes: readonly LayeredNode[], edges: readonly LayeredEdge[], direction: Direction, nodeGap = 28, rankGap = 44): RectF {
  if (nodes.length === 0) return new RectF(0, 0, 0, 0);
  const across = direction === "right" || direction === "left";
  // Laid out flowing down; a diagram flowing across swaps each box's sides now and its coordinates at the end.
  const W = (i: number): number => f((across ? nodes[i].height : nodes[i].width) + nodes[i].loopRoom);
  const H = (i: number): number => (across ? nodes[i].width : nodes[i].height);

  const lines = edges.filter((e) => !e.isLoop && e.from >= 0 && e.to >= 0 && e.from < nodes.length && e.to < nodes.length);
  const labelled = lines.some((e) => e.label !== null);
  const span = labelled ? 2 : 1;

  // 1. Cycles: a depth-first walk in written order; a line back to a box still being walked is turned round.
  const reversed = breakCycles(nodes.length, lines);

  // 2. Ranks.
  const rank = rankNodes(nodes.length, lines, reversed, span, nodes.map((n) => n.pin));

  // 3. Waypoints: every line becomes a chain of vertices, one per rank it crosses.
  const vertices: Vertex[] = [];
  for (let i = 0; i < nodes.length; i++) {
    const v = new Vertex();
    v.width = W(i);
    v.height = H(i);
    v.rank = rank[i];
    v.real = i;
    vertices.push(v);
  }
  const chains: number[][] = [];
  for (let e = 0; e < lines.length; e++) {
    const line = lines[e];
    const top = reversed[e] ? line.to : line.from;
    const bottom = reversed[e] ? line.from : line.to;
    const chain = [top];
    const labelRank = rank[top] + Math.max(1, Math.trunc((rank[bottom] - rank[top]) / 2));
    for (let r = rank[top] + 1; r < rank[bottom]; r++) {
      const isLabel = line.label !== null && r === labelRank;
      const size = isLabel ? line.label! : { width: 0, height: 0 };
      const v = new Vertex();
      v.width = isLabel ? (across ? size.height : size.width) : 2;
      v.height = isLabel ? (across ? size.width : size.height) : 0;
      v.rank = r;
      v.isLabel = isLabel;
      vertices.push(v);
      chain.push(vertices.length - 1);
    }
    chain.push(bottom);
    for (let k = 0; k + 1 < chain.length; k++) {
      const inner = vertices[chain[k]].real < 0 && vertices[chain[k + 1]].real < 0;
      const weight = f(line.weight * (inner ? 8 : vertices[chain[k]].real < 0 || vertices[chain[k + 1]].real < 0 ? 2 : 1));
      vertices[chain[k]].down.push({ to: chain[k + 1], weight });
      vertices[chain[k + 1]].up.push({ from: chain[k], weight });
    }
    chains.push(chain);
  }

  const ranks = Math.max(...vertices.map((v) => v.rank)) + 1;
  const layers: number[][] = Array.from({ length: ranks }, () => []);

  // 4. Order: first by a depth-first walk from the sources in written order, then by barycentre sweeps.
  initialOrder(vertices, layers);
  order(vertices, layers);

  // 5. Across the flow: balanced placement.
  place(vertices, layers, nodeGap);

  // 6. Along the flow: each rank as tall as its tallest box, the gaps between them even.
  const rankTop = new Array<number>(ranks).fill(0);
  const rankHeight = new Array<number>(ranks).fill(0);
  for (let r = 0; r < ranks; r++) rankHeight[r] = layers[r].length === 0 ? 0 : Math.max(...layers[r].map((v) => vertices[v].height));
  const gap = labelled ? rankGap / 2 : rankGap;
  let y = 0;
  for (let r = 0; r < ranks; r++) {
    rankTop[r] = y;
    y = f(y + rankHeight[r] + gap);
  }

  const point = (x: number, yy: number): Vec2 => {
    switch (direction) {
      case "up":
        return vec(x, -yy);
      case "right":
        return vec(yy, x);
      case "left":
        return vec(-yy, x);
      default:
        return vec(x, yy);
    }
  };

  for (let i = 0; i < nodes.length; i++) {
    const v = vertices[i];
    // A box with room for a loop sits at the start of its room, the loop beside it.
    const cx = v.x - nodes[i].loopRoom / 2;
    nodes[i].center = point(cx, rankTop[v.rank] + rankHeight[v.rank] / 2);
  }

  // 7. Lines: through their waypoints, leaving the bottom of the higher box and entering the top of the lower one, spread along those sides when several share one.
  const ports = new Map<string, { line: number; toward: number }[]>();
  const portKey = (vertex: number, bottom: boolean): string => `${vertex}:${bottom}`;
  for (let e = 0; e < lines.length; e++) {
    const chain = chains[e];
    const topVertex = chain[0];
    const bottomVertex = chain[chain.length - 1];
    const towardBelow = vertices[chain[1]].x;
    const towardAbove = vertices[chain[chain.length - 2]].x;
    port(ports, portKey(topVertex, true), e, towardBelow);
    port(ports, portKey(bottomVertex, false), e, towardAbove);
  }
  const portX = (vertex: number, bottom: boolean, line: number): number => {
    const v = vertices[vertex];
    const shared = ports.get(portKey(vertex, bottom));
    if (!shared || shared.length < 2 || v.real < 0) return v.x - (v.real >= 0 ? nodes[v.real].loopRoom / 2 : 0);
    const sorted = shared.map((s, i) => ({ s, i })).sort((a, b) => a.s.toward - b.s.toward || a.s.line - b.s.line || a.i - b.i).map((e) => e.s);
    const index = sorted.findIndex((s) => s.line === line);
    const width = f((v.width - nodes[v.real].loopRoom) * 0.6);
    const left = v.x - nodes[v.real].loopRoom / 2 - width / 2;
    return left + (width * (index + 0.5)) / sorted.length;
  };
  for (let e = 0; e < lines.length; e++) {
    const line = lines[e];
    const chain = chains[e];
    const points: Vec2[] = [];
    const first = vertices[chain[0]];
    const last = vertices[chain[chain.length - 1]];
    points.push(point(portX(chain[0], true, e), rankTop[first.rank] + rankHeight[first.rank] / 2 + first.height / 2));
    for (let k = 1; k + 1 < chain.length; k++) {
      const v = vertices[chain[k]];
      const centre = rankTop[v.rank] + rankHeight[v.rank] / 2;
      if (v.isLabel) {
        line.labelCenter = point(v.x, centre);
        // A label sits beside the line rather than on it only when there is no room; on it, it reads as the line's own.
        points.push(point(v.x, centre));
      } else points.push(point(v.x, centre));
    }
    points.push(point(portX(chain[chain.length - 1], false, e), rankTop[last.rank] + rankHeight[last.rank] / 2 - last.height / 2));
    if (reversed[e]) {
      points.reverse();
      line.againstFlow = true;
    }
    if (line.label !== null && chain.length === 2) line.labelCenter = vec((points[0].x + points[points.length - 1].x) / 2, (points[0].y + points[points.length - 1].y) / 2);
    line.points.length = 0;
    line.points.push(...points);
  }

  // 8. Loops: out of the side of the box across the flow and back in.
  for (const loop of edges.filter((e) => e.isLoop && e.from >= 0 && e.from < nodes.length)) {
    const node = nodes[loop.from];
    const box = node.box;
    const reach = 26;
    let points: Vec2[];
    if (across) {
      points = [vec(box.midX - box.width * 0.22, box.bottom), vec(box.midX, box.bottom + reach), vec(box.midX + box.width * 0.22, box.bottom)];
      loop.labelCenter = vec(box.midX, box.bottom + reach + (loop.label?.height ?? 0) / 2 + 4);
    } else {
      points = [vec(box.right, box.midY - box.height * 0.22), vec(box.right + reach, box.midY), vec(box.right, box.midY + box.height * 0.22)];
      loop.labelCenter = vec(box.right + reach + (loop.label?.width ?? 0) / 2 + 6, box.midY);
    }
    loop.points.length = 0;
    loop.points.push(...points);
  }

  let bounds = nodes[0].box;
  for (const node of nodes) bounds = unionRect(bounds, node.box);
  for (const edge of edges) {
    for (const p of edge.points) bounds = pointUnion(bounds, p);
    if (edge.label !== null) {
      const label = edge.label;
      bounds = unionRect(bounds, RectF.fromXYWH(edge.labelCenter.x - label.width / 2, edge.labelCenter.y - label.height / 2, label.width, label.height));
    }
  }
  return bounds;
}

function port(ports: Map<string, { line: number; toward: number }[]>, key: string, line: number, toward: number): void {
  let list = ports.get(key);
  if (!list) ports.set(key, (list = []));
  list.push({ line, toward });
}

// ---------------------------------------------------------------- cycles and ranks

function breakCycles(count: number, lines: readonly LayeredEdge[]): boolean[] {
  const reversed = new Array<boolean>(lines.length).fill(false);
  const outgoing: number[][] = Array.from({ length: count }, () => []);
  for (let e = 0; e < lines.length; e++) outgoing[lines[e].from].push(e);
  const state = new Array<number>(count).fill(0); // 0 unvisited, 1 on the walk, 2 done
  // Sources first, in written order, then whatever a cycle left unreached.
  const hasIncoming = new Array<boolean>(count).fill(false);
  for (const line of lines) hasIncoming[line.to] = true;
  const starts: number[] = [];
  for (let i = 0; i < count; i++) if (!hasIncoming[i]) starts.push(i);
  for (let i = 0; i < count; i++) starts.push(i);
  for (const start of starts) {
    if (state[start] !== 0) continue;
    const stack: [number, number][] = [];
    stack.push([start, 0]);
    state[start] = 1;
    while (stack.length > 0) {
      const [node, next] = stack.pop()!;
      if (next < outgoing[node].length) {
        stack.push([node, next + 1]);
        const e = outgoing[node][next];
        const to = lines[e].to;
        if (state[to] === 1) reversed[e] = true;
        else if (state[to] === 0) {
          state[to] = 1;
          stack.push([to, 0]);
        }
      } else state[node] = 2;
    }
  }
  return reversed;
}

function rankNodes(count: number, lines: readonly LayeredEdge[], reversed: readonly boolean[], span: number, pins: readonly number[]): number[] {
  const down: number[][] = Array.from({ length: count }, () => []);
  const up: number[][] = Array.from({ length: count }, () => []);
  for (let e = 0; e < lines.length; e++) {
    const a = reversed[e] ? lines[e].to : lines[e].from;
    const b = reversed[e] ? lines[e].from : lines[e].to;
    if (a === b) continue;
    down[a].push(b);
    up[b].push(a);
  }
  // Kahn's order, smallest written index first, so ranks follow the text.
  const indegree = up.map((u) => u.length);
  const ready = new Set<number>();
  for (let i = 0; i < count; i++) if (indegree[i] === 0) ready.add(i);
  const order: number[] = [];
  while (ready.size > 0) {
    let node = Number.MAX_SAFE_INTEGER;
    for (const r of ready) if (r < node) node = r;
    ready.delete(node);
    order.push(node);
    for (const next of down[node]) if (--indegree[next] === 0) ready.add(next);
  }
  // Anything left is in a cycle the walk missed, which cannot happen; placed after the rest all the same.
  for (let i = 0; i < count; i++) if (!order.includes(i)) order.push(i);

  const rank = new Array<number>(count).fill(0);
  for (const node of order) for (const previous of up[node]) rank[node] = Math.max(rank[node], rank[previous] + span);
  // A source sits just above the nearest thing it leads to, rather than at the top of the page.
  for (let pass = 0; pass < 2; pass++)
    for (let k = order.length - 1; k >= 0; k--) {
      const node = order[k];
      if (up[node].length === 0 && down[node].length > 0 && pins[node] === 0) rank[node] = Math.min(...down[node].map((next) => rank[next])) - span;
    }
  const unpinned: number[] = [];
  for (let i = 0; i < count; i++) if (pins[i] === 0) unpinned.push(rank[i]);
  let lowest = rank.length === 0 ? 0 : unpinned.length === 0 ? 0 : Math.min(...unpinned);
  for (let i = 0; i < count; i++) rank[i] -= lowest;
  // Pinned boxes: a first above everything it leads to and on the first rank; a last below everything and on the last.
  const unpinnedAfter: number[] = [];
  for (let i = 0; i < count; i++) if (pins[i] === 0) unpinnedAfter.push(rank[i]);
  const highest = unpinnedAfter.length === 0 ? 0 : Math.max(...unpinnedAfter);
  for (let i = 0; i < count; i++) {
    if (pins[i] === 1) rank[i] = Math.min(0, down[i].length === 0 ? 0 : Math.min(...down[i].map((next) => rank[next] - span)));
    else if (pins[i] === 2) rank[i] = Math.max(highest, up[i].length === 0 ? highest : Math.max(...up[i].map((previous) => rank[previous] + span)));
  }
  lowest = rank.length === 0 ? 0 : Math.min(...rank);
  for (let i = 0; i < count; i++) rank[i] -= lowest;
  return rank;
}

// ---------------------------------------------------------------- order

function initialOrder(vertices: Vertex[], layers: number[][]): void {
  const seen = new Array<boolean>(vertices.length).fill(false);
  const visit = (start: number): void => {
    const stack: number[] = [start];
    while (stack.length > 0) {
      const v = stack.pop()!;
      if (seen[v]) continue;
      seen[v] = true;
      layers[vertices[v].rank].push(v);
      for (let k = vertices[v].down.length - 1; k >= 0; k--) if (!seen[vertices[v].down[k].to]) stack.push(vertices[v].down[k].to);
    }
  };
  for (let v = 0; v < vertices.length; v++) if (vertices[v].up.length === 0 && vertices[v].real >= 0) visit(v);
  for (let v = 0; v < vertices.length; v++) if (!seen[v]) visit(v);
  for (const layer of layers) for (let k = 0; k < layer.length; k++) vertices[layer[k]].order = k;
}

function order(vertices: Vertex[], layers: number[][]): void {
  let best = crossings(vertices, layers);
  let bestLayers = layers.map((l) => [...l]);
  for (let iteration = 0; iteration < 24 && best > 0; iteration++) {
    const downward = iteration % 2 === 0;
    if (downward) for (let r = 1; r < layers.length; r++) sortByBarycentre(vertices, layers[r], true);
    else for (let r = layers.length - 2; r >= 0; r--) sortByBarycentre(vertices, layers[r], false);
    transpose(vertices, layers);
    const count = crossings(vertices, layers);
    if (count < best) {
      best = count;
      bestLayers = layers.map((l) => [...l]);
    }
  }
  for (let r = 0; r < layers.length; r++) {
    layers[r].length = 0;
    layers[r].push(...bestLayers[r]);
    for (let k = 0; k < layers[r].length; k++) vertices[layers[r][k]].order = k;
  }
}

function sortByBarycentre(vertices: Vertex[], layer: number[], up: boolean): void {
  const keyed: { vertex: number; key: number; was: number }[] = [];
  for (const v of layer) {
    const vertex = vertices[v];
    let sum = 0;
    let weight = 0;
    if (up)
      for (const { from, weight: w } of vertex.up) {
        sum += vertices[from].order * w;
        weight += w;
      }
    else
      for (const { to, weight: w } of vertex.down) {
        sum += vertices[to].order * w;
        weight += w;
      }
    keyed.push({ vertex: v, key: weight > 0 ? sum / weight : vertex.order, was: vertex.order });
  }
  keyed.sort((a, b) => (a.key !== b.key ? (a.key < b.key ? -1 : 1) : a.was - b.was));
  layer.length = 0;
  for (let k = 0; k < keyed.length; k++) {
    layer.push(keyed[k].vertex);
    vertices[keyed[k].vertex].order = k;
  }
}

function transpose(vertices: Vertex[], layers: number[][]): void {
  for (let pass = 0; pass < 4; pass++) {
    let improved = false;
    for (let r = 0; r < layers.length; r++) {
      const layer = layers[r];
      for (let k = 0; k + 1 < layer.length; k++) {
        const a = layer[k];
        const b = layer[k + 1];
        const before = pairCrossings(vertices, a, b);
        const after = pairCrossings(vertices, b, a);
        if (after < before) {
          layer[k] = b;
          layer[k + 1] = a;
          vertices[b].order = k;
          vertices[a].order = k + 1;
          improved = true;
        }
      }
    }
    if (!improved) break;
  }
}

/** How many crossings the lines of `left` and `right` make with each other, with left placed first. */
function pairCrossings(vertices: Vertex[], left: number, right: number): number {
  let count = 0;
  for (const { from: a } of vertices[left].up) for (const { from: b } of vertices[right].up) if (vertices[a].order > vertices[b].order) count++;
  for (const { to: a } of vertices[left].down) for (const { to: b } of vertices[right].down) if (vertices[a].order > vertices[b].order) count++;
  return count;
}

function crossings(vertices: Vertex[], layers: number[][]): number {
  let count = 0;
  for (let r = 0; r + 1 < layers.length; r++) {
    const segments: [number, number][] = [];
    for (const v of layers[r]) for (const { to } of vertices[v].down) segments.push([vertices[v].order, vertices[to].order]);
    for (let i = 0; i < segments.length; i++)
      for (let j = i + 1; j < segments.length; j++) if ((segments[i][0] - segments[j][0]) * (segments[i][1] - segments[j][1]) < 0) count++;
  }
  return count;
}

// ---------------------------------------------------------------- placement

function place(vertices: Vertex[], layers: number[][], nodeGap: number): void {
  // Packed from the left, each rank centred on the widest.
  for (const layer of layers) {
    let x = 0;
    for (let k = 0; k < layer.length; k++) {
      const v = vertices[layer[k]];
      if (k > 0) x = f(x + separation(vertices[layer[k - 1]], v, nodeGap));
      v.x = x;
    }
    const shift = layer.length === 0 ? 0 : f((vertices[layer[0]].x + vertices[layer[layer.length - 1]].x) / 2);
    for (const v of layer) vertices[v].x = f(vertices[v].x - shift);
  }

  for (let iteration = 0; iteration < 40; iteration++) {
    const downward = iteration % 2 === 0;
    const sweep: number[] = [];
    for (let r = 0; r < layers.length; r++) sweep.push(r);
    if (!downward) sweep.reverse();
    for (const r of sweep) {
      const layer = layers[r];
      if (layer.length === 0) continue;
      const target = new Array<number>(layer.length).fill(0);
      for (let k = 0; k < layer.length; k++) {
        const v = vertices[layer[k]];
        let sum = 0;
        let weight = 0;
        for (const { from, weight: w } of v.up) {
          sum += f(vertices[from].x * w);
          weight += w;
        }
        for (const { to, weight: w } of v.down) {
          sum += f(vertices[to].x * w);
          weight += w;
        }
        target[k] = weight > 0 ? sum / weight : v.x;
      }
      const gaps: number[] = [];
      for (let k = 0; k < layer.length - 1; k++) gaps.push(separation(vertices[layer[k]], vertices[layer[k + 1]], nodeGap));
      const placed = project(target, gaps);
      for (let k = 0; k < layer.length; k++) vertices[layer[k]].x = f(placed[k]);
    }
  }

  straighten(vertices, layers, nodeGap);

  let left = 3.4028234663852886e38;
  for (const v of vertices) left = Math.min(left, f(v.x - v.width / 2));
  for (const v of vertices) v.x = f(v.x - left);
}

/**
 * Sets each chain - vertices joined one to the next by the only line out of the one and the only line into the other - on one straight line where its ranks have room, at the place of its best-connected member, so a run of single steps reads as a column rather than the gentle zigzag the balance left in it.
 */
function straighten(vertices: Vertex[], layers: number[][], nodeGap: number): void {
  const continues = (v: number): boolean => vertices[v].up.length === 1 && vertices[vertices[v].up[0].from].down.length === 1;
  for (let start = 0; start < vertices.length; start++) {
    if (continues(start)) continue;
    const chain = [start];
    let current = start;
    while (vertices[current].down.length === 1 && vertices[vertices[current].down[0].to].up.length === 1) {
      current = vertices[current].down[0].to;
      chain.push(current);
    }
    if (chain.length < 2) continue;
    // The first of the best-connected, a box before a waypoint: a stable sort, as LINQ's OrderByDescending.ThenBy is.
    let anchor = chain[0];
    const score = (v: number): [number, number] => [vertices[v].up.length + vertices[v].down.length, vertices[v].real < 0 ? 1 : 0];
    for (const v of chain) {
      const [c, w] = score(v);
      const [bc, bw] = score(anchor);
      if (c > bc || (c === bc && w < bw)) anchor = v;
    }
    let target = vertices[anchor].x;
    let low = -3.4028234663852886e38;
    let high = 3.4028234663852886e38;
    for (const v of chain) {
      const layer = layers[vertices[v].rank];
      const k = vertices[v].order;
      if (k > 0) low = Math.max(low, f(vertices[layer[k - 1]].x + separation(vertices[layer[k - 1]], vertices[v], nodeGap)));
      if (k + 1 < layer.length) high = Math.min(high, f(vertices[layer[k + 1]].x - separation(vertices[v], vertices[layer[k + 1]], nodeGap)));
    }
    if (low > high) continue;
    target = Math.min(Math.max(target, low), high);
    for (const v of chain) vertices[v].x = target;
  }
}

function separation(a: Vertex, b: Vertex, nodeGap: number): number {
  const aWay = a.real < 0 && !a.isLabel;
  const bWay = b.real < 0 && !b.isLabel;
  // Two waypoints keep a line's width apart; a waypoint and a box keep half a gap.
  const gap = aWay && bWay ? f(nodeGap * f(0.35)) : aWay || bWay ? f(nodeGap * f(0.6)) : nodeGap;
  return f(f((a.width + b.width) / 2) + gap);
}

/**
 * The positions nearest `target` in the least-squares sense that keep each one at least its gap after the one before: pool-adjacent-violators on the targets less their cumulative gaps.
 */
export function project(target: readonly number[], gaps: readonly number[]): number[] {
  const n = target.length;
  const offset = new Array<number>(n).fill(0);
  for (let k = 1; k < n; k++) offset[k] = offset[k - 1] + gaps[k - 1];
  // Isotonic regression of (target - offset): blocks of pooled values, each the mean of what it pools.
  const blocks: { sum: number; count: number }[] = [];
  for (let k = 0; k < n; k++) {
    blocks.push({ sum: target[k] - offset[k], count: 1 });
    while (blocks.length > 1 && blocks[blocks.length - 2].sum / blocks[blocks.length - 2].count > blocks[blocks.length - 1].sum / blocks[blocks.length - 1].count) {
      const { sum: s, count: c } = blocks.pop()!;
      const last = blocks[blocks.length - 1];
      blocks[blocks.length - 1] = { sum: last.sum + s, count: last.count + c };
    }
  }
  const result = new Array<number>(n).fill(0);
  let index = 0;
  for (const { sum, count } of blocks) {
    const mean = sum / count;
    for (let k = 0; k < count; k++, index++) result[index] = mean + offset[index];
  }
  return result;
}
