// The four diagrams of boxes and lines - flowcharts, state diagrams, class diagrams and entity diagrams - and the colour words every kind shares.
// Ported from Parcel NExT's Divooka.Visualization.Dhole/Kinds/GraphKinds.cs.

import type { Block, Span } from "../syntax/source";
import { isWhiteSpace } from "../syntax/source";
import { Said } from "../syntax/problems";
import * as Scan from "../syntax/scan";
import { ArrowSet, type Arrow, type LineStyle, type Ref } from "../syntax/scan";
import { DiagramSpec, Grammar, KindParser, registerKind, setting, type BuildContext, type Built, type KindInfo, type ReadContext, type Setting } from "../syntax/reader";
import type { SourceLine } from "../syntax/source";
import type { ProblemList } from "../syntax/problems";
import { Tone, type NamedHue } from "../rendering/tones";
import type { NodeShape } from "../rendering/shapes";
import { DiagramLayer } from "../rendering/scene";
import { chartOf } from "../plot/figure";
import { AttributeWords } from "./attribute-words";

export { AttributeWords };
import type { Direction } from "../layout/direction";
import { Compartments, GraphDiagram, GraphEdge, GraphGroup, GraphModel, compartmentLine, type CompartmentLine, type GraphNode } from "../layout/graph-diagram";

/** A diagram of boxes and lines: a flowchart, a state diagram, a class diagram or an entity diagram. */
export class GraphSpec extends DiagramSpec {
  readonly model = new GraphModel();
  /** The words the summary counts boxes and lines in, one and many: steps and arrows, states and transitions. */
  boxes: { one: string; many: string } = { one: "box", many: "boxes" };
  lines: { one: string; many: string } = { one: "line", many: "lines" };

  constructor(kind: KindInfo, kindLine: SourceLine) {
    super(kind, kindLine);
  }

  override get isEmpty(): boolean {
    return this.model.nodes.length === 0 && this.model.groups.length === 0;
  }

  build(_problems: ProblemList, context: BuildContext): Built {
    const model = this.model;
    const scene = GraphDiagram.build(model, this.theme, context.measurer);
    const layer = new DiagramLayer(scene, this.kind.name.english, context.measurer);
    layer.label = this.title;
    const boxes = model.nodes.filter((n) => !(n.shape === "startDot" || n.shape === "endDot" || n.shape === "note")).length + model.groups.filter((g) => g.isState).length;
    const lines = model.edges.filter((e) => !(e.line === "dashed" && e.tip === "none" && e.tail === "none" && model.nodes[e.from]?.shape === "note")).length;
    const groups = model.groups.filter((g) => !g.isState).length;
    const english = this.kind.name.english;
    const article = Grammar.a(english);
    const summary = `${article[0].toUpperCase()}${article.slice(1)} ${english} of ${Grammar.count(boxes, this.boxes.one, this.boxes.many)} and ${Grammar.count(lines, this.lines.one, this.lines.many)}${groups > 0 ? " in " + Grammar.count(groups, "group") : ""}.`;
    return { chart: chartOf(layer), naturalWidth: scene.width, naturalHeight: scene.height, summary };
  }
}

const MutedWords = ["muted", "quiet", "faded", "disabled", "inactive"];
const LineWords = new Map<string, LineStyle>([
  ["dashed", "dashed"], ["dotted", "dashed"], ["thick", "thick"], ["bold", "thick"], ["solid", "solid"],
]);
const ColourChoices = ["blue", "orange", "green", "yellow", "pink", "purple", "red", "teal", "grey", "good", "bad", "warn", "accent", "muted"];
const noShapes = new Map<string, NodeShape>();

/** Whether a line starts with `word` as a word of its own: what follows it when it does, null when it does not. */
export function keyword(content: Span, word: string): Span | null {
  if (!content.startsWith(word) || content.length === word.length) {
    if (content.length === word.length && content.startsWith(word)) return content.from(word.length);
    return null;
  }
  const next = content.at(word.length);
  if (!isWhiteSpace(next) && next !== ":") return null;
  let after = content.from(word.length).trim();
  if (after.length > 0 && after.at(0) === ":") after = after.from(1).trim();
  return after;
}

/** An end of a line: a box, or a group (a composite state). */
type End = { index: number; isGroup: boolean };

/**
 * What the four diagrams of boxes and lines read alike: a box named at its first mention, a declaration giving it a longer label, attributes in brackets, chains of arrows with a label after a colon, groups indented under a `group` line, and notes.
 */
export abstract class GraphKindParser extends KindParser {
  private readonly shaped = new Set<GraphNode>();
  protected readonly graph: GraphSpec;

  constructor(context: ReadContext) {
    super(context);
    this.graph = new GraphSpec(context.kind, context.kindLine);
  }

  get spec(): DiagramSpec {
    return this.graph;
  }
  protected get model(): GraphModel {
    return this.graph.model;
  }
  protected get arrowSet(): ArrowSet {
    return ArrowSet.plain;
  }
  /** The thing a box is called in a problem: "a step", "a state". */
  protected abstract get boxWord(): Said;
  /** The shape a box has when nothing says otherwise. */
  protected get defaultShape(): NodeShape {
    return "box";
  }

  protected override get settings(): Setting[] {
    return [
      setting(["direction", "flow", "orientation", "layout", "rankdir"], (v) => {
        const d = this.readDirection(v);
        if (d !== null) this.model.direction = d;
      }),
    ];
  }

  /** Mermaid's direction after the kind's word - `graph TD`, `flowchart LR` - is a direction rather than a title. */
  protected override titled(): void {
    let direction: Direction | null = null;
    switch (this.spec.title?.trim().toUpperCase()) {
      case "TD":
      case "TB":
        direction = "down";
        break;
      case "LR":
        direction = "right";
        break;
      case "BT":
        direction = "up";
        break;
      case "RL":
        direction = "left";
        break;
    }
    if (direction !== null) {
      this.model.direction = direction;
      this.spec.title = null;
    }
  }

  // ---------------------------------------------------------------- words

  /** The colours an attribute can name, and the roles that stand for colours. */
  protected static get hueWords(): ReadonlyMap<string, NamedHue> {
    return AttributeWords.hues;
  }
  /** The words an attribute of a box can be besides a colour: its shapes, for a flowchart. */
  protected get shapeWords(): ReadonlyMap<string, NodeShape> {
    return noShapes;
  }
  /** Every word a box's attribute can be, for finding the one a slip was meant to be. */
  protected get attributeChoices(): string[] {
    return [...this.shapeWords.keys(), ...ColourChoices, ...this.extraAttributeWords];
  }
  /** The words a hint lists: each shape once, by its plainest name, then the colours and roles. */
  protected get attributeHint(): string[] {
    return [...this.primaryShapes, ...ColourChoices, ...this.extraAttributeWords];
  }
  /** Each shape a box can have, once, by its plainest name. */
  protected get primaryShapes(): string[] {
    return [];
  }
  protected get extraAttributeWords(): string[] {
    return [];
  }

  // ---------------------------------------------------------------- boxes

  /** The key a name is found by: case and runs of spaces set aside, so "Order food" and "order  food" are one box. */
  protected static keyOf(name: string): string {
    return name.trim().replace(/\s+/gu, " ").toLowerCase();
  }

  /** The box a reference names, made at its first mention, with the reference's attributes applied. */
  protected box(reference: Ref, group: number): GraphNode {
    const { node, created } = this.model.node(GraphKindParser.keyOf(reference.name), group);
    if (created) {
      node.label = reference.name;
      node.shape = this.defaultShape;
      this.made(node);
    }
    this.attributes(node, reference.attributes);
    this.shapedAs(node);
    return node;
  }

  /** Called when a box is first named, before its attributes. */
  protected made(_node: GraphNode): void {}

  /** A question gets a question's shape unless its attributes gave it another. */
  protected shapedAs(node: GraphNode): void {
    if (this.shaped.has(node) || this.shapeWords.size === 0 || node.compartments !== null) return;
    const label = node.label.trimEnd();
    if (label.length > 0 && (label[label.length - 1] === "?" || label[label.length - 1] === "\uFF1F")) node.shape = "diamond";
  }

  /** Applies attribute words to a box: a shape, a colour, a role; anything else is reported, or given to `otherAttribute`. */
  protected attributes(node: GraphNode, attributes: readonly Span[]): void {
    for (const attribute of attributes) {
      const word = attribute.text.trim();
      const key = Scan.key(word);
      const shape = this.shapeWords.get(key);
      const hue = GraphKindParser.hueWords.get(key);
      if (shape !== undefined) {
        node.shape = shape;
        this.shaped.add(node);
      } else if (hue !== undefined) node.hue = Tone.hue(hue);
      else if (MutedWords.includes(key)) node.muted = true;
      else if (!this.otherAttribute(node, word, key)) this.unknownAttribute(attribute, this.boxWord, this.attributeChoices, this.attributeHint);
    }
  }

  /** A kind's own attribute words: a state's fork, a class's stereotype. True when the word was taken. */
  protected otherAttribute(_node: GraphNode, _word: string, _key: string): boolean {
    return false;
  }

  /** Applies attribute words to a line: a colour, a role, a line style. */
  protected lineAttributes(edge: GraphEdge, attributes: readonly Span[]): void {
    for (const attribute of attributes) {
      const key = Scan.key(attribute.text);
      const hue = GraphKindParser.hueWords.get(key);
      const line = LineWords.get(key);
      if (hue !== undefined) edge.hue = Tone.hue(hue);
      else if (line !== undefined) edge.line = line;
      else if (MutedWords.includes(key)) edge.hue = Tone.of("muted");
      else this.unknownAttribute(attribute, new Said("a line", "连线"), ["dashed", "thick", "blue", "red", "green", "good", "bad", "muted"]);
    }
  }

  // ---------------------------------------------------------------- lines

  /**
   * Reads a line that is not a keyword: a chain of arrows, a declaration `id: Label`, or a box on its own.
   */
  protected statement(content: Span, group: number): void {
    if (this.oddArrow(content)) return;
    const { head, tail } = Scan.splitColon(content);
    const { pieces, arrows } = Scan.arrows(head, this.arrowSet);
    const bars = Scan.labelBetweenBars(pieces);
    if (bars !== null) {
      this.problems.error(bars, "LabelBetweenBars");
      return;
    }
    if (arrows.length === 0) {
      if (tail !== null) {
        const id = Scan.reference(head, this.problems);
        if (id.name.length === 0) {
          this.problems.error(head.isEmpty ? content.slice(0, 1) : head, "EmptyName");
          return;
        }
        const label = Scan.reference(tail, this.problems);
        const node = this.box(id, group);
        if (label.name.length !== 0) node.label = label.name;
        this.attributes(node, label.attributes);
        this.shapedAs(node);
        return;
      }
      const only = Scan.reference(head, this.problems);
      if (only.name.length === 0) {
        this.problems.error(content.slice(0, 1), "EmptyName");
        return;
      }
      this.single(only, group);
      return;
    }
    this.chain(content, pieces, arrows, tail, group);
  }

  /** A box named on a line of its own. */
  protected single(reference: Ref, group: number): void {
    this.box(reference, group);
  }

  /** This kind's name with its article, for a problem: "a flowchart", "an entity diagram". */
  protected get kindSaid(): Said {
    const name = this.context.kind.name;
    return new Said(`${Grammar.a(name.english)} ${name.english}`, name.chinese);
  }

  /** Whether a line has a word drawn like an arrow that this kind has not got - Mermaid's `-.->`, `--x` - which is said, and the line left out rather than read as boxes named after the pieces. */
  protected oddArrow(content: Span): boolean {
    const head = Scan.splitColon(content).head;
    // A count the line's ends cannot have - 2-* - is said as a count rather than as an arrow.
    if (this.arrowSet.cardinalities) {
      const count = Scan.badCardinality(head);
      if (count !== null) {
        this.problems.error(count, "BadCardinality", count.text);
        return true;
      }
    }
    const odd = Scan.unknownArrow(head, this.arrowSet);
    if (odd === null) return false;
    this.problems.error(odd, "UnknownArrow", odd.text, this.kindSaid, this.arrowSet.names);
    return true;
  }

  /** A chain of arrows: a line between each neighbouring pair, the label after the colon on the last. */
  protected chain(_content: Span, pieces: readonly Span[], arrows: readonly Arrow[], tail: Span | null, group: number): void {
    const made: GraphEdge[] = [];
    for (let i = 0; i < arrows.length; i++) {
      const left = pieces[i];
      const right = pieces[i + 1];
      if (left.isEmpty) {
        this.problems.error(arrows[i].token, i === 0 ? "ArrowFromNothing" : "EmptyName");
        continue;
      }
      if (right.isEmpty) {
        this.problems.error(arrows[i].token, "ArrowToNothing");
        continue;
      }
      const from = this.end(Scan.reference(left, this.problems), group, true);
      const to = this.end(Scan.reference(right, this.problems), group, false);
      if (from === null || to === null) continue;
      const edge = this.link(from, to, arrows[i]);
      if (edge !== null) made.push(edge);
    }
    if (tail !== null && made.length > 0) {
      const text = Scan.reference(tail, this.problems);
      if (text.name.length !== 0) made[made.length - 1].label = text.name;
      this.lineAttributes(made[made.length - 1], text.attributes);
    }
  }

  /** What one end of an arrow names: a box, or - in a state diagram - a start, an end or a composite state. */
  protected end(reference: Ref, group: number, _source: boolean): End | null {
    if (reference.name.length === 0) {
      this.problems.error(reference.whole, "EmptyName");
      return null;
    }
    // A star is a state machine's start or end - Mermaid's [*] as well, its brackets read as attributes - and nothing else has one.
    if (reference.name.trim() === "*" || (reference.name.trim().length === 0 && reference.attributes.length === 1 && reference.attributes[0].text.trim() === "*")) {
      this.problems.error(reference.whole, "StartInsideNothing", this.kindSaid);
      return null;
    }
    const node = this.box(reference, group);
    return { index: this.model.indexOf(node.key), isGroup: false };
  }

  /** The line an arrow draws between two ends, its heads as the arrow says and pointing the way the flow goes. */
  protected link(from: End, to: End, arrow: Arrow): GraphEdge | null {
    const form = arrow.form;
    // An arrow written backwards - B <- A - flows from A to B: the layout ranks by the way the arrowhead points.
    const backwards = form.tail !== "none" && form.tip === "none";
    const edge = backwards
      ? new GraphEdge({ from: to.index, fromGroup: to.isGroup, to: from.index, toGroup: from.isGroup, tip: form.tail, tail: "none", line: form.line })
      : new GraphEdge({ from: from.index, fromGroup: from.isGroup, to: to.index, toGroup: to.isGroup, tip: form.tip, tail: form.tail, line: form.line });
    this.model.edges.push(edge);
    return edge;
  }

  // ---------------------------------------------------------------- groups and notes

  /** A group from a `group` line: `group Kitchen` or `group k: Kitchen`, with attributes. */
  protected group(rest: Span, parent: number, isState = false): number {
    const { head, tail } = Scan.splitColon(rest);
    const id = Scan.reference(head, this.problems);
    const label = tail !== null ? Scan.reference(tail, this.problems) : id;
    const name = label.name.length === 0 ? id.name : label.name;
    const group = new GraphGroup(GraphKindParser.keyOf(id.name.length === 0 ? name : id.name));
    group.label = name;
    group.parent = parent;
    group.isState = isState;
    for (const attribute of [...id.attributes, ...(tail === null ? [] : label.attributes)]) {
      const key = Scan.key(attribute.text);
      const hue = GraphKindParser.hueWords.get(key);
      if (hue !== undefined) group.hue = Tone.hue(hue);
      else this.unknownAttribute(attribute, new Said("a group", "组"), ["blue", "orange", "green", "yellow", "pink", "purple", "red", "teal", "grey"]);
    }
    this.model.groups.push(group);
    return this.model.groups.length - 1;
  }

  /** A note beside a box: `note Box: what to say`, joined to it by a dashed line. */
  protected note(rest: Span, content: Span, group: number): void {
    const { head, tail } = Scan.splitColon(rest);
    const target = Scan.reference(head, this.problems);
    if (target.name.length === 0 || tail === null) {
      this.problems.error(content, "NoteNeedsTarget");
      return;
    }
    const about = this.box(target, group);
    const { node: note } = this.model.node(`*note${this.model.nodes.length}`, about.group);
    note.label = Scan.name(tail, this.problems);
    note.shape = "note";
    this.model.edges.push(new GraphEdge({ from: this.model.indexOf(note.key), to: this.model.indexOf(about.key), tip: "none", line: "dashed", hue: Tone.of("muted") }));
  }
}

const FlowchartShapes = new Map<string, NodeShape>([
  ["box", "box"], ["rect", "box"], ["rectangle", "box"], ["step", "box"], ["process", "box"],
  ["round", "round"], ["rounded", "round"], ["soft", "round"],
  ["pill", "pill"], ["stadium", "pill"], ["start", "pill"], ["end", "pill"], ["stop", "pill"], ["terminal", "pill"], ["begin", "pill"],
  ["circle", "circle"],
  ["diamond", "diamond"], ["decision", "diamond"], ["choice", "diamond"], ["question", "diamond"], ["if", "diamond"],
  ["hexagon", "hexagon"], ["prepare", "hexagon"], ["preparation", "hexagon"],
  ["io", "parallelogram"], ["input", "parallelogram"], ["output", "parallelogram"], ["data", "parallelogram"], ["parallelogram", "parallelogram"],
  ["database", "cylinder"], ["db", "cylinder"], ["store", "cylinder"], ["cylinder", "cylinder"], ["storage", "cylinder"],
  ["document", "document"], ["doc", "document"], ["file", "document"], ["report", "document"],
  ["subroutine", "subroutine"], ["call", "subroutine"], ["predefined", "subroutine"],
  ["note", "note"], ["comment", "note"],
]);

/**
 * A flowchart: steps and the arrows between them, a question's shape for a label ending in a question mark, groups, and shapes named in words.
 */
export class FlowchartParser extends GraphKindParser {
  protected get boxWord(): Said {
    return new Said("a step", "步骤");
  }
  protected override get primaryShapes(): string[] {
    return ["box", "round", "pill", "circle", "diamond", "hexagon", "io", "database", "document", "subroutine", "note"];
  }
  protected override get shapeWords(): ReadonlyMap<string, NodeShape> {
    return FlowchartShapes;
  }

  protected content(block: Block): void {
    this.line(block, -1);
  }

  private line(block: Block, group: number): void {
    const content = block.content;
    let rest = keyword(content, "group") ?? keyword(content, "subgraph");
    if (rest !== null) {
      const g = this.group(rest, group);
      if (block.children.length === 0) this.problems.warning(content, "EmptyGroup", this.model.groups[g].label);
      for (const child of block.children) this.line(child, g);
      return;
    }
    rest = keyword(content, "note");
    if (rest !== null && Scan.indexOf(rest, ":") >= 0) this.note(rest, content, group);
    else this.statement(content, group);
    this.unindent(block, (b) => this.line(b, group));
  }

  protected override finish(): void {
    this.graph.boxes = { one: "step", many: "steps" };
    this.graph.lines = { one: "arrow", many: "arrows" };
  }
}

const StateShapes = new Map<string, NodeShape>([
  ["choice", "diamond"], ["decision", "diamond"], ["fork", "bar"], ["join", "bar"],
]);

/**
 * A state diagram: states and the transitions between them, `*` for where it starts and stops, composite states written as states with lines under them, choices, forks and joins, and notes.
 */
export class StateParser extends GraphKindParser {
  private readonly composites = new Map<string, number>();

  protected get boxWord(): Said {
    return new Said("a state", "状态");
  }
  protected override get primaryShapes(): string[] {
    return ["choice", "fork", "join"];
  }
  protected override get defaultShape(): NodeShape {
    return "round";
  }
  protected override get shapeWords(): ReadonlyMap<string, NodeShape> {
    return StateShapes;
  }

  protected content(block: Block): void {
    this.line(block, -1);
  }

  private line(block: Block, group: number): void {
    let content = block.content;
    const rest = keyword(content, "note");
    if (rest !== null && Scan.indexOf(rest, ":") >= 0) {
      this.note(rest, content, group);
      return;
    }
    const declared = keyword(content, "state");
    if (declared !== null && declared.length > 0) content = declared;
    const { head, tail } = Scan.splitColon(content);
    const hasArrow = Scan.arrows(head, this.arrowSet).arrows.length > 0;
    if (block.children.length > 0 && !hasArrow) {
      // A state with lines under it is a composite state: a frame holding a diagram of its own.
      const id = Scan.reference(head, this.problems);
      const label = tail !== null && !tail.isEmpty ? Scan.name(tail, this.problems) : id.name;
      const g = this.group(head, group, true);
      this.model.groups[g].label = label;
      this.composites.set(GraphKindParser.keyOf(id.name), g);
      for (const child of block.children) this.line(child, g);
      return;
    }
    this.statement(content, group);
    this.unindent(block, (b) => this.line(b, group));
  }

  protected override end(reference: Ref, group: number, source: boolean): End | null {
    const name = reference.name.trim();
    // A star - or Mermaid's [*], whose brackets read as attributes - is where the frame starts, or where it stops.
    const star = name === "*" || (name.length === 0 && reference.attributes.length === 1 && reference.attributes[0].text.trim() === "*");
    if (star) {
      // Each frame has its own start and its own end.
      const key = (source ? "*start" : "*end") + "@" + String(group);
      const { node: point, created } = this.model.node(key, group);
      if (created) {
        point.label = "";
        point.shape = source ? "startDot" : "endDot";
      }
      return { index: this.model.indexOf(point.key), isGroup: false };
    }
    const composite = this.composites.get(GraphKindParser.keyOf(name));
    if (composite !== undefined) return { index: composite, isGroup: true };
    return super.end(reference, group, source);
  }

  protected override finish(): void {
    // A composite named by a line before its own lines were read was a state until then.
    const redirect = new Map<number, number>();
    for (const [key, group] of this.composites) {
      const index = this.model.indexOf(key);
      if (index >= 0) redirect.set(index, group);
    }
    this.model.redirect(redirect);
    this.graph.boxes = { one: "state", many: "states" };
    this.graph.lines = { one: "transition", many: "transitions" };
  }
}

/**
 * A class diagram: classes with their members indented under them, UML's relationship arrows, multiplicities, stereotypes in brackets, and packages as groups.
 */
export class ClassParser extends GraphKindParser {
  protected get boxWord(): Said {
    return new Said("a class", "类");
  }
  protected override get arrowSet(): ArrowSet {
    return ArrowSet.classes;
  }
  protected override get defaultShape(): NodeShape {
    return "square";
  }
  protected override get extraAttributeWords(): string[] {
    return ["interface", "abstract", "enum", "record", "struct", "service"];
  }

  protected override made(node: GraphNode): void {
    node.compartments = new Compartments();
  }

  protected override otherAttribute(node: GraphNode, word: string, _key: string): boolean {
    // Any other word is the class's stereotype: «interface», «enumeration», «service».
    node.compartments ??= new Compartments();
    node.compartments.stereotype ??= word;
    return true;
  }

  protected content(block: Block): void {
    this.line(block, -1);
  }

  private line(block: Block, group: number): void {
    let content = block.content;
    let rest = keyword(content, "group") ?? keyword(content, "package") ?? keyword(content, "namespace");
    if (rest !== null) {
      const g = this.group(rest, group);
      if (block.children.length === 0) this.problems.warning(content, "EmptyGroup", this.model.groups[g].label);
      for (const child of block.children) this.line(child, g);
      return;
    }
    rest = keyword(content, "note");
    if (rest !== null && Scan.indexOf(rest, ":") >= 0) {
      this.note(rest, content, group);
      return;
    }
    if (ClassParser.isMember(content)) {
      this.problems.error(content, "MemberOutsideClass");
      return;
    }
    const declared = keyword(content, "class");
    if (declared !== null && declared.length > 0) content = declared;
    if (this.oddArrow(content)) return;
    const { head } = Scan.splitColon(content, true);
    if (Scan.arrows(head, this.arrowSet).arrows.length > 0) {
      this.statement(content, group);
      this.unindent(block, (b) => this.line(b, group));
      return;
    }
    // A class, and its members under it.
    const reference = Scan.reference(content, this.problems);
    if (reference.name.length === 0) {
      this.problems.error(content, "EmptyName");
      return;
    }
    const node = this.box(reference, group);
    node.compartments ??= new Compartments();
    const fields: CompartmentLine[] = [];
    const operations: CompartmentLine[] = [];
    for (const child of block.children) {
      const member = ClassParser.member(child.content);
      (member.cells[0].includes("(") ? operations : fields).push(member);
      for (const grandchild of child.children) this.problems.warning(grandchild.content, "IndentedUnderNothing");
    }
    if (fields.length > 0 || operations.length > 0) {
      node.compartments.sections.length = 0;
      node.compartments.sections.push(fields);
      if (operations.length > 0) node.compartments.sections.push(operations);
    }
  }

  private static isMember(content: Span): boolean {
    if (content.length === 0) return false;
    const first = content.at(0);
    if (!(first === "+" || first === "-" || first === "~")) return false;
    if (content.length > 1) {
      const second = content.at(1);
      if (second === ">" || second === "-" || second === "|" || second === "*" || second === "o") return false;
    }
    return true;
  }

  /** A member as written, its visibility as UML's symbol: `public` becomes `+`, `private` `-`; `static` underlines it and `abstract` sets it in italic. */
  private static member(content: Span): CompartmentLine {
    let text = content.text.trim();
    let isStatic = false;
    let isAbstract = false;
    let visibility = "";
    const starts = (word: string): boolean => {
      if (text.length > word.length && text.slice(0, word.length).toLowerCase() === word.toLowerCase() && isWhiteSpace(text[word.length])) {
        text = text.slice(word.length).trimStart();
        return true;
      }
      return false;
    };
    for (let changed = true; changed; ) {
      changed = false;
      for (const [word, symbol] of [["public", "+"], ["private", "-"], ["protected", "#"], ["internal", "~"], ["package", "~"]])
        if (starts(word)) {
          visibility = symbol;
          changed = true;
        }
      if (starts("static")) {
        isStatic = true;
        changed = true;
      }
      if (starts("abstract")) {
        isAbstract = true;
        changed = true;
      }
    }
    if (visibility.length === 0 && text.length > 0 && (text[0] === "+" || text[0] === "-" || text[0] === "~")) {
      visibility = text.slice(0, 1);
      text = text.slice(1).trimStart();
    }
    return compartmentLine([visibility.length > 0 ? `${visibility} ${text}` : text], isAbstract, isStatic);
  }

  protected override link(from: End, to: End, arrow: Arrow): GraphEdge | null {
    const form = arrow.form;
    let edge: GraphEdge;
    // The end with a triangle or a diamond is the more general one - the base class, the whole - and goes above.
    const tipIsParent = form.tip === "triangle" || form.tip === "diamond" || form.tip === "hollowDiamond";
    if (arrow.tailCard != null || arrow.tipCard != null)
      edge = new GraphEdge({ from: from.index, to: to.index, tail: "none", tip: "none", tailCard: arrow.tailCard ?? null, tipCard: arrow.tipCard ?? null });
    else if (tipIsParent) edge = new GraphEdge({ from: to.index, to: from.index, tail: form.tip, tip: form.tail, line: form.line });
    else if (form.tail !== "none" && form.tip === "none" && form.tail === "arrow") edge = new GraphEdge({ from: to.index, to: from.index, tip: "arrow", line: form.line });
    else edge = new GraphEdge({ from: from.index, to: to.index, tail: form.tail, tip: form.tip, line: form.line });
    this.model.edges.push(edge);
    return edge;
  }

  protected override finish(): void {
    this.graph.boxes = { one: "class", many: "classes" };
    this.graph.lines = { one: "relationship", many: "relationships" };
  }
}

/**
 * An entity diagram: entities with their attributes indented under them, keys marked, and relationships drawn with crow's feet from cardinalities written at each end of the line: `Customer 1-* Order`.
 */
export class EntityParser extends GraphKindParser {
  protected get boxWord(): Said {
    return new Said("an entity", "实体");
  }
  protected override get arrowSet(): ArrowSet {
    return ArrowSet.entities;
  }
  protected override get defaultShape(): NodeShape {
    return "square";
  }

  protected override made(node: GraphNode): void {
    node.compartments = new Compartments({ tabular: true });
  }

  protected content(block: Block): void {
    this.line(block, -1);
  }

  private line(block: Block, group: number): void {
    const content = block.content;
    let rest = keyword(content, "group");
    if (rest !== null) {
      const g = this.group(rest, group);
      for (const child of block.children) this.line(child, g);
      return;
    }
    rest = keyword(content, "note");
    if (rest !== null && Scan.indexOf(rest, ":") >= 0) {
      this.note(rest, content, group);
      return;
    }
    if (this.oddArrow(content)) return;
    const { head } = Scan.splitColon(content);
    if (Scan.arrows(head, this.arrowSet).arrows.length > 0) {
      this.statement(content, group);
      this.unindent(block, (b) => this.line(b, group));
      return;
    }
    // An entity is named on a line of its own; a name and a type outside one is an attribute that lost its entity.
    if (Scan.indexOf(content, ":") >= 0) {
      this.problems.error(content, "AttributeOutsideEntity");
      return;
    }
    const reference = Scan.reference(head, this.problems);
    if (reference.name.length === 0) {
      this.problems.error(content, "EmptyName");
      return;
    }
    const node = this.box(reference, group);
    node.compartments ??= new Compartments({ tabular: true });
    const rows: CompartmentLine[] = [];
    for (const child of block.children) rows.push(this.attribute(child.content));
    if (rows.length > 0) {
      node.compartments.sections.length = 0;
      node.compartments.sections.push(rows);
    }
  }

  /** An attribute: its name, its type, and its keys - `id: number [key]`, or `id number key`. */
  private attribute(content: Span): CompartmentLine {
    const { remainder: rest, attributes: flags } = Scan.trailingAttributes(content, this.problems);
    const { head: name, tail: type } = Scan.splitColon(rest);
    let nameText = Scan.name(name, this.problems);
    let typeText = type !== null ? Scan.name(type, this.problems) : "";
    if (type === null) {
      const words = nameText.split(" ").filter((w) => w.length > 0);
      if (words.length >= 2) {
        nameText = words[0];
        typeText = words.slice(1).join(" ");
      }
    }
    const keys: string[] = [];
    for (const flag of flags) {
      let key: string;
      switch (Scan.key(flag.text)) {
        case "key":
        case "pk":
        case "primary":
        case "primarykey":
        case "id":
          key = "PK";
          break;
        case "ref":
        case "fk":
        case "foreign":
        case "foreignkey":
        case "reference":
          key = "FK";
          break;
        case "unique":
        case "uk":
          key = "UK";
          break;
        default:
          key = "";
      }
      if (key.length === 0) this.unknownAttribute(flag, new Said("an attribute", "属性"), ["key", "ref", "unique"]);
      else if (!keys.includes(key)) keys.push(key);
    }
    return compartmentLine([nameText, typeText, keys.join(", ")], false, keys.includes("PK"));
  }

  protected override link(from: End, to: End, arrow: Arrow): GraphEdge | null {
    if (arrow.tailCard == null && arrow.tipCard == null) return super.link(from, to, arrow);
    const edge = new GraphEdge({ from: from.index, to: to.index, tail: "none", tip: "none", tailCard: arrow.tailCard ?? null, tipCard: arrow.tipCard ?? null, crowsFeet: true, line: arrow.form.line });
    this.model.edges.push(edge);
    return edge;
  }

  protected override finish(): void {
    this.graph.boxes = { one: "entity", many: "entities" };
    this.graph.lines = { one: "relationship", many: "relationships" };
  }
}

registerKind("flowchart", (context) => new FlowchartParser(context));
registerKind("state", (context) => new StateParser(context));
registerKind("class", (context) => new ClassParser(context));
registerKind("entity", (context) => new EntityParser(context));
