// One axis measured for a given length - which ticks it shows, at what angle its labels sit, and how much room it needs beside the
// plotting area - and drawn: its line, ticks, labels, title, gridlines and zero line.
// Ported from Parcel NExT's Divooka.Graphics.Plotting/Rendering/AxisPainter.cs.

import type { AxisSide } from "./axis";
import { ChartPaints, snap } from "./contracts";
import { TextPainter, type DrawContext } from "./figure";
import { PositionScale, type AxisTick, type ScaleDomain } from "./scales";
import type { Sink } from "./sink";
import type { Theme } from "./theme";
import type { RectF } from "../rendering/geometry";

const LabelGap = 4;
const MinLabelSpacing = 10;

export class AxisLayout {
  domain!: ScaleDomain;
  horizontal!: boolean;
  side!: AxisSide;
  ticks!: readonly AxisTick[];
  labelAngle = 0;
  labelEvery = 1;
  showLabels = true;
  showTitle = true;
  drawTickMarks = false;
  /** The room the axis takes beside the plotting area: tick marks, labels and title. */
  band = 0;
  /** How far the first and last labels reach past the ends of the plotting area. */
  overhangStart = 0;
  overhangEnd = 0;
  tickLength = 0;
  /** Whether this axis carries the chart's values (rather than its categories or the second dimension of a scatter), so it takes the theme's primary gridlines. */
  isValueAxis = false;

  /** The number of ticks to ask for along an axis this long. */
  static defaultCount(length: number, horizontal: boolean): number {
    return Math.min(Math.max(Math.trunc(length / (horizontal ? 80 : 45)), 2), 10);
  }

  /** Measure an axis for a plotting area `length` pixels long. */
  static measure(domain: ScaleDomain, horizontal: boolean, side: AxisSide, length: number, text: TextPainter, theme: Theme, showLabels: boolean, showTitle: boolean): AxisLayout {
    const spec = domain.spec;
    length = Math.max(length, 10);
    const categorical = domain.type === "category";
    let count = spec.tickCount ?? AxisLayout.defaultCount(length, horizontal);
    let ticks = domain.ticks(count);
    const lineHeight = text.lineHeight("tick");
    let angle = spec.labelAngle ?? 0;
    let every = 1;

    if (showLabels && horizontal && ticks.length > 1) {
      if (!categorical && spec.tickValues === null && spec.tickStep === null && spec.tickCount === null && spec.labelAngle === null) {
        // Fewer ticks until neighbouring labels clear each other.
        while (count > 2 && collide(domain, ticks, length, text, theme)) {
          const before = ticks.length;
          while (count > 2 && domain.ticks(--count).length >= before) {}
          ticks = domain.ticks(count);
        }
      } else if (spec.labelAngle === null && collide(domain, ticks, length, text, theme)) {
        // Categories (and stated ticks) are all labelled: turn them, and only past a right angle thin them.
        const step = length / Math.max(1, ticks.length);
        if (step * Math.sin(Math.PI / 4) >= lineHeight + 2) angle = -45;
        else {
          angle = -90;
          if (step < lineHeight + 2) every = Math.ceil((lineHeight + 2) / step);
        }
      }
    } else if (showLabels && !horizontal && ticks.length > 1 && !categorical && spec.tickValues === null && spec.tickStep === null && spec.tickCount === null) {
      // Only labelled ticks crowd: a logarithmic axis' unlabelled minor ticks are meant to be close together.
      while (count > 2 && length / Math.max(1, ticks.filter((t) => t.label.length > 0).length - 1) < lineHeight + 4) {
        const before = ticks.length;
        while (count > 2 && domain.ticks(--count).length >= before) {}
        ticks = domain.ticks(count);
      }
    } else if (showLabels && !horizontal && categorical && ticks.length > 1) {
      const step = length / Math.max(1, ticks.length);
      if (step < lineHeight + 1) every = Math.ceil((lineHeight + 1) / step);
    }

    const tickMarks = theme.tickLength > 0 && !categorical && (horizontal ? theme.axisLines : !theme.gridY || spec.grid === false);
    const tickLength = tickMarks ? theme.tickLength : 0;

    let labelThickness = 0;
    if (showLabels) {
      ticks.forEach((tick, i) => {
        if (i % every !== 0 || tick.label.length === 0) return;
        const size = TextPainter.rotated(text.measure(tick.label, "tick"), angle);
        labelThickness = Math.max(labelThickness, horizontal ? size.height : size.width);
      });
    }
    const titleThickness = showTitle && spec.title ? text.lineHeight("axisTitle") + theme.textGap : 0;
    let band = tickLength + (labelThickness > 0 ? LabelGap + labelThickness : 0) + titleThickness;
    if (band > 0) band += 2;

    // How far the end labels reach past the plotting area, so the layout can make room for them.
    let overhangStart = 0;
    let overhangEnd = 0;
    if (showLabels && ticks.length > 0 && angle === 0) {
      const probe = new PositionScale(domain, 0, length, ticks, theme.barPadding);
      const ordered = [...probe.ticks].sort((a, b) => a.position - b.position);
      const first = ordered[0];
      const last = ordered[ordered.length - 1];
      const firstExtent = horizontal ? text.measure(first.label, "tick").width / 2 : lineHeight / 2;
      const lastExtent = horizontal ? text.measure(last.label, "tick").width / 2 : lineHeight / 2;
      // Vertical positions run downwards from the top of the plotting area's probe; a label centred on the top tick reaches half a line above it.
      overhangStart = Math.max(0, firstExtent - first.position);
      overhangEnd = Math.max(0, lastExtent - (length - last.position));
    }

    return Object.assign(new AxisLayout(), {
      domain,
      horizontal,
      side,
      ticks,
      labelAngle: angle,
      labelEvery: every,
      showLabels,
      showTitle,
      drawTickMarks: tickMarks,
      tickLength,
      band,
      overhangStart,
      overhangEnd,
    });
  }

  /** The trained scale for this axis over the given pixel range. */
  scaleOver(start: number, end: number, theme: Theme): PositionScale {
    return new PositionScale(this.domain, start, end, this.ticks, theme.barPadding);
  }

  /** Draws the axis' line, ticks, labels and title beside the plotting area. */
  draw(sink: Sink, context: DrawContext, scale: PositionScale, plot: RectF): void {
    const theme = context.theme;
    const text = context.text;
    const spec = this.domain.spec;
    if (!spec.visible) return;
    const hairline = theme.hairlineWidth;

    if (this.horizontal) {
      const bottom = this.side !== "top";
      const edge = bottom ? plot.bottom : plot.top;
      const sign = bottom ? 1 : -1;
      if (theme.axisLines && !theme.frame) {
        const y = snap(context, edge, hairline);
        sink.drawLine(plot.left, y, plot.right, y, ChartPaints.hairline(theme.axisLine, hairline));
      }
      if (this.drawTickMarks)
        for (const tick of scale.ticks) {
          const x = snap(context, tick.position, hairline);
          if (x < plot.left - 0.5 || x > plot.right + 0.5) continue;
          sink.drawLine(x, edge, x, edge + sign * (tick.isMajor ? this.tickLength : this.tickLength / 2), ChartPaints.hairline(theme.axisLine, hairline));
        }
      const labelOffset = this.tickLength + LabelGap;
      let maxLabel = 0;
      if (this.showLabels) {
        let i = 0;
        for (const tick of scale.ticks) {
          if (i++ % this.labelEvery !== 0 || tick.label.length === 0) continue;
          const x = tick.position;
          if (x < plot.left - 1 || x > plot.right + 1) continue;
          const y = edge + sign * labelOffset;
          if (this.labelAngle === 0) text.draw(sink, tick.label, x, y, "tick", theme.secondaryInk, bottom ? "top" : "bottom");
          else {
            // Turned labels end at their tick, reading up towards it; the block's thickness lies down and to the right of its reading line, so the anchor moves back by half of it to centre the words on the tick.
            const h = text.lineHeight("tick");
            if (bottom) text.draw(sink, tick.label, x - (this.labelAngle === -90 ? h / 2 : h * 0.35), y, "tick", theme.secondaryInk, "topRight", this.labelAngle);
            else text.draw(sink, tick.label, x, y, "tick", theme.secondaryInk, "bottomLeft", this.labelAngle);
          }
          const size = TextPainter.rotated(text.measure(tick.label, "tick"), this.labelAngle);
          maxLabel = Math.max(maxLabel, size.height);
        }
      }
      if (this.showTitle && spec.title) {
        const y = edge + sign * (labelOffset + maxLabel + theme.textGap);
        text.draw(sink, spec.title, (plot.left + plot.right) / 2, y, "axisTitle", theme.secondaryInk, bottom ? "top" : "bottom");
      }
    } else {
      const left = this.side !== "right";
      const edge = left ? plot.left : plot.right;
      const sign = left ? -1 : 1;
      const gridY = spec.grid ?? (this.isValueAxis ? theme.gridY : theme.gridX);
      if (theme.axisLines && !theme.frame && (!gridY || this.domain.type === "category")) {
        const x = snap(context, edge, hairline);
        sink.drawLine(x, plot.top, x, plot.bottom, ChartPaints.hairline(theme.axisLine, hairline));
      }
      if (this.drawTickMarks)
        for (const tick of scale.ticks) {
          const y = snap(context, tick.position, hairline);
          if (y < plot.top - 0.5 || y > plot.bottom + 0.5) continue;
          sink.drawLine(edge, y, edge + sign * (tick.isMajor ? this.tickLength : this.tickLength / 2), y, ChartPaints.hairline(theme.axisLine, hairline));
        }
      const labelOffset = this.tickLength + LabelGap;
      let maxLabel = 0;
      if (this.showLabels) {
        let i = 0;
        for (const tick of scale.ticks) {
          if (i++ % this.labelEvery !== 0 || tick.label.length === 0) continue;
          const y = tick.position;
          if (y < plot.top - 1 || y > plot.bottom + 1) continue;
          text.draw(sink, tick.label, edge + sign * labelOffset, y, "tick", theme.secondaryInk, left ? "right" : "left", this.labelAngle);
          maxLabel = Math.max(maxLabel, TextPainter.rotated(text.measure(tick.label, "tick"), this.labelAngle).width);
        }
      }
      if (this.showTitle && spec.title) {
        const x = edge + sign * (labelOffset + maxLabel + theme.textGap);
        const mid = (plot.top + plot.bottom) / 2;
        // Read bottom to top on the left, top to bottom on the right, as printed axes do; either way the block's top faces the plotting area, so it is anchored at its bottom edge.
        text.draw(sink, spec.title, x, mid, "axisTitle", theme.secondaryInk, "bottom", left ? -90 : 90);
      }
    }
  }

  /** Draws the gridlines across the plotting area at this axis' major ticks. */
  drawGrid(sink: Sink, context: DrawContext, scale: PositionScale, plot: RectF): void {
    const theme = context.theme;
    const spec = this.domain.spec;
    const grid = spec.grid ?? (this.isValueAxis ? theme.gridY : theme.gridX);
    if (!grid || this.domain.type === "category") return;
    const hairline = theme.hairlineWidth;
    for (const tick of scale.ticks) {
      if (!tick.isMajor) continue;
      const p = snap(context, tick.position, hairline);
      if (this.horizontal) {
        if (p < plot.left - 0.5 || p > plot.right + 0.5) continue;
        sink.drawLine(p, plot.top, p, plot.bottom, ChartPaints.hairline(theme.grid, hairline));
      } else {
        if (p < plot.top - 0.5 || p > plot.bottom + 0.5) continue;
        sink.drawLine(plot.left, p, plot.right, p, ChartPaints.hairline(theme.grid, hairline));
      }
    }
  }

  /** Draws the zero line darker than the grid when zero falls inside a value axis, as the baseline bars grow from. */
  drawZero(sink: Sink, context: DrawContext, scale: PositionScale, plot: RectF): void {
    if (!(this.domain.type === "linear" || this.domain.type === "symlog" || this.domain.type === "sqrt")) return;
    if (!(this.domain.min < 0 && this.domain.max > 0)) return;
    // Zero is a baseline where something grows from it - bars, areas, a histogram; elsewhere it is just another gridline.
    if (!this.domain.wantsZero) return;
    const hairline = context.theme.hairlineWidth;
    const p = snap(context, scale.map(0), hairline);
    if (this.horizontal) sink.drawLine(p, plot.top, p, plot.bottom, ChartPaints.hairline(context.theme.axisLine, hairline));
    else sink.drawLine(plot.left, p, plot.right, p, ChartPaints.hairline(context.theme.axisLine, hairline));
  }
}

function collide(domain: ScaleDomain, ticks: readonly AxisTick[], length: number, text: TextPainter, theme: Theme): boolean {
  const probe = new PositionScale(domain, 0, length, ticks, theme.barPadding);
  const labels = probe.ticks
    .filter((t) => t.label.length > 0)
    .map((t) => ({ position: t.position, width: text.measure(t.label, "tick").width }))
    .sort((a, b) => a.position - b.position);
  for (let i = 1; i < labels.length; i++) if (labels[i].position - labels[i - 1].position < (labels[i].width + labels[i - 1].width) / 2 + MinLabelSpacing) return true;
  return false;
}
