// Sequence diagrams: who takes part, what they say to each other in order down the page, and the blocks, notes and dividers between.
// Ported from Parcel NExT's Divooka.Visualization.Dhole/Kinds/Sequence.cs (SequenceSpec, SequenceParser, SequenceLayout).

import type { Block, Span } from "../syntax/source";
import { Said, type ProblemList } from "../syntax/problems";
import * as Scan from "../syntax/scan";
import { ArrowSet, type LineStyle } from "../syntax/scan";
import { DiagramSpec, KindParser, registerKind, setting, type BuildContext, type Built, type ReadContext, type Setting } from "../syntax/reader";
import { RectF, VectorPath, add, mul, normalize, sub, vec, type Vec2 } from "../rendering/geometry";
import { Tone } from "../rendering/tones";
import { DiagramLayer, FontWeights, Scene, TextSetter, shapeMark, textBounds, type Mark, type TextMark } from "../rendering/scene";
import * as Shapes from "../rendering/shapes";
import { chartOf } from "../plot/figure";
import type { Theme } from "../plot/theme";
import type { TextMeasurer } from "../plot/text";
import { AttributeWords } from "./attribute-words";
import { typeFor, type TypeSizes } from "../layout/graph-diagram";

// ---------------------------------------------------------------- the spec

export type Role = "participant" | "actor" | "database";

export interface Participant {
  readonly key: string;
  label: string;
  role: Role;
  hue: Tone;
}

export interface Message {
  readonly type: "message";
  readonly from: number;
  readonly to: number;
  readonly text: string;
  readonly reply: boolean;
  readonly line: LineStyle;
  readonly hue: Tone | null;
}
export interface Note {
  readonly type: "note";
  readonly first: number;
  readonly last: number;
  readonly placement: string;
  readonly text: string;
}
export interface Divider {
  readonly type: "divider";
  readonly text: string;
}
export interface FrameStart {
  readonly type: "frameStart";
  readonly tag: string;
  readonly condition: string;
}
export interface FrameSection {
  readonly type: "frameSection";
  readonly tag: string;
  readonly condition: string;
}
export interface FrameEnd {
  readonly type: "frameEnd";
}
export type Item = Message | Note | Divider | FrameStart | FrameSection | FrameEnd;

/** A sequence diagram as read: who takes part, and what happens in order. */
export class SequenceSpec extends DiagramSpec {
  readonly participants: Participant[] = [];
  readonly items: Item[] = [];
  numbered = false;
  activations = true;
  mirror = true;

  override get isEmpty(): boolean {
    return this.participants.length === 0;
  }

  participantOf(name: string, role: Role): { index: number; created: boolean } {
    const key = name.trim().replace(/\s+/gu, " ").toLowerCase();
    let index = this.participants.findIndex((p) => p.key === key);
    const created = index < 0;
    if (created) {
      this.participants.push({ key, label: name.trim(), role, hue: Tone.hue("accent") });
      index = this.participants.length - 1;
    }
    return { index, created };
  }

  build(_problems: ProblemList, context: BuildContext): Built {
    const scene = SequenceLayout.build(this, this.theme, context.measurer);
    const messages = this.items.filter((i) => i.type === "message").length;
    const n = this.participants.length;
    const summary = `A sequence diagram of ${n} participant${n === 1 ? "" : "s"} and ${messages} message${messages === 1 ? "" : "s"}.`;
    const layer = new DiagramLayer(scene, "Sequence diagram", context.measurer);
    layer.label = this.title;
    return { chart: chartOf(layer), naturalWidth: scene.width, naturalHeight: scene.height, summary };
  }
}

// ---------------------------------------------------------------- the parser

const BlockWords = ["loop", "if", "alt", "opt", "optional", "par", "parallel", "critical", "break", "region"];

/** The first word of a line - its letters - in lower case, and what follows it trimmed. */
function firstWord(content: Span): { word: string; rest: Span } {
  let end = 0;
  while (end < content.length && /\p{L}/u.test(content.at(end))) end++;
  return { word: content.slice(0, end).text.toLowerCase(), rest: content.from(end).trim() };
}

/**
 * A sequence diagram: participants, messages between them in order - `->` a call, `-->` a reply - notes, dividers, and blocks indented under `loop`, `if`/`else`, `opt`, `par`/`and`, `critical` and `break`.
 */
export class SequenceParser extends KindParser {
  private readonly own: SequenceSpec;
  private readonly top: Block[] = [];

  constructor(context: ReadContext) {
    super(context);
    this.own = new SequenceSpec(context.kind, context.kindLine);
  }

  get spec(): SequenceSpec {
    return this.own;
  }

  protected override get settings(): Setting[] {
    return [
      setting(["numbers", "numbered", "numbering", "autonumber"], (v) => {
        const on = this.readSwitch(v);
        if (on !== null) this.own.numbered = on;
      }),
      setting(["activations", "activation", "bars"], (v) => {
        const on = this.readSwitch(v);
        if (on !== null) this.own.activations = on;
      }),
      setting(["mirror", "footer", "heads below"], (v) => {
        const on = this.readSwitch(v);
        if (on !== null) this.own.mirror = on;
      }),
    ];
  }

  // The top lines are read together once every setting is known, so an else sees the if before it.
  protected content(block: Block): void {
    this.top.push(block);
  }

  protected override finish(): void {
    this.lines(this.top, 0);
  }

  /** Reads a run of sibling lines, joining an `else` to the `if` before it and an `and` to its `par`. */
  private lines(blocks: Block[], depth: number): void {
    for (let i = 0; i < blocks.length; i++) {
      const block = blocks[i];
      const content = block.content;
      const { word, rest } = firstWord(content);
      if (BlockWords.includes(word)) {
        const tag = word === "alt" ? "if" : word === "optional" ? "opt" : word === "parallel" ? "par" : word;
        this.own.items.push({ type: "frameStart", tag, condition: Scan.name(rest, this.problems) });
        this.lines(block.children, depth + 1);
        // The else and and lines that continue this block are its siblings.
        while (i + 1 < blocks.length) {
          const next = firstWord(blocks[i + 1].content);
          const continuation = next.word;
          if (!((continuation === "else" && tag === "if") || (continuation === "and" && tag === "par"))) break;
          i++;
          this.own.items.push({ type: "frameSection", tag: continuation, condition: Scan.name(next.rest, this.problems) });
          this.lines(blocks[i].children, depth + 1);
        }
        this.own.items.push({ type: "frameEnd" });
        continue;
      }
      if (word === "else" || word === "and") {
        this.problems.error(content.slice(0, word.length), word === "else" ? "ElseWithoutIf" : "AndWithoutPar");
        this.lines(block.children, depth);
        continue;
      }
      this.statement(block);
      if (block.children.length > 0) {
        this.problems.warning(content, "UnknownBlock", content.text.length > 24 ? content.text.slice(0, 24) + "…" : content.text);
        this.lines(block.children, depth);
      }
    }
  }

  private statement(block: Block): void {
    const content = block.content;
    const { word, rest } = firstWord(content);
    // Mermaid's autonumber, on a line of its own, is numbers: on.
    if (Scan.key(content.text) === "autonumber") {
      this.own.numbered = true;
      return;
    }
    // A line with an arrow is a message whatever its first word is: "Database -> App" is a message from a participant called Database.
    const message = Scan.arrows(Scan.splitColon(content).head, ArrowSet.plain).arrows.length > 0;
    if (!message)
      switch (word) {
        case "actor":
        case "person":
          this.declare(rest, "actor");
          return;
        case "participant":
          this.declare(rest, "participant");
          return;
        case "database":
          this.declare(rest, "database");
          return;
        case "note":
          this.noteLine(rest, content);
          return;
      }
    if (content.text.startsWith("==")) {
      this.own.items.push({ type: "divider", text: trimChars(content.text, "= ") });
      return;
    }
    const { head, tail } = Scan.splitColon(content);
    const odd = Scan.unknownArrow(head, ArrowSet.plain);
    if (odd !== null) {
      this.problems.error(odd, "UnknownArrow", odd.text, new Said("a sequence diagram", "时序图"), ArrowSet.plain.names);
      return;
    }
    const { pieces, arrows } = Scan.arrows(head, ArrowSet.plain);
    const bars = Scan.labelBetweenBars(pieces);
    if (bars !== null) {
      this.problems.error(bars, "LabelBetweenBars");
      return;
    }
    if (arrows.length !== 1) {
      this.problems.error(content, "MessageNeedsArrow");
      return;
    }
    if (pieces[0].isEmpty) {
      this.problems.error(arrows[0].token, "ArrowFromNothing");
      return;
    }
    if (pieces[1].isEmpty) {
      this.problems.error(arrows[0].token, "ArrowToNothing");
      return;
    }
    const a = this.own.participantOf(Scan.name(pieces[0], this.problems), "participant").index;
    const b = this.own.participantOf(Scan.name(pieces[1], this.problems), "participant").index;
    const form = arrows[0].form;
    const backwards = form.tail !== "none" && form.tip === "none";
    const [from, to] = backwards ? [b, a] : [a, b];
    let hue: Tone | null = null;
    let text = "";
    if (tail !== null) {
      const said = Scan.reference(tail, this.problems);
      text = said.name;
      for (const attribute of said.attributes) {
        const h = AttributeWords.hue(attribute.text);
        if (h !== null) hue = Tone.hue(h);
        else this.unknownAttribute(attribute, new Said("a message", "消息"), ["blue", "green", "red", "good", "bad", "warn"]);
      }
    }
    this.own.items.push({ type: "message", from, to, text, reply: form.line === "dashed", line: form.line, hue });
  }

  private declare(rest: Span, role: Role): void {
    const { head, tail } = Scan.splitColon(rest);
    const id = Scan.reference(head, this.problems);
    if (id.name.length === 0) {
      this.problems.error(rest.isEmpty ? rest.line.content : rest, "EmptyName");
      return;
    }
    // "as" names a long participant by a short word, as other languages write it: participant Bank of Example as Bank.
    let name = id.name;
    let label = id.name;
    const at = name.toLowerCase().lastIndexOf(" as ");
    if (tail === null && at > 0) {
      label = name.slice(0, at).trim();
      name = name.slice(at + 4).trim();
    }
    const index = this.own.participantOf(name, role).index;
    const participant = this.own.participants[index];
    participant.role = role;
    participant.label = tail !== null && !tail.isEmpty ? Scan.name(tail, this.problems) : label;
    for (const attribute of id.attributes) {
      const hue = AttributeWords.hue(attribute.text);
      if (hue !== null) participant.hue = Tone.hue(hue);
      else this.unknownAttribute(attribute, new Said("a participant", "参与者"), ["blue", "orange", "green", "yellow", "pink", "purple", "red", "teal", "grey"]);
    }
  }

  private noteLine(rest: Span, content: Span): void {
    const { head, tail } = Scan.splitColon(rest);
    if (tail === null) {
      this.problems.error(content, "NoteNeedsTarget");
      return;
    }
    let placement: string;
    let targets: Span;
    if (head.startsWith("over")) {
      placement = "over";
      targets = head.from(4).trim();
    } else if (head.startsWith("left of")) {
      placement = "left";
      targets = head.from(7).trim();
    } else if (head.startsWith("right of")) {
      placement = "right";
      targets = head.from(8).trim();
    } else if (head.startsWith("left")) {
      placement = "left";
      targets = head.from(4).trim();
    } else if (head.startsWith("right")) {
      placement = "right";
      targets = head.from(5).trim();
    } else {
      placement = "over";
      targets = head;
    }
    const on = Scan.list(targets)
      .filter((t) => !t.isEmpty)
      .map((t) => this.own.participantOf(Scan.name(t, this.problems), "participant").index);
    if (on.length === 0) {
      this.problems.error(content, "NoteNeedsTarget");
      return;
    }
    this.own.items.push({ type: "note", first: Math.min(...on), last: Math.max(...on), placement, text: Scan.name(tail, this.problems) });
  }
}

/** C#'s string.Trim(params char[]): the characters of `chars` taken off both ends. */
function trimChars(text: string, chars: string): string {
  let start = 0;
  let end = text.length;
  while (start < end && chars.includes(text[start])) start++;
  while (end > start && chars.includes(text[end - 1])) end--;
  return text.slice(start, end);
}

// ---------------------------------------------------------------- the layout

const HeadPadX = 14;
const HeadPadY = 9;
const Gap = 36;
const RowGap = 12;
const BarWidth = 10;

/** A bar's start and how deep it is nested on its participant. */
interface Active {
  readonly start: number;
  readonly depth: number;
}

/** A block being laid out: where it starts, what it says, the participants it reaches, and where its else or and lines fall. */
interface OpenFrame {
  readonly top: number;
  readonly tag: string;
  readonly condition: string;
  low: number;
  high: number;
  readonly sections: number[];
  readonly conditions: string[];
}

interface ClosedFrame {
  readonly top: number;
  readonly bottom: number;
  readonly tag: string;
  readonly condition: string;
  readonly low: number;
  readonly high: number;
  readonly sections: number[];
  readonly conditions: string[];
  readonly depth: number;
}

/** C#'s List.OrderBy: stable, by a number. */
function orderBy<T>(items: readonly T[], key: (item: T) => number): T[] {
  return items.map((item, i) => ({ item, i, k: key(item) })).sort((a, b) => a.k - b.k || a.i - b.i).map((e) => e.item);
}

/**
 * A sequence diagram laid out: a column per participant as wide as its name, the gaps between columns as wide as the messages between them need, a row per message, note, divider and block edge, and activation bars from each call to its reply.
 */
export const SequenceLayout = {
  build(spec: SequenceSpec, theme: Theme, measurer: TextMeasurer): Scene {
    const text = new TextSetter(theme.fontFamilies, measurer);
    const type = typeFor(theme);
    const scene = new Scene(theme.fontFamilies);
    const n = spec.participants.length;
    if (n === 0) {
      scene.add(text.mark(" ", 0, 0, type.small, FontWeights.Normal, Tone.of("muted")));
      scene.frame(12);
      return scene;
    }

    // Heads.
    const headWidth: number[] = new Array(n).fill(0);
    const headHeight: number[] = new Array(n).fill(0);
    for (let i = 0; i < n; i++) {
      const label = text.measure(spec.participants[i].label, type.label, FontWeights.SemiBold);
      headWidth[i] = Math.max(label.width + 2 * HeadPadX, 72);
      headHeight[i] = spec.participants[i].role === "actor" ? 46 + label.height : label.height + 2 * HeadPadY + (spec.participants[i].role === "database" ? 10 : 0);
    }
    const headRow = Math.max(...headHeight);

    // Columns: wide enough apart for each head and for every message's label between the two it joins.
    const gap: number[] = new Array(Math.max(0, n - 1)).fill(0);
    for (let i = 0; i + 1 < n; i++) gap[i] = (headWidth[i] + headWidth[i + 1]) / 2 + Gap;
    let rightRoom = headWidth[n - 1] / 2;
    let leftRoom = headWidth[0] / 2;
    const needs: { a: number; b: number; need: number }[] = [];
    for (const item of spec.items) {
      if (item.type === "message" && item.from !== item.to)
        needs.push({ a: Math.min(item.from, item.to), b: Math.max(item.from, item.to), need: text.measure(numbered(spec, item), type.small, FontWeights.Normal).width + 36 });
      else if (item.type === "message") {
        const need = text.measure(numbered(spec, item), type.small, FontWeights.Normal).width + 50;
        if (item.from + 1 < n) needs.push({ a: item.from, b: item.from + 1, need: need + headWidth[item.from + 1] / 2 });
        else rightRoom = Math.max(rightRoom, need);
      } else if (item.type === "note") {
        const width = Math.min(text.measure(item.text, type.small, FontWeights.Normal).width, 220) + 20;
        if (item.placement === "right") {
          if (item.last + 1 < n) needs.push({ a: item.last, b: item.last + 1, need: width + 24 + headWidth[item.last + 1] / 2 });
          else rightRoom = Math.max(rightRoom, width + 20);
        } else if (item.placement === "left") {
          if (item.first > 0) needs.push({ a: item.first - 1, b: item.first, need: width + 24 + headWidth[item.first - 1] / 2 });
          else leftRoom = Math.max(leftRoom, width + 20);
        } else if (item.first !== item.last) needs.push({ a: item.first, b: item.last, need: width - 20 });
      }
    }
    for (const { a, b, need } of orderBy(needs, (x) => x.b - x.a)) {
      let have = 0;
      for (let k = a; k < b; k++) have += gap[k];
      if (have < need) for (let k = a; k < b; k++) gap[k] += (need - have) / (b - a);
    }
    const x: number[] = new Array(n).fill(0);
    x[0] = leftRoom;
    for (let i = 1; i < n; i++) x[i] = x[i - 1] + gap[i - 1];

    // Rows.
    const lineHeight = text.measure("Ag", type.small, FontWeights.Normal).height;
    let y = headRow + 18;
    let active: Active[][] = Array.from({ length: n }, () => []);
    const bars: { participant: number; top: number; bottom: number; depth: number }[] = [];
    const messageMarks: Mark[] = [];
    const frameMarks: Mark[] = [];
    const frameLabels: Mark[] = [];
    const noteMarks: Mark[] = [];
    const frames: OpenFrame[] = [];
    // What was active when each block began: an else, or an and, begins from there again, since only one of a block's branches happens.
    const begun: Active[][][] = [];
    const closed: ClosedFrame[] = [];
    let number = 0;
    let call = -1;
    const answered = Answered(spec, n);

    const edge = (participant: number, toward: number): number => {
      const depth = active[participant].length;
      if (!spec.activations || depth === 0) return x[participant];
      const centre = x[participant] + (depth - 1) * 4;
      return toward > centre ? centre + BarWidth / 2 : centre - BarWidth / 2;
    };

    for (const item of spec.items) {
      switch (item.type) {
        case "message": {
          const m = item;
          number++;
          const label = numbered(spec, m, number);
          const labelHeight = !label ? 0 : text.measure(label, type.small, FontWeights.Normal).height;
          const ink = m.hue ?? Tone.of("ink");
          if (m.from === m.to) {
            if (!m.reply) ++call;
            const top = y + labelHeight + 4;
            const from = edge(m.from, x[m.from] + 1);
            const loop = new VectorPath();
            loop.moveTo(from, top).lineTo(from + 34, top).lineTo(from + 34, top + 22).lineTo(from + 6, top + 22);
            messageMarks.push(shapeMark(loop, null, ink, 1.4, m.line));
            addHead(messageMarks, vec(from, top + 22), vec(-1, 0), m.reply, ink);
            if (label.length > 0) messageMarks.push(text.mark(label, from + 8, y, type.small, FontWeights.Normal, Tone.of("secondary")));
            if (spec.numbered) addNumber(messageMarks, text, type, number, vec(from, top));
            y = top + 22 + RowGap + 6;
          } else {
            const lineY = y + labelHeight + 6;
            // A reply ends its sender's activation before the arrow is placed; a call starts its receiver's after.
            if (spec.activations && m.reply && active[m.from].length > 0) {
              const { start, depth } = active[m.from].pop()!;
              bars.push({ participant: m.from, top: start, bottom: lineY, depth });
            }
            const fromX = edge(m.from, x[m.to]);
            // Only a call a reply comes back from has a bar: one that is never answered would run to the foot of the page and say nothing.
            if (!m.reply && answered.has(++call) && spec.activations) active[m.to].push({ start: lineY, depth: active[m.to].length });
            const toX = edge(m.to, x[m.from]);
            const direction = Math.sign(toX - fromX);
            const line = new VectorPath();
            line.moveTo(fromX, lineY).lineTo(toX - direction * (m.reply ? 1 : 8), lineY);
            messageMarks.push(shapeMark(line, null, ink, 1.4, m.line));
            addHead(messageMarks, vec(toX, lineY), vec(direction, 0), m.reply, ink);
            if (label.length > 0) messageMarks.push(text.centred(label, (fromX + toX) / 2, y + labelHeight / 2, type.small, FontWeights.Normal, Tone.of("secondary")));
            if (spec.numbered) addNumber(messageMarks, text, type, number, vec(fromX, lineY));
            y = lineY + RowGap + 4;
          }
          reach(frames, m.from, m.to);
          break;
        }
        case "note": {
          const note = item;
          const measured = text.mark(note.text, 0, 0, type.small, FontWeights.Normal, Tone.of("ink"), 220);
          let w = measured.width + 20;
          const h = measured.height + 12;
          const left =
            note.placement === "right"
              ? x[note.last] + 14
              : note.placement === "left"
                ? x[note.first] - 14 - w
                : (x[note.first] + x[note.last]) / 2 - Math.max(w, x[note.last] - x[note.first] + 40) / 2;
          if (note.placement === "over") w = Math.max(w, x[note.last] - x[note.first] + 40);
          const box = RectF.fromXYWH(left, y, w, h);
          noteMarks.push(shapeMark(Shapes.outline("note", box), Tone.hue("yellow").washed(0.2), Tone.hue("yellow").washed(0.75), 1.2));
          noteMarks.push({ ...measured, x: box.left + (w - measured.width) / 2, y: box.top + 6 });
          y += h + RowGap;
          reach(frames, note.first, note.last);
          break;
        }
        case "divider": {
          const mid = y + 12;
          const rule = new VectorPath();
          rule.moveTo(x[0] - leftRoom * 0.6, mid).lineTo(x[n - 1] + rightRoom * 0.6, mid);
          frameMarks.push(shapeMark(rule, null, Tone.of("axis"), 1, "dashed"));
          if (item.text.length > 0) {
            const label = text.centred(item.text, (x[0] + x[n - 1]) / 2, mid, type.small, FontWeights.SemiBold, Tone.of("secondary"));
            const chip = new VectorPath();
            chip.addRoundRect(textBounds(label).inflate(8, 3), 4, 4);
            noteMarks.push(shapeMark(chip, Tone.of("background"), Tone.of("axis"), 1));
            noteMarks.push(label);
          }
          y += 30;
          break;
        }
        case "frameStart":
          frames.push({ top: y, tag: item.tag, condition: item.condition, low: Number.MAX_SAFE_INTEGER, high: Number.MIN_SAFE_INTEGER, sections: [], conditions: [] });
          begun.push(active.map((a) => [...a]));
          y += lineHeight + 14;
          break;
        case "frameSection": {
          if (frames.length === 0) break;
          const frame = frames[frames.length - 1];
          frame.sections.push(y);
          frame.conditions.push(item.condition);
          if (begun.length > 0 && frame.tag === "if") {
            // Bars the branch before opened end where it ends.
            const before = begun[begun.length - 1];
            const next: Active[][] = [];
            for (let i = 0; i < n; i++) {
              for (const a of active[i].filter((a) => !before[i].some((b) => b.start === a.start && b.depth === a.depth)))
                bars.push({ participant: i, top: a.start, bottom: y - 4, depth: a.depth });
              next.push([...before[i]]);
            }
            active = next;
          }
          y += lineHeight + 10;
          break;
        }
        case "frameEnd": {
          if (frames.length === 0) break;
          const frame = frames.pop()!;
          if (begun.length > 0) begun.pop();
          closed.push({ top: frame.top, bottom: y, tag: frame.tag, condition: frame.condition, low: frame.low, high: frame.high, sections: frame.sections, conditions: frame.conditions, depth: frames.length });
          // A frame's reach widens the frame round it.
          if (frames.length > 0 && frame.low <= frame.high) reach(frames, frame.low, frame.high);
          y += 10;
          break;
        }
      }
    }
    const bottom = y + 6;
    for (let i = 0; i < n; i++) for (const { start, depth } of active[i]) bars.push({ participant: i, top: start, bottom: bottom - 4, depth });

    // Lifelines and heads, then frames, bars, messages and notes over them.
    for (let i = 0; i < n; i++) {
      const life = new VectorPath();
      life.moveTo(x[i], headRow).lineTo(x[i], bottom);
      scene.add(shapeMark(life, null, Tone.of("axis"), 1, "dashed"));
    }
    for (const frame of orderBy(closed, (f) => f.depth)) {
      const low = frame.low <= frame.high ? frame.low : 0;
      const high = frame.low <= frame.high ? frame.high : n - 1;
      const inset = frame.depth * 8;
      const left = x[low] - Math.max(headWidth[low] / 2, 40) - 6 + inset;
      const right = x[high] + Math.max(headWidth[high] / 2, 40) + 6 - inset;
      const box = new RectF(left, frame.top, right, frame.bottom);
      const outline = new VectorPath();
      outline.addRect(box);
      scene.add(shapeMark(outline, Tone.of("ink").washed(0.025), Tone.of("axis"), 1.1));
      const tag = text.mark(frame.tag, left + 7, frame.top + 3, type.small, FontWeights.SemiBold, Tone.of("ink"));
      const pentagon = new VectorPath();
      const tw = tag.width + 14;
      const th = tag.height + 6;
      pentagon.moveTo(left, frame.top).lineTo(left + tw + 6, frame.top).lineTo(left + tw + 6, frame.top + th - 6).lineTo(left + tw, frame.top + th).lineTo(left, frame.top + th).close();
      frameLabels.push(shapeMark(pentagon, Tone.of("grid"), Tone.of("axis"), 1.1));
      frameLabels.push(tag);
      if (frame.condition.length > 0) frameLabels.push(text.mark(`[${frame.condition}]`, left + tw + 14, frame.top + 3, type.small, FontWeights.Normal, Tone.of("secondary")));
      for (let s = 0; s < frame.sections.length; s++) {
        const rule = new VectorPath();
        rule.moveTo(left, frame.sections[s]).lineTo(right, frame.sections[s]);
        frameMarks.push(shapeMark(rule, null, Tone.of("axis"), 1.1, "dashed"));
        if (frame.conditions[s].length > 0) frameLabels.push(text.mark(`[${frame.conditions[s]}]`, left + 10, frame.sections[s] + 3, type.small, FontWeights.Normal, Tone.of("secondary")));
      }
    }
    for (const mark of frameMarks) scene.add(mark);
    for (const { participant, top, bottom: barBottom, depth } of orderBy(bars, (b) => b.depth)) {
      const bar = new VectorPath();
      bar.addRect(RectF.fromXYWH(x[participant] + depth * 4 - BarWidth / 2, top - 2, BarWidth, Math.max(8, barBottom - top + 4)));
      scene.add(shapeMark(bar, spec.participants[participant].hue.washed(0.22), spec.participants[participant].hue.washed(0.85), 1.1));
    }
    for (const mark of frameLabels) scene.add(mark);
    for (let i = 0; i < n; i++) {
      head(scene, text, type, spec.participants[i], x[i], 0, headWidth[i], headRow, true);
      if (spec.mirror) head(scene, text, type, spec.participants[i], x[i], bottom, headWidth[i], headRow, false);
    }
    for (const mark of [...messageMarks, ...noteMarks]) scene.add(mark);
    scene.frame(12);
    return scene;
  },
};

/**
 * Which calls - counted in order, replies not counted - a reply comes back from: a reply from a participant answers the latest call to it still unanswered, and an `else` starts again from what was unanswered when its `if` began, as the bars do.
 */
function Answered(spec: SequenceSpec, participants: number): Set<number> {
  const answered = new Set<number>();
  let waiting: number[][] = Array.from({ length: participants }, () => []);
  const begun: number[][][] = [];
  const tags: string[] = [];
  let call = -1;
  for (const item of spec.items) {
    switch (item.type) {
      case "message":
        if (item.from !== item.to) {
          if (item.reply) {
            if (waiting[item.from].length > 0) answered.add(waiting[item.from].pop()!);
          } else waiting[item.to].push(++call);
        } else if (!item.reply) ++call;
        break;
      case "frameStart":
        begun.push(waiting.map((w) => [...w]));
        tags.push(item.tag);
        break;
      case "frameSection":
        if (begun.length > 0 && tags[tags.length - 1] === "if") waiting = begun[begun.length - 1].map((w) => [...w]);
        break;
      case "frameEnd":
        if (begun.length > 0) {
          begun.pop();
          tags.pop();
        }
        break;
    }
  }
  return answered;
}

/** Widens every open frame to take in the participants a message or a note reaches. */
function reach(frames: OpenFrame[], a: number, b: number): void {
  for (const f of frames) {
    f.low = Math.min(f.low, Math.min(a, b));
    f.high = Math.max(f.high, Math.max(a, b));
  }
}

/** What a message's label says. */
function numbered(_spec: SequenceSpec, message: Message, _number = 0): string {
  return message.text;
}

function addNumber(marks: Mark[], text: TextSetter, type: TypeSizes, number: number, at: Vec2): void {
  const label = String(number);
  const disc = new VectorPath();
  disc.addCircle(at.x, at.y, 9);
  marks.push(shapeMark(disc, Tone.hue("accent"), null, 0));
  marks.push(text.centred(label, at.x, at.y, type.small * 0.82, FontWeights.SemiBold, Tone.of("background")));
}

function addHead(marks: Mark[], tip: Vec2, direction: Vec2, open: boolean, ink: Tone): void {
  if (open) {
    const u = normalize(direction);
    const n = vec(-u.y, u.x);
    const v = new VectorPath();
    v.moveTo(add(sub(tip, mul(u, 9)), mul(n, 5))).lineTo(tip).lineTo(sub(sub(tip, mul(u, 9)), mul(n, 5)));
    marks.push(shapeMark(v, null, ink, 1.4));
    return;
  }
  const end = Shapes.end("arrow", tip, direction, 9);
  if (end !== null) marks.push(shapeMark(end.path, ink, null, 0));
}

function head(scene: Scene, text: TextSetter, type: TypeSizes, p: Participant, cx: number, y: number, width: number, rowHeight: number, top: boolean): void {
  const hue = p.hue;
  switch (p.role) {
    case "actor": {
      // A stick figure above its name at the top, below it at the foot.
      const name: TextMark = text.centred(p.label, cx, 0, type.label, FontWeights.SemiBold, Tone.of("ink"));
      const figureTop = top ? y + rowHeight - name.height - 46 : y + 6;
      const nameTop = top ? y + rowHeight - name.height : figureTop + 46;
      const headCircle = new VectorPath();
      headCircle.addCircle(cx, figureTop + 7, 7);
      scene.add(shapeMark(headCircle, hue.washed(0.2), hue, 1.6));
      const body = new VectorPath();
      body.moveTo(cx, figureTop + 14).lineTo(cx, figureTop + 30);
      body.moveTo(cx - 12, figureTop + 19).lineTo(cx + 12, figureTop + 19);
      body.moveTo(cx, figureTop + 30).lineTo(cx - 10, figureTop + 42);
      body.moveTo(cx, figureTop + 30).lineTo(cx + 10, figureTop + 42);
      scene.add(shapeMark(body, null, hue, 1.6));
      scene.add({ ...name, y: nameTop });
      break;
    }
    default: {
      const label = text.measure(p.label, type.label, FontWeights.SemiBold);
      const h = label.height + 2 * HeadPadY + (p.role === "database" ? 10 : 0);
      const boxTop = top ? y + rowHeight - h : y;
      const box = RectF.fromXYWH(cx - width / 2, boxTop, width, h);
      scene.add(shapeMark(Shapes.outline(p.role === "database" ? "cylinder" : "box", box), hue.washed(0.14), hue.washed(0.9), 1.5));
      scene.add(text.centred(p.label, cx, box.midY + (p.role === "database" ? 4 : 0), type.label, FontWeights.SemiBold, Tone.of("ink")));
      break;
    }
  }
}

registerKind("sequence", (context) => new SequenceParser(context));
