// The statistics charts draw: here, fitted trends. Ported from Parcel NExT's Divooka.Graphics.Plotting/Statistics/Statistics.cs
// (TrendFit and ChartStatistics.Trend with what it needs; box plots, densities and histogram bins are not drawn by Dhole). Not-a-number
// values are left out of everything.

import { formatWith } from "./formatting";

/** What kind of curve a trend line fits: a straight line by least squares, a polynomial of the stated degree, or a smooth local fit (LOESS) that follows the data's shape without a formula. */
export type TrendKind = "linear" | "polynomial" | "smooth";

/** A fitted trend: its curve, sampled, and for a formula fit its coefficients and how well it fits. */
export class TrendFit {
  constructor(
    readonly kind: TrendKind,
    /** Where the curve was sampled. */
    readonly x: readonly number[],
    /** The curve at each sample. */
    readonly y: readonly number[],
    /** The lower edge of the 95% confidence band at each sample, for a formula fit. */
    readonly lower: readonly number[] | null,
    /** The upper edge of the 95% confidence band at each sample, for a formula fit. */
    readonly upper: readonly number[] | null,
    /** The polynomial's coefficients from the constant term up, in the data's own units; empty for a smooth fit. */
    readonly coefficients: readonly number[],
    /** The share of the variance the fit explains, from 0 to 1; not a number for a smooth fit. */
    readonly rSquared: number,
  ) {}

  /** The formula as text: y = 2.31x + 0.40. */
  get equation(): string {
    if (this.coefficients.length === 0) return "smooth fit";
    const terms: string[] = [];
    for (let p = this.coefficients.length - 1; p >= 0; p--) {
      const c = this.coefficients[p];
      const value = formatWith(Math.abs(c), Math.abs(c) >= 100 ? ",.1f" : ".3~g");
      const term = p === 0 ? value : p === 1 ? value + "x" : value + "x" + [...String(p)].map((d) => "⁰¹²³⁴⁵⁶⁷⁸⁹"[+d]).join("");
      terms.push(terms.length === 0 ? (c < 0 ? "−" : "") + term : (c < 0 ? " − " : " + ") + term);
    }
    return "y = " + terms.join("");
  }
}

function powers(u: number, p: number): number[] {
  const out = new Array<number>(p + 1);
  out[0] = 1;
  for (let i = 1; i <= p; i++) out[i] = out[i - 1] * u;
  return out;
}

/** The coefficients of sum(b_k ((x - m)/s)^k) as a polynomial in x. */
function expand(beta: readonly number[], mean: number, scale: number): number[] {
  const p = beta.length - 1;
  const result = new Array<number>(p + 1).fill(0);
  for (let k = 0; k <= p; k++) {
    const factor = beta[k] / Math.pow(scale, k);
    // (x - m)^k = sum_j C(k, j) x^j (-m)^(k - j)
    for (let j = 0; j <= k; j++) result[j] += factor * binomial(k, j) * Math.pow(-mean, k - j);
  }
  return result;
}

function binomial(n: number, k: number): number {
  let result = 1;
  for (let i = 1; i <= k; i++) result = (result * (n - k + i)) / i;
  return result;
}

function invert(matrix: number[][]): number[][] {
  const n = matrix.length;
  const a = matrix.map((row) => [...row]);
  const inv = matrix.map((_, i) => matrix.map((__, j) => (i === j ? 1 : 0)));
  for (let col = 0; col < n; col++) {
    let pivot = col;
    for (let r = col + 1; r < n; r++) if (Math.abs(a[r][col]) > Math.abs(a[pivot][col])) pivot = r;
    if (Math.abs(a[pivot][col]) < 1e-14) throw new Error("The points do not determine a fit of that degree: there are too few distinct x values.");
    if (pivot !== col) {
      [a[col], a[pivot]] = [a[pivot], a[col]];
      [inv[col], inv[pivot]] = [inv[pivot], inv[col]];
    }
    const d = a[col][col];
    for (let c = 0; c < n; c++) {
      a[col][c] /= d;
      inv[col][c] /= d;
    }
    for (let r = 0; r < n; r++) {
      if (r === col) continue;
      const f = a[r][col];
      if (f === 0) continue;
      for (let c = 0; c < n; c++) {
        a[r][c] -= f * a[col][c];
        inv[r][c] -= f * inv[col][c];
      }
    }
  }
  return inv;
}

/** A local linear fit at `at` with tricube weights over the nearest share of the points. */
function loess(points: readonly [number, number][], at: number, span: number): number {
  const k = Math.max(2, Math.ceil(span * points.length));
  const distances = points.map(([x]) => Math.abs(x - at)).sort((a, b) => a - b);
  let reach = distances[Math.min(k, distances.length) - 1];
  if (reach <= 0) reach = 1e-12;
  let sw = 0;
  let swx = 0;
  let swy = 0;
  let swxx = 0;
  let swxy = 0;
  for (const [x, y] of points) {
    const d = Math.abs(x - at) / reach;
    if (d >= 1) continue;
    const w = Math.pow(1 - d * d * d, 3);
    sw += w;
    swx += w * x;
    swy += w * y;
    swxx += w * x * x;
    swxy += w * x * y;
  }
  if (sw === 0) return NaN;
  const denominator = sw * swxx - swx * swx;
  if (Math.abs(denominator) < 1e-12) return swy / sw;
  const slope = (sw * swxy - swx * swy) / denominator;
  const intercept = (swy - slope * swx) / sw;
  return intercept + slope * at;
}

/** The 97.5th percentile of Student's t with `df` degrees of freedom: the multiplier of a two-sided 95% interval. */
export function studentT975(df: number): number {
  const table = [12.706, 4.303, 3.182, 2.776, 2.571, 2.447, 2.365, 2.306, 2.262, 2.228, 2.201, 2.179, 2.16, 2.145, 2.131, 2.12, 2.11, 2.101, 2.093, 2.086, 2.08, 2.074, 2.069, 2.064, 2.06, 2.056, 2.052, 2.048, 2.045, 2.042];
  if (df < 1) return NaN;
  if (df <= 30) return table[df - 1];
  // Beyond the table the quantile is close to linear in 1/df: 2.042 at 30, 2.021 at 40, 2.000 at 60, 1.980 at 120, 1.960 in the limit.
  const tail: [number, number][] = [
    [30, 2.042],
    [40, 2.021],
    [60, 2.0],
    [120, 1.98],
    [Number.POSITIVE_INFINITY, 1.96],
  ];
  for (let i = 0; i < tail.length - 1; i++) {
    if (df <= tail[i + 1][0]) {
      const a = 1 / tail[i][0];
      const b = tail[i + 1][0] === Number.POSITIVE_INFINITY ? 0 : 1 / tail[i + 1][0];
      const t = (1 / df - a) / (b - a);
      return tail[i][1] + (tail[i + 1][1] - tail[i][1]) * t;
    }
  }
  return 1.96;
}

/** Fits a trend to points: a straight line or a polynomial by least squares, with a 95% confidence band for the fitted mean, or a smooth local fit. */
export function trend(x: readonly number[], y: readonly number[], kind: TrendKind = "linear", degree = 2, span = 0.75, samples = 100): TrendFit {
  if (x.length !== y.length) throw new Error(`There are ${x.length} x values and ${y.length} y values.`);
  const points: [number, number][] = [];
  for (let i = 0; i < x.length; i++) if (Number.isFinite(x[i]) && Number.isFinite(y[i])) points.push([x[i], y[i]]);
  points.sort((a, b) => a[0] - b[0]);
  const n = points.length;
  if (n < 2) throw new Error("A trend needs at least two points.");
  const lowX = points[0][0];
  const highX = points[n - 1][0];
  const grid = Array.from({ length: samples }, (_, i) => lowX + ((highX - lowX) * i) / (samples - 1));

  if (kind === "smooth") return new TrendFit(kind, grid, grid.map((g) => loess(points, g, Math.min(Math.max(span, 0.1), 1))), null, null, [], NaN);

  const p = kind === "linear" ? 1 : Math.min(Math.max(degree, 1), 6);
  if (n <= p) throw new Error(`A degree-${p} fit needs more than ${p} points; there are ${n}.`);

  // Least squares in a centred, scaled variable, which keeps the normal equations well conditioned; the coefficients are then expanded back into the data's units.
  const mean = points.reduce((s, q) => s + q[0], 0) / n;
  const scale = Math.max(1e-12, Math.max(...points.map((q) => Math.abs(q[0] - mean))));
  const normal = Array.from({ length: p + 1 }, () => new Array<number>(p + 1).fill(0));
  const rhs = new Array<number>(p + 1).fill(0);
  for (const [px, py] of points) {
    const pw = powers((px - mean) / scale, p);
    for (let r = 0; r <= p; r++) {
      rhs[r] += pw[r] * py;
      for (let c = 0; c <= p; c++) normal[r][c] += pw[r] * pw[c];
    }
  }
  const inverse = invert(normal);
  const beta = new Array<number>(p + 1).fill(0);
  for (let r = 0; r <= p; r++) for (let c = 0; c <= p; c++) beta[r] += inverse[r][c] * rhs[c];

  const fit = (at: number): number => {
    const pw = powers((at - mean) / scale, p);
    let value = 0;
    for (let r = 0; r <= p; r++) value += beta[r] * pw[r];
    return value;
  };

  const meanY = points.reduce((s, q) => s + q[1], 0) / n;
  const residual = points.reduce((s, q) => s + (q[1] - fit(q[0])) * (q[1] - fit(q[0])), 0);
  const total = points.reduce((s, q) => s + (q[1] - meanY) * (q[1] - meanY), 0);
  const rSquared = total === 0 ? 1 : 1 - residual / total;

  const fitted = grid.map(fit);
  let lower: number[] | null = null;
  let upper: number[] | null = null;
  const df = n - p - 1;
  if (df > 0) {
    const s = Math.sqrt(residual / df);
    const t = studentT975(df);
    lower = new Array<number>(samples);
    upper = new Array<number>(samples);
    for (let i = 0; i < samples; i++) {
      const pw = powers((grid[i] - mean) / scale, p);
      let leverage = 0;
      for (let r = 0; r <= p; r++) for (let c = 0; c <= p; c++) leverage += pw[r] * inverse[r][c] * pw[c];
      const half = t * s * Math.sqrt(Math.max(0, leverage));
      lower[i] = fitted[i] - half;
      upper[i] = fitted[i] + half;
    }
  }
  return new TrendFit(kind, grid, fitted, lower, upper, expand(beta, mean, scale), rSquared);
}
