/** A copy with every text size multiplied by `factor`. */
export function withTextScale(theme: Theme, factor: number): Theme {
  return {
    ...theme,
    fontSize: theme.fontSize * factor,
    axisTitleSize: theme.axisTitleSize * factor,
    titleSize: theme.titleSize * factor,
    figureTitleSize: theme.figureTitleSize * factor,
    subtitleSize: theme.subtitleSize * factor,
    captionSize: theme.captionSize * factor,
    dataLabelSize: theme.dataLabelSize * factor,
  };
}

/** A copy that sets text in `family` first, keeping the others as fallbacks. */
export function withFont(theme: Theme, family: string): Theme {
  if (!family.trim()) return theme;
  return { ...theme, fontFamilies: [family, ...theme.fontFamilies.filter((f) => f.toLowerCase() !== family.toLowerCase())] };
}

/** Light ink on a near-black surface, with the palette stepped for it. */
export const Dark: Theme = {
  ...Light,
  name: "Dark",
  background: parseHex("#1a1a19"),
  ink: parseHex("#ffffff"),
  secondaryInk: parseHex("#c3c2b7"),
  mutedInk: parseHex("#898781"),
  grid: parseHex("#2c2c2a"),
  axisLine: parseHex("#4a4a46"),
  palette: Palette.DivookaDark,
};

/** Larger text and heavier marks, for a slide seen from across a room. */
export const Presentation: Theme = withTextScale({ ...Light, name: "Presentation", lineWidth: 3, pointSize: 10, padding: 24 }, 1.4);

/** No gridlines and no axis lines: the data, its labels and nothing else. */
export const Minimal: Theme = { ...Light, name: "Minimal", gridY: false, axisLines: false, tickLength: 0 };

/** A framed plotting area with gridlines both ways and Category10 colours: the look of a classic scientific plot. */
export const Classic: Theme = {
  ...Light,
  name: "Classic",
  palette: Palette.Category10,
  gridX: true,
  frame: true,
  grid: parseHex("#e6e6e6"),
  axisLine: parseHex("#444444"),
  secondaryInk: parseHex("#222222"),
  barRadius: 0,
  pointRing: 0,
  lineWidth: 1.5,
  pointSize: 6,
};

/** Black ink, grey marks and a framed plotting area, for a page printed without colour. */
export const Print: Theme = {
  ...Light,
  name: "Print",
  ink: parseHex("#000000"),
  secondaryInk: parseHex("#222222"),
  mutedInk: parseHex("#555555"),
  grid: parseHex("#d4d4d4"),
  axisLine: parseHex("#000000"),
  palette: Palette.Grays,
  frame: true,
  barRadius: 0,
};

/** A theme read off an editor palette's tokens: the accent and the category hues in order, a hue that repeats an earlier one left out. */
function fromPalette(name: string, dark: boolean, canvas: string, ink: string, secondaryInk: string, mutedInk: string, hairline: string, strong: string, success: string, error: string, hues: string[]): Theme {
  const basis = dark ? Dark : Light;
  const distinct: string[] = [];
  for (const hue of hues) if (!distinct.some((d) => d.toLowerCase() === hue.toLowerCase())) distinct.push(hue);
  return {
    ...basis,
    name,
    background: parseHex(canvas),
    ink: parseHex(ink),
    secondaryInk: parseHex(secondaryInk),
    mutedInk: parseHex(mutedInk),
    grid: parseHex(hairline),
    axisLine: parseHex(strong),
    palette: Palette.fromHex(name, ...distinct),
    rising: parseHex(success),
    falling: parseHex(error),
  };
}

