/** Every preset, by name. */
export const Presets: readonly Theme[] = [Light, Dark, Presentation, Minimal, Classic, Print, Golden, QuietGold, SilverGold, HighContrast];

function themeKey(name: string | null | undefined): string {
  let out = "";
  for (const c of name ?? "") if (/[\p{L}\p{N}]/u.test(c)) out += c.toLowerCase();
  return out;
}

/** The preset called `name` (case, spaces and hyphens ignored), or null when there is none. */
export function findTheme(name: string | null | undefined): Theme | null {
  const key = themeKey(name);
  return key.length === 0 ? null : Presets.find((t) => themeKey(t.name) === key) ?? null;
}
