// What a chart's layers and its renderer say to each other: a layer made ready to draw, the training of a chart's axes and colours,
// the colours that training resolves to, the legend entries layers contribute, the polar frame of a radar, and what a layer draws
// with. Ported from Parcel NExT's Divooka.Graphics.Plotting/Rendering/Contracts.cs.

import type { ColorScale, LegendItem, LegendSwatch } from "./axis";
import type { DrawContext, FrameKind, Layer, LayerPlan, TextPainter } from "./figure";
import type { Paint } from "./sink";
import type { Colour, Palette, Theme } from "./theme";
import { AxisTraining, type AxisTick, type PositionScale, type ScaleDomain } from "./scales";
import { describeKind, type Series, type SeriesKind } from "./series";

// ---------------------------------------------------------------- layer plans

/**
 * A layer made ready to draw: its derived data computed, and the things a chart asks of it - which frame it needs, what values it
 * binds to the axes and the colour scale, how it draws, what it adds to the legend, and how far its marks reach past the plotting
 * area.
 */
export abstract class ChartLayerPlan implements LayerPlan {
  readonly [extra: string]: unknown;
  readonly layer: Layer;

  constructor(layer: Layer) {
    this.layer = layer;
  }

  /** The frame the layer needs. */
  get frame(): FrameKind {
    return "cartesian";
  }
  /** Whether the marks are kept inside the plotting area. */
  get clipToPlot(): boolean {
    return true;
  }
  /** Tell the chart's axes and colour scale what values this layer binds to them. */
  train(_training: ChartTraining): void {}
  /** Draw the marks. */
  abstract draw(context: DrawContext): void;
  /** Contribute legend entries. */
  addLegend(_legend: LegendCollector): void {}
  /** The extra room in pixels the marks need beyond the plotting area's edges, such as a label above the tallest bar. */
  overhang(_text: TextPainter): number {
    return 0;
  }
}

// ---------------------------------------------------------------- training

/** The axes and colour scale of one chart while its layers are trained. */
export class ChartTraining {
  constructor(
    readonly x: AxisTraining,
    readonly y: AxisTraining,
    readonly y2: AxisTraining,
    readonly color: ColorTraining,
  ) {}

  /** The vertical axis a layer reads its values on. */
  yOf(layer: Layer): AxisTraining {
    return layer.secondaryAxis ? this.y2 : this.y;
  }
  /** The axis a layer places its values along, horizontal or vertical. */
  valueAxisOf(layer: Layer, horizontal: boolean): AxisTraining {
    return horizontal ? this.x : this.yOf(layer);
  }
  /** The axis a layer places its categories along. */
  categoryAxisOf(layer: Layer, horizontal: boolean): AxisTraining {
    return horizontal ? this.yOf(layer) : this.x;
  }
}

/** What a chart's colour channel was given: categories or numbers. */
export class ColorTraining {
  private readonly seen = new Set<string>();
  kind: SeriesKind | null = null;
  readonly categories: string[] = [];
  low = Number.POSITIVE_INFINITY;
  high = Number.NEGATIVE_INFINITY;
  title: string | null = null;

  add(series: Series): void {
    if (series.kind === "text") {
      this.claim("text");
      for (const category of series.textsOf)
        if (!this.seen.has(category)) {
          this.seen.add(category);
          this.categories.push(category);
        }
    } else {
      this.claim("number");
      for (let i = 0; i < series.count; i++) this.addValue(series.position(i));
    }
    if (this.title === null && series.name.length > 0) this.title = series.name;
  }

  addCategory(category: string): void {
    this.claim("text");
    if (!this.seen.has(category)) {
      this.seen.add(category);
      this.categories.push(category);
    }
  }

  addValue(value: number): void {
    this.claim("number");
    if (!Number.isFinite(value)) return;
    if (value < this.low) this.low = value;
    if (value > this.high) this.high = value;
  }

  private claim(kind: SeriesKind): void {
    this.kind ??= kind;
    if (this.kind !== kind && !(this.kind === "number" && kind === "time") && !(this.kind === "time" && kind === "number"))
      throw new Error(`A chart's colours were bound to ${describeKind(this.kind)} and then to ${describeKind(kind)}; colour one chart by one kind of value.`);
  }
}

/** The trained colour scale of one chart: categories to palette colours. Colouring by numbers along a colour map is not ported - no Dhole chart does it. */
export class ColorAssignment {
  private readonly categorical = new Map<string, Colour>();
  readonly spec: ColorScale;
  readonly categories: readonly string[];
  readonly title: string | null;
  readonly isContinuous: boolean;
  readonly hasCategories: boolean;
  readonly low: number;
  readonly high: number;

  constructor(training: ColorTraining, spec: ColorScale, theme: Theme) {
    this.spec = spec;
    this.categories = training.categories;
    this.title = spec.title ?? training.title;
    const palette: Palette = spec.palette ?? theme.palette;
    training.categories.forEach((category, i) => this.categorical.set(category, palette.at(i)));
    this.isContinuous = training.kind === "number";
    let low = spec.min ?? (Number.isFinite(training.low) ? training.low : 0);
    let high = spec.max ?? (Number.isFinite(training.high) ? training.high : 1);
    if (low === high) {
      low -= 0.5;
      high += 0.5;
    }
    this.low = low;
    this.high = high;
    this.hasCategories = training.kind === "text" && training.categories.length > 0;
  }

  forCategory(category: string): Colour {
    return this.categorical.get(category) ?? { r: 128, g: 128, b: 128, a: 255 };
  }

  forValue(_value: number): Colour {
    throw new Error("Colouring by a number is not drawn on this page.");
  }
}

// ---------------------------------------------------------------- legends

/** The legend entries a chart's layers contribute, in order, without duplicates. */
export class LegendCollector {
  private readonly labels = new Set<string>();
  readonly items: LegendItem[] = [];
  colorBar: ColorAssignment | null = null;
  /** The chart's trained colours, for entries that stand for a category. */
  readonly colors: ColorAssignment;

  constructor(colors: ColorAssignment) {
    this.colors = colors;
  }

  add(label: string | null | undefined, color: Colour, swatch: LegendSwatch): void {
    if (!label || this.labels.has(label)) return;
    this.labels.add(label);
    this.items.push({ label, color, swatch });
  }

  /** An entry for every category of the chart's colour channel that `series` names. */
  addSeriesCategories(series: Series, swatch: LegendSwatch): void {
    if (series.kind !== "text") {
      this.colorBar = this.colors;
      return;
    }
    for (const category of series.distinctTexts()) this.add(category, this.colors.forCategory(category), swatch);
  }

  /** An entry for each category given. */
  addCategories(categories: Iterable<string>, swatch: LegendSwatch): void {
    for (const category of categories) this.add(category, this.colors.forCategory(category), swatch);
  }
}

// ---------------------------------------------------------------- the polar frame

/** The polar frame of a radar chart: where its centre is, how far its rings reach, and which way its spokes point. */
export class PolarFrame {
  constructor(
    readonly centerX: number,
    readonly centerY: number,
    readonly radius: number,
    readonly spokes: readonly string[],
    readonly radial: ScaleDomain,
    readonly rings: readonly AxisTick[],
  ) {}

  /** The angle of spoke `index`, in radians clockwise from straight up. */
  angle(index: number): number {
    return this.spokes.length === 0 ? 0 : (index * 2 * Math.PI) / this.spokes.length;
  }

  /** The distance from the centre for a value. */
  radiusOf(value: number): number {
    if (this.radial.max === this.radial.min) return 0;
    return Math.min(Math.max((value - this.radial.min) / (this.radial.max - this.radial.min), 0), 1.2) * this.radius;
  }

  /** The point at a spoke and a value. */
  point(index: number, value: number): { x: number; y: number } {
    const angle = this.angle(index);
    const r = this.radiusOf(value);
    return { x: this.centerX + r * Math.sin(angle), y: this.centerY - r * Math.cos(angle) };
  }
}

/** A layer drawn on spokes and rings. */
export interface PolarLayer {
  trainPolar(training: PolarTraining): void;
}

/** What a radial chart's layers named: their spokes, and the range of their values. */
export class PolarTraining {
  private readonly seen = new Set<string>();
  readonly spokes: string[] = [];
  low = Number.POSITIVE_INFINITY;
  high = Number.NEGATIVE_INFINITY;

  addSpoke(spoke: string): void {
    if (!this.seen.has(spoke)) {
      this.seen.add(spoke);
      this.spokes.push(spoke);
    }
  }

  addValue(value: number): void {
    if (!Number.isFinite(value)) return;
    this.low = Math.min(this.low, value);
    this.high = Math.max(this.high, value);
  }
}

// ---------------------------------------------------------------- drawing

/** Everything a chart layer draws with: the figure's draw context, with the chart's colours and - in the frames that have them - its scales or its polar frame. */
export interface ChartDrawContext extends DrawContext {
  readonly colors: ColorAssignment;
  readonly x?: PositionScale | null;
  readonly y?: PositionScale | null;
  readonly y2?: PositionScale | null;
  readonly polar?: PolarFrame | null;
}

/** The chart parts of a draw context. */
export function chartContext(context: DrawContext): ChartDrawContext {
  return context as ChartDrawContext;
}

/** The vertical scale a layer reads its values on. */
export function yOf(context: DrawContext, layer: Layer): PositionScale {
  const c = chartContext(context);
  const scale = layer.secondaryAxis ? c.y2 : c.y;
  if (!scale) throw new Error("This layer needs axes, and its chart has none.");
  return scale;
}

/** The horizontal scale. */
export function xScale(context: DrawContext): PositionScale {
  const scale = chartContext(context).x;
  if (!scale) throw new Error("This layer needs axes, and its chart has none.");
  return scale;
}

/** A coordinate moved to where a line of `width` pixels renders crisply: unmoved on a vector sink, which needs no snapping. */
export function snap(context: DrawContext, value: number, width = 1): number {
  const deviceScale = context.deviceScale;
  if (deviceScale <= 0 || Number.isNaN(value)) return value;
  const device = value * deviceScale;
  const deviceWidth = Math.max(1, Math.round(width * deviceScale));
  const snapped = deviceWidth % 2 === 1 ? Math.floor(device) + 0.5 : Math.round(device);
  return snapped / deviceScale;
}

/** The paints a chart draws with. */
export const ChartPaints = {
  fill(colour: Colour): Paint {
    return { colour, style: "fill" };
  },
  stroke(colour: Colour, width: number, dash?: readonly number[] | null, round = true): Paint {
    return {
      colour,
      style: "stroke",
      strokeWidth: Math.max(0.01, width),
      cap: round ? "round" : "butt",
      join: round ? "round" : "miter",
      dash: dash && dash.length > 1 ? dash : undefined,
    };
  },
  /** A hairline: gridlines, axis lines, tick marks. */
  hairline(colour: Colour, width: number): Paint {
    return ChartPaints.stroke(colour, width, null, false);
  },
};

export { AxisTraining };
