// Lines through points in order, points placed by x and y, and filled bands between a line and a baseline - with the stacking of
// bands per category, and the placing of a series' values with a scale. Ported from Parcel NExT's
// Divooka.Graphics.Plotting/Layers/Lines.cs. Points sized by a number (a bubble chart) are not ported: no Dhole chart sizes points.

import type { LegendSwatch } from "../axis";
import { withOpacity } from "../color-math";
import { ChartLayerPlan, ChartPaints, chartContext, xScale, yOf, type ChartTraining, type LegendCollector } from "../contracts";
import { Layer, type DrawContext, type PlanContext } from "../figure";
import type { PositionScale } from "../scales";
import { describeKind, Series } from "../series";
import type { Colour } from "../theme";
import { decimate, dashOf, drawPoint, polyline, polylineCommands, type LineDash, type LineShape, type PointShape } from "./marks";
import type { Vec2 } from "../../rendering/geometry";

/** How bars or areas per category are combined: side by side (bars) or overlapping (areas), each from zero; piled up, each starting where the one before ended; or piled up and scaled so each pile reaches 100%. */
export type StackMode = "grouped" | "stacked" | "percent";

// ---------------------------------------------------------------- lines

/**
 * A line through points in order: a series over time, a function, a trace. A not-a-number value breaks the line, so a gap in the data
 * is a gap on the chart rather than a straight segment across it. With `colorBy` one layer draws one line per category, each in its
 * category's colour.
 */
export class Line extends Layer {
  readonly x: Series;
  readonly y: Series;
  /** How the line passes through its points. */
  shape: LineShape = "straight";
  /** The line's width; unset, the theme's. */
  width: number | null = null;
  /** How the line is dashed. */
  dash: LineDash = "solid";
  /** Whether each point is marked. */
  markers = false;
  /** The marks' shape. */
  markerShape: PointShape = "circle";
  /** Draws one line per category of this series, each in its category's colour. */
  colorBy: Series | null = null;
  /** Whether the line's name is written at its last point, as well as in the legend. */
  endLabel = false;

  constructor(x: Series | readonly number[] | readonly string[], y: Series | readonly number[]) {
    super();
    this.x = Series.of(x);
    this.y = Series.of(y);
  }

  plan(context: PlanContext): LinePlan {
    Check.sameLength(this.x, this.y, "x", "y");
    if (this.colorBy !== null) Check.sameLength(this.x, this.colorBy, "x", "colour");
    return new LinePlan(this, this.colorBy === null ? context.seriesColor(this) : { r: 0, g: 0, b: 0, a: 0 });
  }
}

class LinePlan extends ChartLayerPlan {
  constructor(
    private readonly line: Line,
    private readonly color: Colour,
  ) {
    super(line);
  }

  override train(training: ChartTraining): void {
    training.x.add(this.line.x);
    training.yOf(this.line).add(this.line.y);
    if (this.line.colorBy !== null) training.color.add(this.line.colorBy);
  }

  draw(context: DrawContext): void {
    const line = this.line;
    const x = xScale(context);
    const y = yOf(context, line);
    const width = line.width ?? context.theme.lineWidth;
    for (const { indices, color: stroke, name } of this.groups(context)) {
      const points: Vec2[] = indices.map((i) => ({ x: project(x, line.x, i), y: project(y, line.y, i) }));
      const drawn = decimate(points, context.plot.width);
      const ink = withOpacity(stroke, line.opacity);
      const path = polyline(drawn, line.shape);
      context.sink.drawPath(path, ChartPaints.stroke(ink, width, dashOf(line.dash, width)));
      if (line.markers && drawn.length === points.length) for (const p of points) drawPoint(context.sink, p.x, p.y, line.markerShape, context.theme.pointSize, ink, context.surface, context.theme.pointRing);
      if (line.endLabel && name) {
        const finite = points.filter((p) => Number.isFinite(p.x) && Number.isFinite(p.y));
        const end = finite[finite.length - 1];
        if (end) context.text.draw(context.sink, name, end.x + 6, end.y, "dataLabel", context.theme.secondaryInk, "left");
      }
    }
  }

  private groups(context: DrawContext): { indices: number[]; color: Colour; name: string | null }[] {
    const line = this.line;
    if (line.colorBy === null) return [{ indices: Array.from({ length: line.x.count }, (_, i) => i), color: this.color, name: line.label }];
    return groupBy(line.colorBy).map(({ category, indices }) => ({ indices, color: chartContext(context).colors.forCategory(category), name: category }));
  }

  override addLegend(legend: LegendCollector): void {
    const swatch: LegendSwatch = this.line.markers ? "lineAndPoint" : "line";
    if (this.line.colorBy === null) legend.add(this.line.label, this.color, swatch);
    else legend.addSeriesCategories(this.line.colorBy, swatch);
  }
}

// ---------------------------------------------------------------- points

/** Points placed by x and y: a scatter plot, a strip of observations. `colorBy` colours each point by a category. */
export class Points extends Layer {
  readonly x: Series;
  readonly y: Series;
  /** The points' shape. */
  shape: PointShape = "circle";
  /** The points' diameter in pixels; unset, the theme's. */
  size: number | null = null;
  /** Colours each point by a category, or along the chart's colour map by a number. */
  colorBy: Series | null = null;

  constructor(x: Series | readonly number[], y: Series | readonly number[]) {
    super();
    this.x = Series.of(x);
    this.y = Series.of(y);
  }

  plan(context: PlanContext): PointsPlan {
    Check.sameLength(this.x, this.y, "x", "y");
    if (this.colorBy !== null) Check.sameLength(this.x, this.colorBy, "x", "colour");
    return new PointsPlan(this, this.colorBy === null ? context.seriesColor(this) : { r: 0, g: 0, b: 0, a: 0 });
  }
}

class PointsPlan extends ChartLayerPlan {
  constructor(
    private readonly points: Points,
    private readonly color: Colour,
  ) {
    super(points);
  }

  override train(training: ChartTraining): void {
    training.x.add(this.points.x);
    training.yOf(this.points).add(this.points.y);
    if (this.points.colorBy !== null) training.color.add(this.points.colorBy);
  }

  draw(context: DrawContext): void {
    const points = this.points;
    const x = xScale(context);
    const y = yOf(context, points);
    const ring = context.theme.pointRing;
    for (let i = 0; i < points.x.count; i++) {
      const px = project(x, points.x, i);
      const py = project(y, points.y, i);
      if (!Number.isFinite(px) || !Number.isFinite(py)) continue;
      let fill = this.color;
      if (points.colorBy !== null)
        fill = points.colorBy.kind === "text" ? chartContext(context).colors.forCategory(points.colorBy.textsOf[i]) : chartContext(context).colors.forValue(points.colorBy.position(i));
      const diameter = points.size ?? context.theme.pointSize;
      drawPoint(context.sink, px, py, points.shape, diameter, withOpacity(fill, points.opacity), context.surface, ring);
    }
  }

  override addLegend(legend: LegendCollector): void {
    if (this.points.colorBy === null) legend.add(this.points.label, this.color, "point");
    else legend.addSeriesCategories(this.points.colorBy, "point");
  }
}

// ---------------------------------------------------------------- areas

/**
 * A filled band between a line and a baseline: an area chart, a range between two series, a stacked area. The band runs from `y0`
 * (zero when unset) up to `y`. With `colorBy` one layer draws a band per category, and `stack` piles them up - each category's band
 * starting where the one below ended - on the x values they share. A single area is a wash of its colour under a full-strength line;
 * stacked areas are solid, separated by a hairline of the background.
 */
export class Area extends Layer {
  readonly x: Series;
  readonly y: Series;
  /** The bottom of the band; unset, zero. */
  y0: Series | null = null;
  /** How the edges pass through their points. */
  shape: LineShape = "straight";
  /** Draws a band per category of this series. */
  colorBy: Series | null = null;
  /** How bands per category are combined. */
  stack: StackMode = "stacked";
  /** Whether the top edge is drawn as a line. */
  outline = true;
  /** How opaque the fill is; unset, a wash for one band and nearly solid for stacked ones. */
  fillOpacity: number | null = null;

  constructor(x: Series | readonly number[] | readonly string[], y: Series | readonly number[]) {
    super();
    this.x = Series.of(x);
    this.y = Series.of(y);
  }

  plan(context: PlanContext): AreaPlan {
    Check.sameLength(this.x, this.y, "x", "y");
    if (this.y0 !== null) Check.sameLength(this.x, this.y0, "x", "baseline");
    if (this.colorBy !== null) Check.sameLength(this.x, this.colorBy, "x", "colour");
    if (this.y.kind !== "number") throw new Error("An area's heights must be numbers.");
    return new AreaPlan(this, this.colorBy === null ? context.seriesColor(this) : { r: 0, g: 0, b: 0, a: 0 });
  }
}

class AreaPlan extends ChartLayerPlan {
  private readonly stacking: Stacking | null;

  constructor(
    private readonly area: Area,
    private readonly color: Colour,
  ) {
    super(area);
    this.stacking = area.colorBy !== null ? Stacking.pivot(area.x, area.y, area.colorBy, area.stack) : null;
  }

  override train(training: ChartTraining): void {
    const area = this.area;
    const y = training.yOf(area);
    // An area filled down to zero is measured from zero, so its axis must show zero; a band between two series is not, and starting its axis at zero squeezes the band and everything drawn with it into the top of the chart.
    y.wantsZero = area.y0 === null || this.stacking !== null;
    if (this.stacking !== null) {
      for (const x of this.stacking.keys) training.x.addValue(x);
      training.x.claim(area.x.kind, area.x.name);
      for (const v of this.stacking.extent()) y.addValue(v);
      if (area.stack === "percent") y.preferredFormat = ".0%";
      for (const group of this.stacking.groups) training.color.addCategory(group);
      y.claim("number", area.y.name);
      return;
    }
    training.x.add(area.x);
    y.add(area.y);
    if (area.y0 !== null) y.add(area.y0);
  }

  draw(context: DrawContext): void {
    const area = this.area;
    const x = xScale(context);
    const y = yOf(context, area);
    const width = context.theme.lineWidth;
    if (this.stacking === null) {
      const n = area.x.count;
      const top: Vec2[] = [];
      const bottom: Vec2[] = [];
      for (let i = 0; i < n; i++) {
        const px = project(x, area.x, i);
        top.push({ x: px, y: project(y, area.y, i) });
        bottom.push({ x: px, y: area.y0 === null ? y.map(baseOf(y)) : project(y, area.y0, i) });
      }
      const opacity = (area.fillOpacity ?? context.theme.areaOpacity) * area.opacity;
      this.fillBand(context, top, bottom, withOpacity(this.color, opacity));
      if (area.outline) context.sink.drawPath(polyline(top, area.shape), ChartPaints.stroke(withOpacity(this.color, area.opacity), width));
      return;
    }

    const stacking = this.stacking;
    const stackedOpacity = (area.fillOpacity ?? 0.85) * area.opacity;
    for (let g = 0; g < stacking.groups.length; g++) {
      const top: Vec2[] = [];
      const bottom: Vec2[] = [];
      for (let k = 0; k < stacking.keys.length; k++) {
        const px = x.map(stacking.keys[k]);
        const [lo, hi] = stacking.span(g, k);
        top.push({ x: px, y: y.map(hi) });
        bottom.push({ x: px, y: y.map(lo) });
      }
      const fill = chartContext(context).colors.forCategory(stacking.groups[g]);
      this.fillBand(context, top, bottom, withOpacity(fill, stackedOpacity));
      if (area.outline) context.sink.drawPath(polyline(top, area.shape), ChartPaints.stroke(context.surface, 1));
    }
  }

  private fillBand(context: DrawContext, top: Vec2[], bottom: Vec2[], fill: Colour): void {
    const defined = (a: Vec2, b: Vec2): boolean => Number.isFinite(a.x) && Number.isFinite(a.y) && Number.isFinite(b.y);
    const shape = this.area.shape;
    // A band is drawn piece by piece between gaps, top edge forward and bottom edge back.
    let start = 0;
    while (start < top.length) {
      while (start < top.length && !defined(top[start], bottom[start])) start++;
      let end = start;
      while (end < top.length && defined(top[end], bottom[end])) end++;
      if (end - start >= 2) {
        const path = polyline(top.slice(start, end), shape);
        const back = bottom.slice(start, end).reverse();
        const lower = polylineCommands(back, shape === "stepAfter" ? "stepBefore" : shape === "stepBefore" ? "stepAfter" : shape);
        // Join the two edges into one closed outline.
        let first = true;
        for (const c of lower.commands) {
          if (c.verb === "M") {
            if (first) path.lineTo(c.x, c.y);
            first = false;
            continue;
          }
          if (c.verb === "L") path.lineTo(c.x, c.y);
          else if (c.verb === "C") path.cubicTo({ x: c.x1, y: c.y1 }, { x: c.x2, y: c.y2 }, { x: c.x, y: c.y });
        }
        path.close();
        context.sink.drawPath(path, ChartPaints.fill(fill));
      }
      start = end;
    }
  }

  override addLegend(legend: LegendCollector): void {
    const area = this.area;
    if (this.stacking !== null) legend.addCategories(this.stacking.groups, "fill");
    else if (!area.outline && area.fillOpacity !== null)
      // A band drawn only as a wash - a range, a confidence interval - is named by a swatch of that wash, so the legend shows what the chart shows rather than a solid block it never draws.
      legend.add(area.label, { ...this.color, a: Math.round(this.color.a * Math.min(Math.max(area.fillOpacity * area.opacity, 0), 1)) }, "fill");
    else legend.add(area.label, this.color, "fill");
  }
}

function baseOf(y: PositionScale): number {
  return y.type === "log" ? y.min : Math.min(Math.max(0, Math.min(y.min, y.max)), Math.max(y.min, y.max));
}

/** Long data pivoted into a table of groups by keys, with the stacked span of every cell. */
export class Stacking {
  private readonly spans: [number, number][][];

  private constructor(
    readonly keys: number[],
    readonly groups: string[],
    private readonly values: number[][],
    mode: StackMode,
  ) {
    this.spans = groups.map(() => keys.map((): [number, number] => [0, 0]));
    for (let k = 0; k < keys.length; k++) {
      let total = 0;
      if (mode === "percent") for (let g = 0; g < groups.length; g++) total += Math.abs(values[g][k]);
      let positive = 0;
      let negative = 0;
      for (let g = 0; g < groups.length; g++) {
        let v = values[g][k];
        if (mode === "percent") v = total === 0 ? 0 : v / total;
        if (mode === "grouped") {
          this.spans[g][k] = [0, v];
          continue;
        }
        if (v >= 0) {
          this.spans[g][k] = [positive, positive + v];
          positive += v;
        } else {
          this.spans[g][k] = [negative + v, negative];
          negative += v;
        }
      }
    }
  }

  value(group: number, key: number): number {
    return this.values[group][key];
  }
  span(group: number, key: number): [number, number] {
    return this.spans[group][key];
  }

  *extent(): Iterable<number> {
    for (let g = 0; g < this.groups.length; g++)
      for (let k = 0; k < this.keys.length; k++) {
        yield this.spans[g][k][0];
        yield this.spans[g][k][1];
      }
  }

  /** Pivot long data: one row per x key (sorted), one column per group (in order of appearance), summing repeats and treating absences as zero. */
  static pivot(x: Series, y: Series, groupBy: Series, mode: StackMode): Stacking {
    if (x.kind === "text") throw new Error("Stacked areas need numbers or times along x.");
    const groups = groupBy.distinctTexts();
    const keys = [...new Set(Array.from({ length: x.count }, (_, i) => x.position(i)).filter(Number.isFinite))].sort((a, b) => a - b);
    const keyIndex = new Map(keys.map((k, i) => [k, i]));
    const groupIndex = new Map(groups.map((g, i) => [g, i]));
    const values = groups.map(() => keys.map(() => 0));
    for (let i = 0; i < x.count; i++) {
      const key = x.position(i);
      const value = y.numbersOf[i];
      if (!Number.isFinite(key) || !Number.isFinite(value)) continue;
      values[groupIndex.get(groupBy.text(i))!][keyIndex.get(key)!] += value;
    }
    return new Stacking(keys, groups, values, mode);
  }
}

// ---------------------------------------------------------------- shared

/** The pixel of value `i` of a series placed with a scale: a category's middle, or a number. */
export function project(scale: PositionScale, series: Series, i: number): number {
  return series.kind === "text" ? scale.mapCategory(series.textsOf[i]) : scale.map(series.position(i));
}

/** A series' indices grouped by category, in order of first appearance. */
export function groupBy(series: Series): { category: string; indices: number[] }[] {
  const groups = new Map<string, number[]>();
  for (let i = 0; i < series.count; i++) {
    const key = series.text(i);
    let list = groups.get(key);
    if (!list) groups.set(key, (list = []));
    list.push(i);
  }
  return [...groups].map(([category, indices]) => ({ category, indices }));
}

/** The argument checks every layer makes. */
export const Check = {
  sameLength(a: Series, b: Series, nameA: string, nameB: string): void {
    if (a.count !== b.count) throw new Error(`The ${nameA} values (${a.count}) and the ${nameB} values (${b.count}) must be as many as each other.`);
  },
  numbers(series: Series, name: string): void {
    if (series.kind !== "number") throw new Error(`The ${name} must be numbers, not ${describeKind(series.kind)}.`);
  },
};
