// Figures, charts and layers, and the renderer that lays a figure out and draws it: the part of Divooka's plotting framework
// (Divooka.Graphics.Plotting: Model/Figure.cs, Model/Chart.cs, Layers/Drawing.cs, Rendering/FigureRenderer.cs,
// Rendering/TextPainter.cs) a Dhole diagram is drawn through. A Dhole text becomes a figure, exactly as it does in Divooka, so
// its title, subtitle, caption, padding and grid of several diagrams are laid out by the same arithmetic.
//
// A chart's layers decide its frame: marks placed by x and y get axes (cartesian), a radar gets spokes and rings (polar), and a
// pie or a diagram gets the plotting area alone (free). Training a chart's axes, colours and legend, and drawing the frames with
// axes and spokes, are registered by the chart kinds' module (`registerCharting`, from plot/frames), so a page that draws only
// diagrams carries none of it.

import { layoutText, FontWeights, type FontWeight, type TextLayout, type TextMeasurer } from "./text";
import { Light, type Colour, type Palette, type Theme } from "./theme";
import type { Sink } from "./sink";
import { RectF, rotationDegrees } from "../rendering/geometry";
import type { Axis, ColorScale, Legend } from "./axis";
import type { ChartTraining, LegendCollector } from "./contracts";

// ---------------------------------------------------------------- text roles

/** The jobs text does on a chart, each with its own size and weight from the theme. */
export type TextRole = "tick" | "axisTitle" | "chartTitle" | "figureTitle" | "subtitle" | "caption" | "legend" | "legendTitle" | "dataLabel";

/** Which point of a text block is placed at the coordinates given. */
export type TextAnchor = "topLeft" | "top" | "topRight" | "left" | "center" | "right" | "bottomLeft" | "bottom" | "bottomRight";

/** Measures and draws every word on a chart, so what is measured is exactly what is drawn. */
export class TextPainter {
  readonly theme: Theme;
  readonly measurer: TextMeasurer;
  private readonly layouts = new Map<string, TextLayout>();

  constructor(theme: Theme, measurer: TextMeasurer) {
    this.theme = theme;
    this.measurer = measurer;
  }

  /** The font size a role is set in. */
  sizeOf(role: TextRole): number {
    const t = this.theme;
    switch (role) {
      case "tick":
      case "legend":
        return t.fontSize;
      case "axisTitle":
      case "legendTitle":
        return t.axisTitleSize;
      case "chartTitle":
        return t.titleSize;
      case "figureTitle":
        return t.figureTitleSize;
      case "subtitle":
        return t.subtitleSize;
      case "caption":
        return t.captionSize;
      default:
        return t.dataLabelSize;
    }
  }

  static weightOf(role: TextRole): FontWeight {
    return role === "chartTitle" || role === "figureTitle" || role === "legendTitle" ? FontWeights.SemiBold : FontWeights.Normal;
  }

  /** The laid-out block for a piece of text in a role, on one line. */
  layout(text: string, role: TextRole): TextLayout {
    text ??= "";
    const key = `${role}|${text}`;
    let laid = this.layouts.get(key);
    if (!laid) {
      laid = layoutText(this.measurer, text.length === 0 ? " " : text, { families: this.theme.fontFamilies, size: this.sizeOf(role), weight: TextPainter.weightOf(role) });
      this.layouts.set(key, laid);
    }
    return laid;
  }

  /** The width and height a piece of text takes in a role. */
  measure(text: string, role: TextRole): { width: number; height: number } {
    if (!text) return { width: 0, height: 0 };
    const laid = this.layout(text, role);
    return { width: laid.width, height: laid.height };
  }

  /** The height of one line in a role, whatever its text. */
  lineHeight(role: TextRole): number {
    return this.measure("Ag", role).height;
  }

  /** The size a block takes once turned through `degrees`. */
  static rotated(size: { width: number; height: number }, degrees: number): { width: number; height: number } {
    const r = (degrees * Math.PI) / 180;
    const c = Math.abs(Math.cos(r));
    const s = Math.abs(Math.sin(r));
    return { width: size.width * c + size.height * s, height: size.width * s + size.height * c };
  }

  /** Draws text with its `anchor` point at (x, y), turned through `degrees` about that point. */
  draw(sink: Sink, text: string, x: number, y: number, role: TextRole, colour: Colour, anchor: TextAnchor, degrees = 0): void {
    if (!text || colour.a === 0) return;
    const laid = this.layout(text, role);
    const w = laid.width;
    const h = laid.height;
    const dx = anchor === "top" || anchor === "center" || anchor === "bottom" ? -w / 2 : anchor === "topRight" || anchor === "right" || anchor === "bottomRight" ? -w : 0;
    const dy = anchor === "left" || anchor === "center" || anchor === "right" ? -h / 2 : anchor === "bottomLeft" || anchor === "bottom" || anchor === "bottomRight" ? -h : 0;
    if (degrees === 0) {
      sink.drawText(laid, x + dx, y + dy, colour);
      return;
    }
    const saved = sink.save();
    try {
      sink.concat(rotationDegrees(degrees, x, y));
      sink.drawText(laid, x + dx, y + dy, colour);
    } finally {
      sink.restoreToCount(saved);
    }
  }

  /** The rectangle a block drawn at an anchor would cover, unrotated. */
  bounds(text: string, x: number, y: number, role: TextRole, anchor: TextAnchor): RectF {
    const size = this.measure(text, role);
    const left = anchor === "top" || anchor === "center" || anchor === "bottom" ? x - size.width / 2 : anchor === "topRight" || anchor === "right" || anchor === "bottomRight" ? x - size.width : x;
    const top = anchor === "left" || anchor === "center" || anchor === "right" ? y - size.height / 2 : anchor === "bottomLeft" || anchor === "bottom" || anchor === "bottomRight" ? y - size.height : y;
    return RectF.fromXYWH(left, top, size.width, size.height);
  }
}

// ---------------------------------------------------------------- model

/** The kind of frame a chart's layers are drawn in: placed by x and y, with axes; placed by angle and radius, with spokes and rings; or laid out by the layer itself in the plotting area, with no axes. */
export type FrameKind = "cartesian" | "polar" | "free";

/** What a layer is told while it is being planned: the theme, the palette its chart deals colours from, and where notes go. */
export interface PlanContext {
  readonly theme: Theme;
  readonly palette: Palette;
  readonly notes: string[];
  readonly measurer: TextMeasurer;
  /** The colour each one-series layer was dealt, by the layer itself rather than by its value: two equal layers are two series with two colours. */
  readonly assigned: Map<Layer, Colour>;
  /** The colour of a layer that is one series: its own, or the palette's next. */
  seriesColor(layer: Layer): Colour;
}

/** What a layer is drawn with: the sink, the theme, the text painter, its plotting area, and - in a chart's frames - its colours and scales. */
export interface DrawContext {
  readonly sink: Sink;
  readonly theme: Theme;
  readonly text: TextPainter;
  readonly plot: RectF;
  readonly notes: string[];
  /** Device pixels per figure pixel on a raster sink; 0 on a vector one such as SVG, where nothing is snapped. */
  readonly deviceScale: number;
  /** The colour the chart is drawn on. */
  readonly surface: Colour;
  /** Whatever a frame adds - scales, colour assignments - for the layers drawn in it. */
  readonly [extra: string]: unknown;
}

/**
 * A layer made ready to draw: its frame, and how it draws. A chart's layers say more of themselves - what they bind to the axes and
 * the colour scale, what they add to the legend, how far their marks reach past the plotting area - through the optional members,
 * which a drawing (a diagram laid out by its own code) has none of.
 */
export interface LayerPlan {
  readonly layer: Layer;
  readonly frame: FrameKind;
  readonly clipToPlot: boolean;
  draw(context: DrawContext): void;
  /** Tell the chart's axes and colour scale what values this layer binds to them. */
  train?(training: ChartTraining): void;
  /** Contribute legend entries. */
  addLegend?(legend: LegendCollector): void;
  /** The extra room in pixels the marks need beyond the plotting area's edges. */
  overhang?(text: TextPainter): number;
  readonly [extra: string]: unknown;
}

/** One layer of a chart: one kind of mark bound to data. A layer without a colour takes the next colour of its chart's palette, in the order layers are added, so the first series is always the first colour. */
export abstract class Layer {
  /** The layer's name in the legend. */
  label: string | null = null;
  /** The layer's colour, instead of the palette's next. */
  color: Colour | null = null;
  /** How opaque the layer is, from 0 to 1. */
  opacity = 1;
  /** Whether the layer's vertical values are read on the chart's second axis, on the right. */
  secondaryAxis = false;

  abstract plan(context: PlanContext): LayerPlan;

  /** What kind of layer this is, as the C# type is named. */
  get typeName(): string {
    return this.constructor.name;
  }

  /** A short description for a chart's text form. */
  describe(): string {
    return this.label ? `${this.typeName} '${this.label}'` : this.typeName;
  }
}

/** What a Drawing draws with: the sink, already moved and scaled to where the drawing goes, and the theme. */
export interface DrawingContext {
  readonly sink: Sink;
  readonly theme: Theme;
  /** Figure pixels per drawing pixel: 1, or less where the drawing was scaled down to fit. */
  readonly scale: number;
  readonly surface: Colour;
  note(sentence: string): void;
}

/**
 * A layer that is a picture laid out by the code that made it - a diagram, a board - drawn in its chart's plotting area at its own
 * size, or scaled down to fit a smaller area, and centred. A drawing is never enlarged: its words are set at the sizes it was laid
 * out with, and a figure larger than the drawing leaves room round it.
 */
export abstract class DrawingLayer extends Layer {
  /** The drawing's width at its own size, in figure pixels. */
  abstract get width(): number;
  /** The drawing's height at its own size, in figure pixels. */
  abstract get height(): number;
  /** Draws the drawing at its own size, with its top left corner at the origin of the context's sink. */
  protected abstract draw(context: DrawingContext): void;
  /** What the drawing is, in a word or two. */
  get kind(): string {
    return "Drawing";
  }

  override describe(): string {
    return this.label ? `${this.kind} '${this.label}'` : this.kind;
  }

  /** The scale a drawing is drawn at in an area: 1, or less to fit a smaller area. */
  static scaleToFit(width: number, height: number, areaWidth: number, areaHeight: number): number {
    return Math.max(0.01, Math.min(1, Math.min(areaWidth / Math.max(1e-9, width), areaHeight / Math.max(1e-9, height))));
  }

  plan(): LayerPlan {
    if (!(this.width > 0) || !(this.height > 0) || !Number.isFinite(this.width) || !Number.isFinite(this.height))
      throw new Error(`A drawing must have a width and a height above zero; this one is ${this.width} by ${this.height}.`);
    return {
      layer: this,
      frame: "free",
      clipToPlot: false,
      draw: (context: DrawContext) => {
        const area = context.plot;
        const scale = DrawingLayer.scaleToFit(this.width, this.height, area.width, area.height);
        const left = area.left + (area.width - this.width * scale) / 2;
        const top = area.top + (area.height - this.height * scale) / 2;
        const saved = context.sink.save();
        try {
          context.sink.translate(left, top);
          context.sink.scale(scale, scale);
          this.draw({
            sink: context.sink,
            theme: context.theme,
            scale,
            surface: context.surface,
            note: (sentence) => {
              if (sentence.trim() && !context.notes.includes(sentence)) context.notes.push(sentence);
            },
          });
        } finally {
          context.sink.restoreToCount(saved);
        }
      },
    };
  }
}

/**
 * One chart: layers of marks drawn over shared axes, with a legend and a title. A chart is a value: change it with a spread. Its
 * axes, colour scale and legend are settings of plot/axis, unset for a chart that has none (a diagram), which reads as their
 * defaults.
 */
export interface Chart {
  readonly layers: readonly Layer[];
  readonly title?: string | null;
  /** The horizontal axis. */
  readonly x?: Axis;
  /** The vertical axis. */
  readonly y?: Axis;
  /** The second vertical axis, on the right, used by layers placed on it. */
  readonly y2?: Axis;
  /** How a colour channel bound to data becomes colours. */
  readonly color?: ColorScale;
  /** The legend. */
  readonly legend?: Legend;
  /** The plotting area's background, instead of the theme's. */
  readonly plotBackground?: Colour | null;
  /** Whether one unit along x is as long on screen as one unit along y. */
  readonly equalAspect?: boolean;
  readonly [extra: string]: unknown;
}

export function chartOf(...layers: Layer[]): Chart {
  return { layers };
}

/** A finished picture: one chart or a grid of them, with a title, a caption, a size and a theme. */
export interface Figure {
  /** The figure's width, in 96-dpi pixels. */
  readonly width: number;
  /** The figure's height, in 96-dpi pixels. */
  readonly height: number;
  /** The charts, filling the grid row by row. */
  readonly charts: readonly Chart[];
  /** How many charts sit side by side; 0 picks a near-square grid. */
  readonly columns: number;
  readonly title: string | null;
  /** A line under the title saying what the figure shows. */
  readonly subtitle: string | null;
  /** A note at the foot: the source, a definition, a caveat. */
  readonly caption: string | null;
  readonly theme: Theme;
}

export function figureOf(...charts: Chart[]): Figure {
  return { width: 640, height: 400, charts, columns: 0, title: null, subtitle: null, caption: null, theme: Light };
}

/** This figure at another size, in 96-dpi pixels. */
export function withSize(figure: Figure, width: number, height: number): Figure {
  if (!(width >= 1) || !(height >= 1)) throw new Error(`A figure must be at least one pixel each way; ${width} by ${height} is not.`);
  return { ...figure, width, height };
}

/** The grid the charts are arranged in: columns and rows. */
export function gridOf(figure: Figure): { columns: number; rows: number } {
  const count = Math.max(1, figure.charts.length);
  const columns = figure.columns > 0 ? Math.min(figure.columns, count) : Math.ceil(Math.sqrt(count));
  return { columns, rows: Math.ceil(count / columns) };
}

// ---------------------------------------------------------------- rendering

/** A chart's legend as the renderer lays it out: whether there is anything in it, how big it is, and how it draws (a LegendPainter of plot/legend-painter). */
export interface PlanLegend {
  readonly isEmpty: boolean;
  measureColumn(maxHeight: number): { width: number; height: number };
  measureRow(maxWidth: number): { width: number; height: number };
  drawColumn(sink: Sink, box: RectF): void;
  drawRows(sink: Sink, box: RectF): void;
}

/** One chart's plan: its layers made ready, its frame - and, once a chart's machinery has trained it, its axes, colours and legend. */
export interface ChartPlan {
  readonly chart: Chart;
  readonly layers: LayerPlan[];
  readonly frame: FrameKind;
  /** The colour each one-series layer was dealt while it was planned. */
  readonly seriesColors: Map<Layer, Colour>;
  /** The legend, empty until a chart's machinery collects one. */
  legend: PlanLegend;
  /** Whatever the machinery adds to the context its layers are drawn with: the chart's colours. */
  drawExtras: Record<string, unknown>;
  [extra: string]: unknown;
}

/** What a render made: the figure's size, and anything it approximated or left out, in plain sentences. */
export interface FigureRendering {
  readonly width: number;
  readonly height: number;
  readonly notes: readonly string[];
}

/** The renderer's own state, for a frame drawing one chart in its cell. */
export interface FigureJob {
  readonly figure: Figure;
  readonly sink: Sink;
  readonly theme: Theme;
  readonly text: TextPainter;
  readonly notes: string[];
  readonly measurer: TextMeasurer;
  /** The draw context for a chart's plotting area, with the chart's colours and whatever the frame adds. */
  context(plan: ChartPlan, plot: RectF, extra?: Record<string, unknown>): DrawContext;
  /** The room left for a frameless chart's plotting area once its title and legend have theirs. */
  reserve(plan: ChartPlan, cell: RectF): { area: RectF; legend: RectF | null; titleTop: number };
  /** Draws a chart's title, and its legend in the box reserved for it. */
  drawLegendAndTitle(plan: ChartPlan, cell: RectF, plot: RectF, legend: RectF | null, titleTop: number): void;
}

/**
 * What charts with axes, spokes or legends need beyond a drawing: training each chart's axes, colours and legend from its layers,
 * and drawing the frames with axes and spokes. The chart kinds' module registers it (plot/frames), so a page that draws only diagrams
 * carries none of it: a drawing binds nothing to axes, and its one legend entry would make no legend.
 */
export interface Charting {
  /** Trains every chart of the figure: its layers' values bound to its axes and colours, the axes resolved, the legend collected. */
  train(job: FigureJob, plans: ChartPlan[]): void;
  /** Draws one chart of a frame with axes or spokes in its cell. */
  draw(job: FigureJob, plan: ChartPlan, cell: RectF): void;
}

let charting: Charting | null = null;

/** Registers the machinery of charts with axes, spokes and legends. */
export function registerCharting(machinery: Charting): void {
  charting = machinery;
}

const noLegend: PlanLegend = {
  isEmpty: true,
  measureColumn: () => ({ width: 0, height: 0 }),
  measureRow: () => ({ width: 0, height: 0 }),
  drawColumn: () => {},
  drawRows: () => {},
};

/** What a layer is told while it is planned: one per chart, so each chart deals its palette from the first colour. */
function planContext(theme: Theme, palette: Palette, notes: string[], measurer: TextMeasurer): PlanContext {
  const assigned = new Map<Layer, Colour>();
  let nextSlot = 0;
  return {
    theme,
    palette,
    notes,
    measurer,
    assigned,
    seriesColor(layer: Layer): Colour {
      if (layer.color) {
        assigned.set(layer, layer.color);
        return layer.color;
      }
      if (nextSlot === palette.colors.length)
        notes.push(`There are more series than the ${palette.colors.length} colours of the ${palette.name} palette, so colours repeat; the legend tells them apart, and small multiples may read better.`);
      const colour = palette.at(nextSlot++);
      assigned.set(layer, colour);
      return colour;
    },
  };
}

function describeFrame(frame: FrameKind): string {
  return frame === "cartesian" ? "an x-y" : frame === "polar" ? "a radial" : "a free-standing";
}

/**
 * Lays a figure out and draws it onto a sink. The order is fixed and every step is deterministic: each chart's layers are planned
 * and trained; the figure is divided into its title, its grid of charts and its caption; each chart measures its legend and its
 * axes' labels for the room it has, and what remains is its plotting area; then everything is drawn once, back to front.
 */
export function renderFigure(figure: Figure, sink: Sink, measurer: TextMeasurer, options: { paintBackground?: boolean; clipToFigure?: boolean } = {}): FigureRendering {
  const theme = figure.theme;
  const text = new TextPainter(theme, measurer);
  const notes: string[] = [];
  const width = figure.width;
  const height = figure.height;

  const job: FigureJob = {
    figure,
    sink,
    theme,
    text,
    notes,
    measurer,
    context(plan, plot, extra = {}) {
      return { sink, theme, text, plot, notes, deviceScale: 0, surface: theme.background, ...plan.drawExtras, ...extra };
    },
    reserve(plan, cell) {
      let top = cell.top;
      const titleTop = top;
      if (plan.chart.title) top += text.lineHeight("chartTitle") + theme.textGap;
      let area = new RectF(cell.left, top, cell.right, cell.bottom);
      let legendBox: RectF | null = null;
      if (!plan.legend.isEmpty) {
        const gap = theme.textGap * 2;
        const position = plan.chart.legend?.position ?? "right";
        if (position === "right") {
          const size = plan.legend.measureColumn(area.height);
          legendBox = RectF.fromXYWH(area.right - size.width, area.midY - size.height / 2, size.width, size.height);
          area = new RectF(area.left, area.top, area.right - size.width - gap, area.bottom);
        } else if (position === "left") {
          const size = plan.legend.measureColumn(area.height);
          legendBox = RectF.fromXYWH(area.left, area.midY - size.height / 2, size.width, size.height);
          area = new RectF(area.left + size.width + gap, area.top, area.right, area.bottom);
        } else if (position === "top") {
          const size = plan.legend.measureRow(area.width);
          legendBox = RectF.fromXYWH(area.left, area.top, area.width, size.height);
          area = new RectF(area.left, area.top + size.height + gap, area.right, area.bottom);
        } else if (position === "bottom") {
          const size = plan.legend.measureRow(area.width);
          legendBox = RectF.fromXYWH(area.left, area.bottom - size.height, area.width, size.height);
          area = new RectF(area.left, area.top, area.right, area.bottom - size.height - gap);
        } else {
          const size = plan.legend.measureColumn(area.height / 2);
          legendBox = insideBox(position, area, size);
        }
      }
      return { area, legend: legendBox, titleTop };
    },
    drawLegendAndTitle(plan, cell, plot, legendBox, titleTop) {
      if (plan.chart.title) text.draw(sink, plan.chart.title, Math.max(cell.left, plot.left), titleTop, "chartTitle", theme.ink, "topLeft");
      if (!legendBox || plan.legend.isEmpty) return;
      let box = legendBox;
      const position = plan.chart.legend?.position ?? "right";
      if (position === "insideTopLeft" || position === "insideTopRight" || position === "insideBottomLeft" || position === "insideBottomRight") {
        box = insideBox(position, plot, { width: box.width, height: box.height });
        const backing = box.inflate(6);
        const background = theme.background;
        sink.drawRect(backing, { colour: { ...background, a: Math.round(background.a * 0.85) }, style: "fill" });
      }
      if (position === "top" || position === "bottom") plan.legend.drawRows(sink, box);
      else plan.legend.drawColumn(sink, box);
    },
  };

  const saved = sink.save();
  try {
    if (options.clipToFigure ?? true) sink.clipRect(new RectF(0, 0, width, height));
    if (options.paintBackground ?? true) sink.drawRect(new RectF(0, 0, width, height), { colour: theme.background, style: "fill" });

    const plans: ChartPlan[] = figure.charts.map((chart) => {
      const context = planContext(theme, chart.color?.palette ?? theme.palette, notes, measurer);
      const layers = chart.layers.map((layer) => layer.plan(context));
      const frame: FrameKind = layers.length === 0 ? "cartesian" : layers[0].frame;
      for (const layer of layers)
        if (layer.frame !== frame) throw new Error(`A ${describeFrame(layer.frame)} layer (${layer.layer.describe()}) cannot share a chart with a ${describeFrame(frame)} one; give it a chart of its own.`);
      return { chart, layers, frame, seriesColors: context.assigned, legend: noLegend, drawExtras: {} };
    });
    charting?.train(job, plans);

    // The figure's own text: title and subtitle above, caption below, all aligned to the padding.
    const pad = theme.padding;
    const content = new RectF(pad, pad, width - pad, height - pad);
    let top = content.top;
    if (figure.title) {
      text.draw(sink, figure.title, content.left, top, "figureTitle", theme.ink, "topLeft");
      top += text.measure(figure.title, "figureTitle").height + 2;
    }
    if (figure.subtitle) {
      text.draw(sink, figure.subtitle, content.left, top, "subtitle", theme.secondaryInk, "topLeft");
      top += text.measure(figure.subtitle, "subtitle").height;
    }
    if (top > content.top) top += theme.textGap * 2;
    let bottom = content.bottom;
    if (figure.caption) {
      const captionHeight = text.measure(figure.caption, "caption").height;
      text.draw(sink, figure.caption, content.left, content.bottom, "caption", theme.mutedInk, "bottomLeft");
      bottom -= captionHeight + theme.textGap * 2;
    }

    const area = new RectF(content.left, top, content.right, Math.max(top + 1, bottom));
    drawCharts(job, plans, area);
    return { width, height, notes };
  } finally {
    sink.restoreToCount(saved);
  }
}

/** Where a legend inside the plotting area goes. */
export function insideBox(position: string, plot: RectF, size: { width: number; height: number }): RectF {
  const inset = 10;
  const left = position === "insideTopLeft" || position === "insideBottomLeft" ? plot.left + inset : plot.right - inset - size.width;
  const top = position === "insideTopLeft" || position === "insideTopRight" ? plot.top + inset : plot.bottom - inset - size.height;
  return RectF.fromXYWH(left, top, size.width, size.height);
}

/** The cell each chart takes in the figure's grid, row by row. */
function drawCharts(job: FigureJob, plans: ChartPlan[], area: RectF): void {
  const { sink, theme, text } = job;
  if (plans.length === 0) {
    text.draw(sink, "No charts", area.midX, area.midY, "dataLabel", theme.mutedInk, "center");
    return;
  }
  const { columns, rows } = gridOf(job.figure);
  const gap = theme.chartGap;
  const cellWidth = (area.width - gap * (columns - 1)) / columns;
  const cellHeight = (area.height - gap * (rows - 1)) / rows;
  const cellOf = (index: number): RectF => {
    const column = index % columns;
    const row = Math.floor(index / columns);
    const left = area.left + column * cellWidth + column * gap;
    const top = area.top + row * cellHeight + row * gap;
    return new RectF(left, top, left + cellWidth, top + cellHeight);
  };
  // Charts sharing an axis would be measured together first so their plotting areas line up; a Dhole figure shares none, so each chart is measured in its own cell as it is drawn.
  plans.forEach((plan, i) => {
    const cell = cellOf(i);
    if (plan.frame === "free") drawFree(job, plan, cell);
    else {
      if (!charting) throw new Error(`This page cannot draw ${describeFrame(plan.frame)} chart: the chart kinds were not loaded.`);
      charting.draw(job, plan, cell);
    }
  });
}

function drawFree(job: FigureJob, plan: ChartPlan, cell: RectF): void {
  const { area, legend, titleTop } = job.reserve(plan, cell);
  const context = job.context(plan, area);
  for (const layer of plan.layers) {
    const saved = job.sink.save();
    try {
      if (layer.clipToPlot) job.sink.clipRect(area.inflate(2));
      layer.draw(context);
    } finally {
      job.sink.restoreToCount(saved);
    }
  }
  job.drawLegendAndTitle(plan, cell, area, legend, titleTop);
}

/**
 * The figure at the size that gives each of its charts a plotting area of `plotWidth` by `plotHeight` once the figure's titles and
 * caption and each chart's title have their room - for charts whose content has a size of its own, such as a drawing. Legends and
 * axes are not counted: a chart that has them takes whatever room it is given and lays them out in that. A title wider than the
 * charts widens the figure, so it is not cut at the edge.
 */
export function sizedFor(figure: Figure, plotWidth: number, plotHeight: number, measurer: TextMeasurer): Figure {
  const theme = figure.theme;
  const text = new TextPainter(theme, measurer);
  const pad = theme.padding;
  // The arithmetic renderFigure and reserve lay a figure out with, run backwards.
  let top = 0;
  let widest = 0;
  if (figure.title) {
    const size = text.measure(figure.title, "figureTitle");
    top += size.height + 2;
    widest = Math.max(widest, size.width);
  }
  if (figure.subtitle) {
    const size = text.measure(figure.subtitle, "subtitle");
    top += size.height;
    widest = Math.max(widest, size.width);
  }
  if (top > 0) top += theme.textGap * 2;
  let bottom = 0;
  if (figure.caption) {
    const size = text.measure(figure.caption, "caption");
    bottom = size.height + theme.textGap * 2;
    widest = Math.max(widest, size.width);
  }
  const { columns, rows } = gridOf(figure);
  const chartTitle = figure.charts.some((chart) => !!chart.title) ? text.lineHeight("chartTitle") + theme.textGap : 0;
  const width = columns * plotWidth + (columns - 1) * theme.chartGap + 2 * pad;
  const height = rows * (plotHeight + chartTitle) + (rows - 1) * theme.chartGap + top + bottom + 2 * pad;
  return withSize(figure, Math.ceil(Math.max(width, widest + 2 * pad)), Math.ceil(Math.max(1, height)));
}
