// Outlines, arrowheads and curves, in the diagram's pixels.
// Ported from Parcel NExT's Divooka.Visualization.Dhole/Rendering/Shapes.cs.

import type { Head } from "../syntax/scan";
import { RectF, VectorPath, add, lengthSquared, mul, normalize, sub, vec, type Vec2 } from "./geometry";

/** The outlines a box in a diagram can have. */
export type NodeShape =
  /** A rectangle with softened corners: a step. */
  | "box"
  /** A rectangle with well-rounded corners: a state, a gentle step. */
  | "round"
  /** A rectangle with round ends: where a flow starts or stops. */
  | "pill"
  | "circle"
  /** A rhombus: a question. */
  | "diamond"
  /** A hexagon: preparation. */
  | "hexagon"
  /** A slanted box: data in or out. */
  | "parallelogram"
  /** A cylinder: a store of data. */
  | "cylinder"
  /** A sheet with a wavy foot: a document. */
  | "document"
  /** A box with a second line at each side: a step defined elsewhere. */
  | "subroutine"
  /** A sheet with a folded corner: a note. */
  | "note"
  /** A small filled circle: a state machine's start. */
  | "startDot"
  /** A small ringed circle: a state machine's end. */
  | "endDot"
  /** A short thick bar: where a flow forks or joins. */
  | "bar"
  /** A plain rectangle with square corners: a class, an entity. */
  | "square";

/** The size of a box of `shape` that holds text of `text` with `padX` and `padY` round it. */
export function fit(shape: NodeShape, text: { width: number; height: number }, padX: number, padY: number): { width: number; height: number } {
  const w = text.width + 2 * padX;
  const h = text.height + 2 * padY;
  const square = (side: number) => ({ width: side, height: side });
  switch (shape) {
    // The smallest rhombus round a rectangle is twice its width and twice its height; a little less reads well, since a label's corners are rarely full.
    case "diamond":
      return { width: Math.max(w * 1.6, h * 2.2), height: Math.max(h * 1.8, 44) };
    case "circle":
      return square(Math.max(w, h) * 1.12);
    case "pill":
      return { width: w + h * 0.6, height: h };
    case "hexagon":
      return { width: w + h * 0.8, height: h };
    case "parallelogram":
      return { width: w + h * 0.6, height: h };
    case "cylinder":
      return { width: w, height: h + 14 };
    case "document":
      return { width: w, height: h + 8 };
    case "subroutine":
      return { width: w + 16, height: h };
    case "note":
      return { width: w + 6, height: h };
    case "startDot":
      return square(20);
    case "endDot":
      return square(22);
    case "bar":
      return { width: Math.max(80, w), height: 7 };
    default:
      return { width: w, height: h };
  }
}

/** The outline of a box of `shape` filling `box`. */
export function outline(shape: NodeShape, box: RectF): VectorPath {
  const path = new VectorPath();
  const l = box.left;
  const t = box.top;
  const r = box.right;
  const b = box.bottom;
  const w = box.width;
  const h = box.height;
  switch (shape) {
    case "round":
      path.addRoundRect(box, Math.min(14, h / 2), Math.min(14, h / 2));
      break;
    case "pill":
      path.addRoundRect(box, h / 2, h / 2);
      break;
    case "circle":
    case "startDot":
    case "endDot":
      path.addOval(box);
      break;
    case "diamond":
      path.moveTo(box.midX, t).lineTo(r, box.midY).lineTo(box.midX, b).lineTo(l, box.midY).close();
      break;
    case "hexagon": {
      const inset = Math.min(h * 0.4, w / 4);
      path.moveTo(l + inset, t).lineTo(r - inset, t).lineTo(r, box.midY).lineTo(r - inset, b).lineTo(l + inset, b).lineTo(l, box.midY).close();
      break;
    }
    case "parallelogram": {
      const slant = Math.min(h * 0.3, w / 5);
      path.moveTo(l + slant, t).lineTo(r, t).lineTo(r - slant, b).lineTo(l, b).close();
      break;
    }
    case "cylinder": {
      const ry = 6;
      path.moveTo(l, t + ry);
      path.arcTo(new RectF(l, t, r, t + 2 * ry), 180, 180, false);
      path.lineTo(r, b - ry);
      path.arcTo(new RectF(l, b - 2 * ry, r, b), 0, 180, false);
      path.close();
      // The near rim of the top, so the cylinder reads as one.
      path.moveTo(l, t + ry);
      path.arcTo(new RectF(l, t, r, t + 2 * ry), 180, -180, false);
      break;
    }
    case "document": {
      const wave = 7;
      path.moveTo(l, t).lineTo(r, t).lineTo(r, b - wave);
      path.cubicTo(vec(r - w * 0.25, b - wave * 2.2), vec(l + w * 0.45, b + wave * 0.6), vec(l, b - wave * 0.4));
      path.close();
      break;
    }
    case "subroutine":
      path.addRect(box);
      path.moveTo(l + 7, t).lineTo(l + 7, b);
      path.moveTo(r - 7, t).lineTo(r - 7, b);
      break;
    case "note": {
      const fold = Math.min(10, h / 3);
      path.moveTo(l, t).lineTo(r - fold, t).lineTo(r, t + fold).lineTo(r, b).lineTo(l, b).close();
      path.moveTo(r - fold, t).lineTo(r - fold, t + fold).lineTo(r, t + fold);
      break;
    }
    case "bar":
      path.addRoundRect(box, 2, 2);
      break;
    case "square":
      path.addRect(box);
      break;
    default:
      path.addRoundRect(box, 5, 5);
      break;
  }
  return path;
}

/** Where a line from the box's centre toward `toward` leaves the outline of `shape`. */
export function boundary(shape: NodeShape, box: RectF, toward: Vec2): Vec2 {
  const c = vec(box.midX, box.midY);
  const d = sub(toward, c);
  if (lengthSquared(d) < 1e-6) return c;
  const hw = box.width / 2;
  const hh = box.height / 2;
  switch (shape) {
    case "circle":
    case "startDot":
    case "endDot": {
      // An ellipse: scale the direction onto it.
      const k = 1 / Math.sqrt((d.x * d.x) / (hw * hw) + (d.y * d.y) / (hh * hh));
      return add(c, mul(d, k));
    }
    case "diamond": {
      const k = 1 / (Math.abs(d.x) / hw + Math.abs(d.y) / hh);
      return add(c, mul(d, k));
    }
    default: {
      const kx = Math.abs(d.x) < 1e-6 ? Number.MAX_VALUE : hw / Math.abs(d.x);
      const ky = Math.abs(d.y) < 1e-6 ? Number.MAX_VALUE : hh / Math.abs(d.y);
      return add(c, mul(d, Math.min(kx, ky)));
    }
  }
}

/**
 * A line's end moved along the flow onto the outline of `shape`: a port the layout placed on the box's flat side, slid onto a
 * diamond's slope or a circle's curve. `vertical`: whether the diagram flows down or up the page, so ports sit on the top and bottom.
 */
export function onOutline(shape: NodeShape, box: RectF, port: Vec2, vertical: boolean): Vec2 {
  const hw = box.width / 2;
  const hh = box.height / 2;
  const cx = box.midX;
  const cy = box.midY;
  // Across the flow, how far the port is from the middle; along it, which side it is on.
  const across = vertical ? port.x - cx : port.y - cy;
  const half = vertical ? hw : hh;
  const depth = vertical ? hh : hw;
  const side = vertical ? Math.sign(port.y - cy) : Math.sign(port.x - cx);
  if (side === 0 || half <= 0) return port;
  const t = Math.min(Math.max(Math.abs(across) / half, 0), 1);
  let reach: number;
  switch (shape) {
    case "diamond":
      reach = depth * (1 - t);
      break;
    case "circle":
    case "startDot":
    case "endDot":
      reach = depth * Math.sqrt(Math.max(0, 1 - t * t));
      break;
    case "pill":
      reach = vertical ? pillReach(Math.abs(across), hw, hh) : depth;
      break;
    default:
      reach = depth;
  }
  return vertical ? vec(port.x, cy + side * reach) : vec(cx + side * reach, port.y);
}

function pillReach(distance: number, hw: number, hh: number): number {
  // The flat stretch of a pill's long side reaches its full depth; past it the round end falls away.
  const flat = hw - hh;
  if (distance <= flat) return hh;
  const d = distance - flat;
  return Math.sqrt(Math.max(0, hh * hh - d * d));
}

/**
 * A line through `points`, curving between each pair so it leaves and arrives along the direction diagrams flow in - down the
 * page, or across it. Each piece is a cubic whose handles run along that direction for half the piece, as D3's bump curves do;
 * neighbouring pieces share their tangent where they meet, so a long edge through its waypoints is one smooth line.
 */
export function bump(points: readonly Vec2[], vertical: boolean): VectorPath {
  const path = new VectorPath();
  if (points.length === 0) return path;
  path.moveTo(points[0]);
  for (let i = 1; i < points.length; i++) {
    const a = points[i - 1];
    const b = points[i];
    // Two ends less than a pixel out of line are one straight line: a cubic between them is flattened into short pieces a hair apart, whose overlapping ends dot the line.
    if (Math.abs(vertical ? b.x - a.x : b.y - a.y) < 1) {
      path.lineTo(vertical ? vec(a.x, b.y) : vec(b.x, a.y));
      continue;
    }
    if (vertical) {
      const my = (a.y + b.y) / 2;
      path.cubicTo(vec(a.x, my), vec(b.x, my), b);
    } else {
      const mx = (a.x + b.x) / 2;
      path.cubicTo(vec(mx, a.y), vec(mx, b.y), b);
    }
  }
  return path;
}

/** A straight line through `points`. */
export function polyline(points: readonly Vec2[]): VectorPath {
  const path = new VectorPath();
  points.forEach((p, i) => (i === 0 ? path.moveTo(p) : path.lineTo(p)));
  return path;
}

/** How far an end of `head` reaches back along its line, so the line can stop where the head begins. */
export function headLength(head: Head, size: number): number {
  switch (head) {
    case "arrow":
      return size;
    case "triangle":
      return size * 1.25;
    case "diamond":
    case "hollowDiamond":
      return size * 1.9;
    default:
      return 0;
  }
}

/** An end of a line: its outline with its point at `tip` facing along `direction`, and whether it is filled with the line's colour (rather than the background, with an outline). */
export function end(head: Head, tip: Vec2, direction: Vec2, size: number): { path: VectorPath; filled: boolean } | null {
  if (head === "none") return null;
  const u = normalize(lengthSquared(direction) < 1e-9 ? vec(0, 1) : direction);
  const n = vec(-u.y, u.x);
  const path = new VectorPath();
  switch (head) {
    case "arrow": {
      const back = sub(tip, mul(u, size));
      path.moveTo(tip).lineTo(add(back, mul(n, size * 0.5))).lineTo(sub(back, mul(u, -size * 0.12))).lineTo(sub(back, mul(n, size * 0.5))).close();
      return { path, filled: true };
    }
    case "triangle": {
      const back = sub(tip, mul(u, size * 1.25));
      path.moveTo(tip).lineTo(add(back, mul(n, size * 0.62))).lineTo(sub(back, mul(n, size * 0.62))).close();
      return { path, filled: false };
    }
    default: {
      const half = size * 0.95;
      const mid = sub(tip, mul(u, half));
      path.moveTo(tip).lineTo(add(mid, mul(n, size * 0.48))).lineTo(sub(tip, mul(u, half * 2))).lineTo(sub(mid, mul(n, size * 0.48))).close();
      return { path, filled: head === "diamond" };
    }
  }
}
